long long C[51][51];

int popcount(int n, long long I)
{
  int c=0;
  for(int x=0;x<n;x++){
    c+=((I>>x)&1);
  }
  return c;
}


int main()
{
  int n,K;
  scanf("%d%d",&n,&K);
  for(int i=0;i<=n;i++){
    C[i][0]=C[i][i]=1ll;
    for(int j=1;j<i;j++){
      C[i][j]=C[i-1][j-1]+C[i-1][j];
    }
  }
  int S,T;
  scanf("%d%d",&S,&T);
  std::vector<int> A(n);
  for(int i=0;i<n;i++){
    scanf("%d",&A[i]);
  }
  std::vector<long long> M(18,0ll);
  for(int j=0;j<18;j++){
    for(int i=0;i<n;i++){
      if((A[i]>>j)&1){
	//printf("%d %d\n",i,j);
	M[j]|=(1ll<<i);
      }
    }
  }
  std::queue<std::pair<int,long long> > Q;
  Q.push(std::make_pair(1,(1ll<<n)-1ll));
  for(int i=0;i<18;i++){
    std::queue<std::pair<int,long long> > NQ;
    while(!Q.empty()){
      int sg=Q.front().first;
      long long I=Q.front().second;
      Q.pop();
      //printf("%d %d %lld %lld\n",i,sg,I,M[i]);
      if(((T>>i)&1)==0){
	I&=~M[i];
      }
      if(((S>>i)&1)==1){
	I&=M[i];
      }
      if(I==0)
	continue;
      NQ.push(std::make_pair(sg,I));
      if(((T>>i)&1)==1&&(I&(~M[i]))!=0){
	NQ.push(std::make_pair(-sg,I&(~M[i])));	
      }
      if(((S>>i)&1)==0&&(I&M[i])!=0){
	NQ.push(std::make_pair(-sg,I&M[i]));	
      }
    }
    Q=NQ;
  }
  long long ans=0ll;
  while(!Q.empty()){
    int sg=Q.front().first,I=Q.front().second;
    Q.pop();
    int p=popcount(n,I);
    for(int x=1;x<=K;x++){
      ans+=sg*C[p][x];
    }
  }
  printf("%lld\n",ans);
  return 0;
}

