const int MAXN = (1<<18);
const int N = 50;

unordered_map<ll, ll> dp[51][51];

int n, k, s, t;
int a[N + 5], occ[N + 5];

bool death(int a, int b) {
	int ab = (a & b);
	return (ab ^ a);
}

bool deathlagi(int a, int b) {
	int ab = (a & b);
	return (ab ^ b);
}

ll solve(int idx, int pk, ll btand, ll btsisa) {
	ll bval = (btand | btsisa);
	if(death(bval, t) || deathlagi(btand, s)) return 0;
	if(pk > k) return 0;
	if(idx == n + 1) {
		if(btand != s || (btand | btsisa) != t) return 0;
		return 1;
	}
	if(dp[idx][pk].find((btand << 18) + btsisa) != dp[idx][pk].end()) return dp[idx][pk][(btand << 18) + btsisa];
	ll res = 0;
	//pick
	if(pk == 0) {
		for(int j = 1;j <= occ[idx];j++) res += solve(idx + 1, pk + j, a[idx], a[idx]);
	}
	else {
		int bvalsisa = (btsisa | btand | a[idx]);
		int bvaland = (btand & a[idx]);
		for(int j = 1;j <= occ[idx];j++) res += solve(idx + 1, pk + j, bvaland, (bvaland ^ bvalsisa));
	}
	//not pick
	res += solve(idx + 1, pk, btand, btsisa);
//	cout<<"AT "<<idx<<" "<<pk<<" "<<btand<<" "<<btsisa<<" "<<res<<endl;
	return dp[idx][pk][(btand << 18) + btsisa] = res;
}

