typedef unsigned long long u64;
const int N=50;
int n, k, s, t, a[N], cnt;
u64 set[2*N], com[N+1][N+1], ans;
void dfs(int x, int nmust, int nmay, u64 must, u64 may) {
	if(nmust>k) return;
	while(x<cnt && (set[x]&must)) ++x;
	if(x==cnt) {
		int tmp=std::min(k, nmay)-nmust;
		ans+=com[nmay-nmust][tmp];
		return;
	}
	u64 cur=set[x]&may;
	if(cur==0) return;
	u64 j;
	for(; cur; cur^=j) {
		j = cur&-cur;
		dfs(x+1, nmust+1, nmay, must|j, may);
		--nmay;
		may^=j;
	}
}
void gg() {
	puts("0");
	exit(0);
}
int main() {
	std::random_device dev;
	std::mt19937 rng(dev());
	scanf("%d%d%d%d", &n, &k, &s, &t);
	for(int i=0; i<n; ++i) {
		scanf("%d", a+i);
		if((a[i]&s)!=s || (a[i]|t)!=t) {
			--i;
			--n;
		}
	}
	if(n==0) gg();
	for(int i=0; i<=n; ++i) {
		com[i][0]=com[i][i]=1;
		for(int j=1; j<i; ++j)
			com[i][j]=com[i-1][j-1]+com[i-1][j];
	}
	for(int i=0; i<=n; ++i) {
		for(int j=1; j<=i; ++j)
			com[i][j]+=com[i][j-1];
	}
	for(int i=0; i<18; ++i) {
		int ss=s>>i&1, tt=t>>i&1;
		if(ss!=tt) {
			u64 cur=0;
			for(int j=0; j<n; ++j) {
				if(~a[j]>>i&1) cur|=1llu<<j;
			}
			set[cnt++]=cur;
			if(!cur) gg();
			cur=0;
			for(int j=0; j<n; ++j) {
				if(a[j]>>i&1) cur|=1llu<<j;
			}
			set[cnt++]=cur;
			if(!cur) gg();
		}
	}
	dfs(0, 0, n, 0, (1llu<<n)-1);
	printf("%llu\n", ans);
	return 0;
}

