#include <bits/stdc++.h>

using namespace std;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n, k, s, t;
  cin >> n >> k >> s >> t;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }
  if ((t & s) != s) {
    cout << 0 << '\n';
    return 0;
  }
  vector<vector<long long>> C(n + 1, vector<long long>(n + 1));
  for (int i = 0; i <= n; i++) {
    C[i][0] = 1;
    for (int j = 1; j <= i; j++) {
      C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
    }
  }
  vector<long long> ways(n + 1);
  for (int i = 0; i <= n; i++) {
    for (int j = 1; j <= min(i, k); j++) {
      ways[i] += C[i][j];
    }
  }
  vector<int> b;
  long long ans = 0;
  for (int mask = 0; mask < (1 << 18); mask++) {
    if ((mask & (t ^ s)) != mask) {
      continue;
    }
    int sign = (__builtin_popcount(mask) % 2 == 0 ? 1 : -1);
    b.clear();
    for (int i = 0; i < n; i++) {
      if ((a[i] & s) != s) {
        continue;
      }
      if ((a[i] | t) != t) {
        continue;
      }
      b.push_back(a[i] & mask);
    }
    sort(b.begin(), b.end());
    int beg = 0;
    while (beg < (int) b.size()) {
      int end = beg;
      while (end + 1 < (int) b.size() && b[end + 1] == b[end]) {
        ++end;
      }
      ans += sign * ways[end - beg + 1];
      beg = end + 1;
    }
  }
  cout << ans << '\n';
  return 0;
}

