void solve(){
  inl(N,K,S,T);
  vl A(N); in(A);

  #ifdef NyaanDebug
    ll bns = 0;
    rep(i,1<<N){
      if(popcnt(i)>K)continue;
      ll s = 262143, t = 0;
      rep(j,N) if(getbit(i,j)) s &= A[j], t |= A[j];
      if(s == S and t == T) bns++;
    }
    trc(bns);
  #endif

  if((T & S) != S) die(0);

  // S
  vl B;
  each(x,A) if((x & S) == S and (x & (~T)) == 0) B.pb(x);
  swap(A,B);
  N=sz(A);
  if(N==0)die(0);
  trc(N,A);

  // N個からK個を選ぶ
  dp[0][0] = 1;
  rep(i,N) rep(j,K+1){
    dp[i+1][j] += dp[i][j];
    dp[i+1][j+1] += dp[i][j];
  }
  // rui
  vl ntok(N + 1);
  rep1(n,N)rep1(k,K) ntok[n]+=dp[n][k];

