  }
  */

  //trca(d,16);
  //trca(u,16);
  //trc(ntok);

  ll ans = ntok[N];
  rep(i, 262144){
    if(i == 0) continue;
    if((i & (~T)) != 0) continue;
    if((i & S) != 0) continue;
    int parity = popcnt(i) & 1;
    unordered_map<ll,int> m;
    each(x,A) m[x & i]++;
    ll cur = 0;
    each(p,m) cur += ntok[p.second];
    //trc(i,cur);
    ans += (parity ? -1 : 1) * cur;
  }
  out(ans);

}

