	}

	//repn(j, M)cout << b[j] << endl;


	vector<map<ll, ll>> dp(M + 1);
	dp[0][0] = (1 << N) - 1;

	repn(i, M) {

		for (auto x : dp[i-1]) {
			ll j = x.first;
			if (dp[i - 1][j] > 0)dp[i][3 * j] = dp[i - 1][j];
			if ((dp[i - 1][j] & b[i]) > 0)dp[i][3 * j + 1] = dp[i - 1][j] & b[i];
			if ((dp[i - 1][j] & ~b[i])>0)dp[i][3 * j + 2] = dp[i - 1][j] & ~b[i];
		}
	}

	//repn(i, M)for(auto x:dp[i]) { cout << i << " " << x.first << " " << x.second << endl; }

	ll ans = 0;

	for(auto x:dp[M]) {
