		//cout << i << " " << dp[M][i] << endl;

		vll c(M + 1);
		ll x = i;
		repn(j, M) {
			c[M + 1 - j] = x % 3;
			x /= 3;
		}

		ll hou = 0;
		repn(j, M) {
			ll x = (S >> (j - 1)) & 1;
			ll y = (T >> (j - 1)) & 1;
			if (x == 0 && y == 1) {if (c[j] > 0&&hou>=0) { hou++; }}
			if (x == 0 && y == 0) { if (c[j] != 2) { hou = -1; } }
			if (x == 1 && y == 1) { if (c[j] != 1) { hou = -1; } }
			if (x == 1 && y == 0) { cout << 0 << endl; return 0; }
		}

		if (hou == -1) { continue; }
		hou %= 2;

		ll pop = 0;
		rep(j, N) {
			if ((dp[M][i] >> j) & 1) { pop++; }
		}

		ll cnt = 0;
		rep(j, min(K, pop) + 1) {
			cnt += com[pop][j];
		}

		//cout << hou << " " << cnt << endl << endl;

		if (hou % 2 == 0) { ans += cnt; }
		else { ans -= cnt; }
	}

	cout << ans << endl;
