        for(auto j=bits[i].S.begin();j!=bits[i].S.end();j++){
            cout << *j << " ";
        }
        cout << endl;
    }
    #endif
    //集合分割したのでさらに分割を行う(部分集合全列挙→bit全探索)
    //全探索して全て数え上げたもの一旦ans_subに格納
    ll ans_sub=0;
    //2^L
    //cout << bits_len << endl;
    FOR(i,1,(1<<bits_len)-1){
        //そこまでで分けられた集合を集合ごとに保存
        deque<set<ll>> all_sets;all_sets.PB(set<ll>(ALL(a)));
        //L
        ll odd_even=0;
        REP(j,bits_len){
            if((i>>j)&1){
                odd_even+=1;
                ll s=SIZE(all_sets);
                //n
                REP(_,s){
                    //積集合をとりたい集合を書き出す
                    set<ll> b1=bits[j].F;set<ll> b2=bits[j].S;
                    set<ll> ins=*(all_sets.begin());
                    all_sets.pop_front();
                    //一時保存用の集合を用意する
                    set<ll> f1,f2;
                    set_intersection(ALL(b1),ALL(ins),inserter(f1,f1.end()));
                    set_intersection(ALL(b2),ALL(ins),inserter(f2,f2.end()));
                    if(SIZE(f1) and SIZE(f2)){all_sets.PB(f1);all_sets.PB(f2);}
                    else if(SIZE(f1)){all_sets.PB(f1);}
                    else if(SIZE(f2)){all_sets.PB(f2);}
                }
            }
        }
        //これで完全に分割できた、あとはそれぞれの集合に対して1以上K以下の数を選ぶだけ
        ll s=SIZE(all_sets);
        //n
        REP(_,s){
            set<ll> now=*(all_sets.begin());
            all_sets.pop_front();
            ll s_sub=SIZE(now);
            //k
            FOR(j,1,min(k,s_sub)){
                if(odd_even%2){
                    ans_sub+=COM(s_sub,j);
                }else{
                    ans_sub-=COM(s_sub,j);
                }
            }
        }
    }
    //cout << ans_sub << endl;
    ll ans=-ans_sub;
    FOR(i,1,k)ans+=COM(n,i);
    cout<< ans <<endl;
}

