#define FOR(x,to) for(x=0;x<(to);x++)
#define FORR(x,arr) for(auto& x:arr)
#define ITR(x,c) for(__typeof(c.begin()) x=c.begin();x!=c.end();x++)
#define ALL(a) (a.begin()),(a.end())
#define ZERO(a) memset(a,0,sizeof(a))
#define MINUS(a) memset(a,0xff,sizeof(a))
//-------------------------------------------------------

int N,K,S,T;
int A[51],B[51],C[51];

ll from[51][1<<18];

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N>>K>>S>>T;

	FOR(i,N) {
		cin>>A[i];
		if(A[i]&~T) {
			i--;
			N--;
			continue;
		}
		if((A[i]&S)!=S) {
			i--;
			N--;
			continue;
		}
		B[i]=A[i]^((1<<18)-1);
	}

	ll ret=0;

	int mask,tomask;
	FOR(i,N) {
		int add=0;
		int del=0;
		FOR(j,18) {
			if((S&(1<<j))==0 &&(T&(1<<j))) {
				if(A[i]&(1<<j)) del |= 1<<j;
				else add |= 1<<j;
			}
		}
		tomask=add | del;
		ZERO(from);
		from[0][0]=1;
		for(j=i+1;j<N;j++) {
			int nmask=(B[j]&del)|(A[j]&add);
			for(int mask=tomask; mask>=0; mask--) {
				mask&=tomask;
				for(x=j-i-1;x>=0;x--) from[x+1][mask|nmask]+=from[x][mask];
			}
		}
		for(j=0;j<=K-1;j++) ret+=from[j][tomask];

	}
	cout<<ret<<endl;

}


