    //全て異なるのでsetで良い
    vector<pair<unordered_set<ll>,unordered_set<ll>>> bits;
    REP(i,18){
        unordered_set<ll> f1,f2;
        REP(j,n){
            if((a[j]>>i)&1){
                f1.insert(a[j]);
            }else{
                f2.insert(a[j]);
            }
        }
        if(SIZE(f1) and SIZE(f2))bits.PB(MP(f1,f2));
    }
