        cin >> a;
        inputs.push_back(a);
    }
    map<pair<int, int>,int> dp[60];
    REP(i, n) {
        for (int q = k-1; q >= 1; --q) {
            for (auto& x : dp[q]) {
                pair<int, int> next = mp(x.first.first & inputs[i], x.first.second | inputs[i]);
                if ((next.first & s) != s) continue;
                dp[q + 1][next] += x.second;
            }
        }
        dp[1][mp(inputs[i], inputs[i])]++;
    }
    int ans = 0;
    for (int i = 1; i <= k; ++i) {
        ans += dp[i][mp(s, t)];
    }
    cout << ans << endl;
}

