const int BIT = 18;

bool used[1 << 18];
int N, K, S1, S2, A[1 << 18], power[20];
int S[1 << 26], cnt;
long long nr[59][59];
vector<int> vec;
vector<pair<int, int>> vec2;

void init() {
	for (int i = 0; i <= 50; i++) {
		for (int j = 0; j <= 50; j++) {
			if (i == 0 || j == 0) nr[i][j] = 1;
			else nr[i][j] = nr[i - 1][j] + nr[i][j - 1];
		}
	}
}

long long solve(int ret, int vs) {
	int t = 0;
	for (int i = 0; i < vec.size(); i++) {
		if ((ret / power[i]) % 3 != 2) t++;
	}

	long long rem = 0;
	for (int i = 1; i <= vs; i++) {
		if (i > K) break;
		rem += nr[i][vs - i];
	}
	if (t % 2 == 1) return -rem;
	return rem;
}

int main() {
	cin >> N >> K >> S1 >> S2; init();
	for (int i = 0; i < 18; i++) {
		int g1 = ((S1 / (1 << i)) % 2);
		int g2 = ((S2 / (1 << i)) % 2);
		if (g1 == 1 && g2 == 0) { cout << "0" << endl; return 0; }
		if (g1 != g2) vec.push_back(i);
		if (g1 == g2) vec2.push_back(make_pair(i, g1));
	}

	for (int i = 0; i < N; i++) {
		cin >> A[i]; int sa = 0;
		for (int j = 0; j < vec.size(); j++) {
			if ((A[i] / (1 << vec[j])) % 2 == 1) sa += (1 << j);
		}
		for (int j = 0; j < vec2.size(); j++) {
			int g1 = (A[i] / (1 << vec2[j].first)) % 2;
			if (g1 != vec2[j].second) used[i] = true;
		}
		A[i] = sa;
	}
	power[0] = 1;
	for (int i = 1; i <= vec.size(); i++) power[i] = 3 * power[i - 1];

	for (int i = 0; i < N; i++) {
		if (used[i] == true) continue;
		int bit[19], base = 0; bit[vec.size()] = 0;
		for (int j = 0; j < vec.size(); j++) bit[j] = (A[i] / (1 << j)) % 2;
		for (int j = 0; j < vec.size(); j++) base += bit[j] * power[j];

		for (int j = 0; j < (1 << vec.size()); j++) {
			S[cnt] = base;
			int cx = j + 1, cp = 0;
			while ((cx & 1) == 0) { cx >>= 1; cp++; }
			base += power[cp] * (2 - bit[cp]);
			for (int k = 0; k < cp; k++) base -= power[k] * (2 - bit[k]);
			cnt++;
		}
	}
	sort(S, S + cnt);

	int vs = 0; long long Answer = 0;
	for (int i = 0; i < cnt; i++) {
		vs++;
		if (i + 1 == cnt || S[i] != S[i + 1]) {
			Answer += solve(S[i], vs);
			vs = 0;
		}
	}
	cout << Answer << endl;
	return 0;
}

