  rep(i,0,B) {
    i64 s = !!(S & (1 << i));
    i64 t = !!(T & (1 << i));
    bits[i] = s | (t << 1);
    if(bits[i] == 0b10) L++;
    if(bits[i] == 0b01) {
      cout << 0 << endl;
