      if(bits[j] == 0b00 && (a & (1 << j))) {
        x = -1;
        break;
      }
      if(bits[j] == 0b11 && !(a & (1 << j))) {
        x = -1;
        break;
      }
      if(bits[j] == 0b10) {
        x = (x << 1) | !!(a & (1 << j));
      }
    }
    if(x == -1) continue;
    A.push_back(x);
  }

  auto zeta_transform = [](int n, vector<i64>& a) {
    for (int k = 0; k < n; ++k) {
      for (int s = 0; s < (1 << n); ++s) {
        if (!((s >> k) & 1)) {
          a[s] += a[s ^ (1 << k)];
        }
      }
    }
  };
