      binom[i][j] = binom[i - 1][j - 1] + binom[i - 1][j];
    }
  }
  rep(i,0,N + 1) {
    rep(j,1,N + 1) {
      binom[i][j] += binom[i][j - 1];
    }
  }
  rep(si,0,A.size()) {
    //cout << "turn " << si << endl;
    i64 X = A[si];
    vector<i64> dp((1 << L));
    rep(i,si + 1, A.size()) {
      //cout << ((~(X ^ A[i])) & ((1 << L) - 1)) << endl;
      dp[(~(X ^ A[i])) & ((1 << L) - 1)]++;
    }
    zeta_transform(L, dp);
    i64 res = 0;
    rep(s,0,(1 << L)) {
      //cout << bitset<2>(s) << " = " << dp[s] << "->" << binom[dp[s]][K - 1] - 1 << endl;
      if(__builtin_popcount(s) & 1) {
        res -= binom[dp[s]][K - 1] - 1;
      }
      else {
        res += binom[dp[s]][K - 1] - 1;
      }
    }
    //cout << res << endl;
    ans += res;
  }
  cout << ans << endl;
}

