const int maxN = 55;
const int maxB = 18;
typedef long long ll;

int A[maxN], as[maxB];
ll C[maxN][maxN], ans;
map<int, int> M;

void init(){
	int i, j;
	for(i = 0; i < maxN; ++i)
		for(C[i][0] = C[i][i] = j = 1; j < i; ++j)
			C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
	for(i = 0; i < maxN; ++i)
		for(j = 2; j < maxN; ++j)
			C[i][j] += C[i][j - 1];
}

int main (){
	int n, k, S, T, i, j, c = 0, b, a;
	scanf("%d%d%d%d", &n, &k, &S, &T);
	for(init(), i = 0; i < n; ++i) scanf("%d", A + i);
	for(i = 0; i < maxB; ++i){
		b = 1 << i;
		if((S & b) && !(T & b)) { puts("0"); return 0; }
		if(!(S & b) && (T & b)) as[c++] = i;
		else { for(j = a = 0; j < n; ++j) if((A[j] & b) + (S & b) != b) A[a++] = A[j]; n = a; }
	}
	for(b = 0; b < (1 << c); ++b){
		int sgn = 1, s = 0;
		for(i = 0; i < c; ++i) if(b & (1 << i)) s |= (1 << as[i]), sgn *= -1;
		for(M.clear(), i = 0; i < n; ++i) ++M[A[i] & s];
		for(auto it : M) ans += sgn * C[it.second][k];
