int C[N][N];
int from[N];

bool know[LG], want[LG];
int a[N];

bool have() {
    for (int i = 0; i < n; ++i) {
        bool ban = 0;
        for (int bit = 0; bit < LG; ++bit) {
            if (know[bit] && ((a[i] >> bit) & 1) != want[bit]) {
                ban = 1;
                break;
            }   
        }   
        if (!ban)
            return 1;
    }   
    return 0;
}   

int get() {
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        bool ban = 0;
        for (int bit = 0; bit < LG; ++bit) {
            if (know[bit] && ((a[i] >> bit) & 1) != want[bit]) {
                ban = 1;
                break;
            }   
        }   
        ans += !ban;
    }   
    return ans;
}   

int ans = 0;
void solve(int i, int st) {
    if (!have())
        return;

    if (i == LG) {
        int can = get();
        int x = from[can];
        if (st&1)
            ans -= x;
        else
            ans += x;
        return;
    }   

    solve(i + 1, st);

    if (((T >> i) & 1) && !((S >> i) & 1)) {
        know[i] = 1;
        want[i] = 0;
        solve(i + 1, st + 1);
        know[i] = 0;

        know[i] = 1;
        want[i] = 1;
        solve(i + 1, st + 1);
        know[i] = 0;
    }
}   

