void fmt(LL f[]){
	for (LL i=0;i<k;++i){
		for (LL j=0;j<1<<k;j+=1<<(i+1)){
			LL *f0=f+j,*f1=f+j+(1<<i);
			for (LL t=0;t<1<<i;++t) f1[t]+=f0[t];
		}
	}
}

LL bit(LL x,LL k){
	return x>>k&1;
}

int main(){
	scanf("%lld%lld%lld%lld",&n,&m,&s,&t);
	if ((s|t)!=t){puts("0"); return 0;}
	for (LL i=0;i<18;++i){
		if (bit(s,i)!=bit(t,i)){
			b[k++]=i;
		}
	}
	for (LL i=1;i<=n;++i){
		LL x; scanf("%lld",&x);
		if ((x&s)!=s) continue;
		if ((x|t)!=t) continue;
		++p;
		for (LL j=0;j<k;++j){
			a[p]|=bit(x,b[j])<<j;
		}
	}
	for (LL i=0;i<=n;++i){
		c[i][0]=1;
		for (LL j=1;j<=i;++j) c[i][j]=c[i-1][j]+c[i-1][j-1];
	}
	for (LL i=0;i<=n;++i){
		for (LL j=0;j<m;++j) C[i]+=c[i][j];
	}
	for (LL i=1;i<=p;++i){
		memset(f,0,sizeof f);
		for (LL j=i+1;j<=p;++j){
			++f[a[j]^a[i]];
		}
		fmt(f);
		for (LL j=0;j<1<<k;++j){
			ans+=C[f[j]]*((k-__builtin_popcount(j))&1?-1:1);
		}
	}
	printf("%lld\n",ans);

	return 0;
}

