int a[N];
ll comb[N][N];
ll precomb[N][N];
std::map <int, int> map[1 << BIT];

int main(){
    for (int i = 0; i < N; ++ i){
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++ j){
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
        }
    }
    int n, k, s, t;
    scanf("%d%d%d%d", &n, &k, &s, &t);
    for (int i = 0; i < n; ++ i){
        scanf("%d", &a[i]);
    }
    if ((s & t) != s){
        puts("0");
        return 0;
    }
    std::vector <int> valid;
    for (int i = 0; i < n; ++ i){
        bool flag = true;
        for (int j = 0; j < BIT; ++ j){
            if ((a[i] >> j & 1) && !(s >> j & 1) && !(t >> j & 1)){
                flag = false;
                break;
            }
            if (!(a[i] >> j & 1) && (s >> j & 1) && (t >> j & 1)){
                flag = false;
                break;
            }
        }
        if (flag){
            valid.emplace_back(a[i]);
        }
    }
    int bit = 0;
    for (int i = 0; i < BIT; ++ i){
        if (!(s >> i & 1) && (t >> i & 1)){
            ++ bit;
        }
    }
    n = 0;
    for (auto u : valid){
        a[n] = 0;
        for (int i = BIT - 1; i >= 0; -- i){
            if (!(s >> i & 1) && (t >> i & 1)){
                a[n] = (a[n] << 1) | (u >> i & 1);
            }
        }
        ++ n;
    }
    for (int i = 0; i < n; ++ i){
        map[(1 << bit) - 1][a[i]] = 1;
    }
    for (int i = (1 << bit) - 2; i >= 0; -- i){
        int lb = (~i) & -(~i);
        for (auto p : map[i ^ lb]){
            map[i][p.first & (~lb)] += p.second;
        }
    }
    ll ans = 0;
    for (int i = 0; i < N; ++ i){
        for (int j = 1; j <= k; ++ j){
            precomb[i][j] = precomb[i][j - 1] + comb[i][j];
        }
    }
    for (int i = 0; i < 1 << bit; ++ i){
        for (auto p : map[i]){
            ans += (__builtin_popcount(i) & 1 ? -1 : 1) * precomb[p.second][k];
        }
    }
    printf("%lld\n", ans);
    return 0;
}

