	for (int i = 0; i < n; i++) {
		for (int j = 0; j <= k; j++) {
			dp[i + 1][j] += dp[i][j];
			if (j + 1 <= k) dp[i + 1][j + 1] += dp[i][j];
		}
	}
	for (int i = 0; i <= n; i++) {
		for (int j = 2; j <= k; j++) {
			dp[i][j] += dp[i][j - 1];
		}
	}
	vector<int> old_a(n);
	for (int i = 0; i < n; i++) {
		cin >> old_a[i];
	}
	if ((s & t) != s) {
		cout << "0\n";
		return 0;
	}
	vector<int> a;
	for (int i = 0; i < n; i++) {
		if ((old_a[i] & s) != s || (old_a[i] & t) != old_a[i]) continue;
		a.push_back(old_a[i]);
	}
	n = a.size();
	long long ans = 0;
	for (int i = 0; i < (1 << 18); i++) {
