void brute(int bit, int sign, ll cands) {
  if (bit == 18) {
    ans += f[__builtin_popcountll(cands)] * sign;
  } else {
    if (((s >> bit) & 1) == ((t >> bit) & 1)) {
      brute(bit + 1, sign, cands);
