        for (int j = 1; j <= i; ++j)
            C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
    }
    ast[0] = 1;
    for (int i = 1; i < N; ++i)
        ast[i] = ast[i - 1] * 3;
