        REP(_,s){
            set<ll> now=*(all_sets.begin());
            all_sets.pop_front();
            ll s_sub=SIZE(now);
            //k
            FOR(j,1,min(k,s_sub)){
                if(odd_even%2){
                    ans_sub+=COM(s_sub,j);
                }else{
                    ans_sub-=COM(s_sub,j);
                }
            }
        }
    }
    //cout << ans_sub << endl;
    ll ans=-ans_sub;
    FOR(i,1,k)ans+=COM(n,i);
    cout<< ans <<endl;
}

