// S: AND
// T: OR

bool compat(int x) {
    if ((x|T) != T) return false;
    if ((x&S) != S) return false;

    return true;
}


bool ok(ll mask) {
    // check S
    for (int i=0; i<18; i++) {
	if (!(S>>i&1)) {
	    if (mask>>i&1) {
		if (!((mask>>(i+18))&1)) {
		    return false;
		}
	    }
	}
    }

    // check T
    for (int i=0; i<18; i++) {
	if (T>>i&1) {
	    if (!(mask>>i&1)) {
		return false;
	    }
	} else {
	    if (mask>>i&1) {
		return false;
	    }
	}
    }



    return true;
}


ll make(int x, ll mask) {
    for (int j=0; j<18; j++) {
	if (x>>j&1) {
	    mask |= (1ll<<j);
	} else {
	    mask |= (1ll<<(18+j));
	}
    }

    return mask;
}


void solve(vector<int> a, map<ll, ll> dp[]) {
    dp[0][0] = 1;


    for (int x: a) {
	for (int sz=k-1; sz>=0; sz--) {
	    for (auto p: dp[sz]) {
		ll nmask = make(x, p.first);
		dp[sz+1][nmask] += p.second;
	    }
	}
    }
}

