const int K = 26;
// 0 good
// 1 bad
int F[K][1 << L];

void smain() {


    int n, k, s, t;
    cin >> n >> k >> s >> t;
    vi a(n);
    fori (i, n) {
        cin >> a[i];
    }

    vi ids;

    fori (b, L) {
        if (((s >> b) & 1) && !((t >> b) & 1)) {
            cout << 0;
            return;
        }
        if (((s >> b) & 1) == ((t >> b) & 1)) {
            vi tmp;
            ids.push_back(b);
            for (auto x : a) {
                if (((x >> b) & 1) == ((s >> b) & 1)) {
                    tmp.push_back(x);
                }
            }
            a = tmp;
        }
    }
    set<int> idsset(ALL(ids));
    for (auto &x : a) {
        for (int i = L - 1; i >= 0; --i) {
            if (idsset.count(i)) {
                x = (x & ((1 << i) - 1)) + ((x >> i + 1) << i);
            }
        }
    }
    int len = L - (int)idsset.size();

    ll ans = 0;

    n = a.size();

    int h = n - 1 >> 1;
    int h2 = n - 1 - h;
    while (a.size()) {
        if (h <= 0) {
            n = a.size();
            fori (mask, 1 << n) if (__builtin_popcount(mask) <= k){
                if (!mask)
                    continue;
                int s = (1 << len) - 1;
                int t = 0;
                fori (i, n) if ((mask >> i) & 1) {
                    s &= a[i];
                    t |= a[i];
                }
                ans += (s == 0 && t == ((1 << len) - 1));
            }
            break;
        }
        reverse(ALL(a));
        int zer = a.back();
        a.pop_back();
        reverse(ALL(a));
        n = a.size();
        vi b;
        for (auto x : a) {
            fori (i, len) {
                if (((x >> i) & 1) == ((zer >> i) & 1)) {
                    if (!((x >> i) & 1)) {
                        x += 1 << i;
                    }
                } else {
                    if ((x >> i) & 1) {
                        x -= 1 << i;
                    }
                }
            }
            b.push_back(x);
        }


        fori (mask, 1 << h2) {
            int cnt = 0;
            int cmask = (1 << len) - 1;
            fori (i, h2) if ((mask >> i) & 1) {
                    cnt++;
                    cmask &= b[i + h];
                }
            F[cnt][cmask]++;
        }

        for (int cnt = 0; cnt <= h2; ++cnt) {

            for (int i = 0; i < len; ++i)
                for (int mask = 0; mask < (1 << len); ++mask)
                    if (mask & (1 << i)) F[cnt][mask] += F[cnt][mask ^ (1 << i)];

        }


        for (int cnt = 1; cnt <= h2; ++cnt) {
            for (int mask = 0; mask < (1 << len); ++mask) {
                F[cnt][mask] += F[cnt - 1][mask];
            }
        }

        fori (mask, 1 << h) {
            int cnt = 0;
            int cmask = (1 << len) - 1;
            fori (i, h) {
                if ((mask >> i) & 1) {
                    cnt++;
                    cmask &= b[i];
                }
            }
            cmask = ((1 << len) - 1) ^ cmask;
            int kek = k - 1 - cnt;
            inmin(kek, h2);
            if (kek >= 0)
                ans += F[kek][cmask];
        }

        for (int i = 0; i <= h2; ++i) {
            fori (mask, (1 << len)) {
                F[i][mask] = 0;
            }
        }
        h--;
    }

    cout << ans;

}

