            trav (e, add) {
                gray.pb(e ^ (1 << b));
            }
        }
    }

    int N, K, S, T; re(N, K, S, T);
    vi a(N); re(a);

    vi ct(M);
    trav (e, a) ct[e]++;

    vi active(M); // active[m] = ct of things that lie between m and t

    mn ans = 0;

    vmn pick(N + 1);
    FOR (v, 1, N + 1)
        FOR (c, 1, min(K, v) + 1)
            pick[v] += mn::ncr(v, c);

    F0R (gi, M) {
        int t = gray[gi];

        if (gi == 0) {
            trav (e, a) {
                if ((e | t) == t) {
                    for (int s = e; s >= 0; s = (s - 1)&e) {
                        active[s]++;
                        if (!s) break;
                    }
                }
            }
        } else {
            int pt = gray[gi - 1];
            trav (e, a) {
                if (((e | t) == t) && !((e | pt) == pt)) {
                    for (int s = e; s >= 0; s = (s - 1)&e) {
                        active[s]++;
                        if (!s) break;
                    }
                }
                if (!((e | t) == t) && ((e | pt) == pt)) {
                    for (int s = e; s >= 0; s = (s - 1)&e) {
                        active[s]--;
                        if (!s) break;
                    }
                }
            }
        }

        if ((t | T) != T) continue;

        int td = __builtin_popcount(T) - __builtin_popcount(t);

        for (int s = t; s >= 0; s = (s - 1)&t) {
            if ((s & S) != S) {
                if (!s) break;
                continue;
            }

            int sd = __builtin_popcount(s) - __builtin_popcount(S);

