int bc(int x){
	int an = 0;
	while (x){
		++an;
		x ^= x & -x;
	}
	return an;
}

ll go(vector<int> v, int b, int k, int x){
	int n = v.size();
	f(i, 0, n)v[i] ^= x;
	ll an = 0;
	f(i, 0, 1 << b){
		int s = 0;
		f(j, 0, n)if (!(v[j] & i))++s;
		if (bc(i) & 1)an -= ch[s][k];
		else an += ch[s][k];
	}
	return an;
}

ll solve(vector<int> const &v, int b, int k){
	ll an = 0;
	f(i, 0, v.size())an += go(vector<int>(v.begin() + i + 1, v.end()), b, k - 1, v[i]);
	return an;
}

