const int N = (1 << 18);
const int K = 55;
const int INF = 0x3f3f3f3f;
const int MOD = 1e9 + 7;
const int LOG = 20;
const int OFF = (1 << LOG);

int n, k, kk = 18, S, T;
ll dp[K][N][2], pamti[N], tko[N];
vector < int > v;

ll dinamika(int bitno){
	for(int i = 0;i < 18;i++){
		if(bitno & (1 << i) && tko[bitno] == tko[bitno - (1 << i)])
			return pamti[bitno - (1 << i)];
	}
	int cur = 0, pod = (N - bitno - 1);
	for(int j = 0;j <= k;j++){
		for(int msk = (N - 1) & pod; msk ;msk = (msk - 1) & pod){
			dp[j][msk | bitno][0] = 0;
			dp[j][msk | bitno][1] = 0;
		}
		dp[j][bitno][0] = 0;
		dp[j][bitno][1] = 0;
	}
	dp[0][bitno][0] = 1;
	for(int i = 0;i < n;i++){
		if((v[i] & bitno) != bitno)
			continue;
		cur = !cur;
		for(int j = 0;j <= k;j++){
			dp[j][bitno][cur] = dp[j][T][!cur];
			for(int msk = (N - 1) & pod; msk ;msk = (msk - 1) & pod){
				dp[j][msk | bitno][cur] = dp[j][msk | bitno][!cur];
			}
			if(j){
				for(int msk = (N - 1) & pod; msk ;msk = (msk - 1) & pod){
					dp[j][msk | v[i]][cur] += dp[j - 1][msk | bitno][!cur];
				}
				dp[j][v[i]][cur] += dp[j - 1][bitno][!cur];
			}
		}	
	}
	ll sol = 0;
	for(int i = 1;i <= k;i++){
		sol += dp[i][S][cur];
	}
	pamti[bitno] = sol;
	return sol;
}

int main(){
	scanf("%d%d%d%d", &n, &k, &T, &S);
	if((S & T) != T){
		printf("0\n");
		return 0;
	}
	for(int i = 0;i < n;i++){
		int x; scanf("%d", &x);
		for(int j = 0;j < N;j++)
			if((x & j) == j) tko[j] += (1LL << i);
		v.PB(x);
	}
	n = (int)v.size();
	ll sol = 0;
	for(int i = 0;i < N;i++){
		if((i & T) != T) continue;
		if(__builtin_popcount(i ^ T) % 2 == 0)
			sol += dinamika(i);
		else
			sol -= dinamika(i);
	}
	printf("%lld\n", sol);
	return 0;
}

