void filter() {
    for (int i = 0; i < n; i++) {
        bool okay = true;
        int x = 0;
        for (int j = 0, l = 0; j < LOG; j++) {
            int _i = (A[i]>>j)&1;
            int _s = (s>>j)&1;
            int _t = (t>>j)&1;

            if (_s==1 && _i==0) {
                okay = false;
                break;
            }
            if (_t==0 && _i==1) {
                okay = false;
                break;
            }

            if (_s == 0 && _t == 1) {
                x |= _i<<l;
                l++;
            }
        }

        if (okay) {
//            cout << "take " << i << " as " << x << endl;
