#define time __nico_time
int time, mod[1<<L], cnt[1<<L];

ll solve() {
    cin >> n >> k >> s >> t;
    if ((s & t) != s) return 0;
    {
        int sz = 0;
        forn(_,n) {
            ll x; cin >> x;
            if ((s & x) != s) continue;
            if ((x | t) != t) continue;
            a[sz++] = x-s;
        }
        n = sz;
    }
