int main() {

	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);

	for (int i = 0; i < N; i++) {
		C[i][0] = 1, sum[i][0] = 0;
		for (int j = 1; j <= i; j++) {
			C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
		}
		for (int j = 1; j < N; j++) sum[i][j] = sum[i][j - 1] + C[i][j];
	}

	int n, k, S, T; cin >> n >> k >> S >> T;
	int an = 0, cnt = 0;
	for (int i = 1; i <= n; i++) {
		int u; cin >> u;
		cnt += u == 0;
		if ((u & S) != S || (u | T) != T) continue;
		int cur = 0;
		for (int j = 0; j < 18; j++) if (((~S) >> j & 1) && (T >> j & 1)) cur = cur << 1 | (u >> j & 1);
		a[++an] = cur;
	}
	if (S + T == 0) {
		cout << sum[cnt][k] << "\n";
		return 0;
	}
	n = an;
	long long ans = 0;
	int xx = 32 - __builtin_clz(T) - __builtin_popcount(S);
	for (int s = 0; s < (1 << xx); s++) {
		for (int i = 1; i <= n; i++) {
			frq[a[i] & s]++;
		}
		int sgn = (__builtin_popcount(s) % 2 ? -1 : 1);
		for (int i = 1; i <= n; i++) if (frq[a[i] & s]) {
			ans += sgn * sum[frq[a[i] & s]][k];
			frq[a[i] & s] = 0;
		}
	}

	cout << ans << "\n";

	return 0;
}

