			return 0;
		}
		if ((t & (1LL << i)) && !(s & (1LL << i)))c.push_back(i);
	}

	Array b;
	REP(i, n) {
		auto check = [&]() {
			REP(j, 18) {
				if ((s & (1LL << j)) && (t & (1LL << j))) {
					if (a[i] & (1LL << j))a[i] ^= (1LL << j);
					else return false;
				}
				else if (!(s & (1LL << j)) && !(t & (1LL << j))) {
					if (a[i] & (1LL << j))return false;
				}
			}
			return true;
		};
		if (check() == true)b.push_back(a[i]);
	}
