int main(){
    int N, K, S, T;
    cin >> N >> K >> S >> T;
    int A[N];
    rep(i, N) cin >> A[i];
    if((T|S) != T) {cout << 0 << endl; return 0;}
    vector<int> check;
    int zero = (1<<18)-1, one = 0;
    rep(i, 18){
        if(S&(1<<i)) one |= 1<<i;
        elif(!(T&(1<<i))) zero &= ~(1<<i);
        else check.pb(i);
    }
    vector<int> a;
    rep(i, N){
        if((A[i]|one) != A[i]) continue;
        if((zero|A[i]) != zero) continue;
        a.pb(A[i]);
    }
    int n = sz(check), m = sz(a);
    ll bt[n][2];
    fill(bt[0], bt[n], 0);
    rep(i, n){
        rep(j, m){
            if(a[j]&(1<<check[i])) bt[i][1] |= (1LL<<j);
            else bt[i][0] |= (1LL<<j);
        }
    }
    ll comb[100][100];
    rep(i, 100){
        comb[i][0] = comb[i][i] = 1;
        rep2(j, 1, i-1){
            comb[i][j] = comb[i-1][j-1]+comb[i-1][j];
        }
    }
    ll sum[100]; //i個からK-1個以下を選ぶ方法
    rep(i, 100){
        sum[i] = 0;
        rep(j, min(i, K-1)+1){
            sum[i] += comb[i][j];
        }
    }
    ll ans = 0;
    rep(j, m){
        int b[n];
        rep(i, n){
            if(a[j]&(1<<check[i])) b[i] = 0;
            else b[i] = 1;
        }
        rep(i, 1<<n){
            ll ng = (1LL<<(j+1))-1;
            rep(k, n){
                if(!(i&(1<<k))) continue;
                ng |= bt[k][b[k]];
            }
            ll tmp = sum[m-__builtin_popcountll(ng)];
            if(__builtin_popcount(i)&1) ans -= tmp;
            else ans += tmp;
        }
    }
    cout << ans << endl;
}

