int main() {
    int N, K, S, T;
    cin >> N >> K >> S >> T;

    vector<map<int,map<int,long long>>> dp(K+1);
    dp[0][(1<<18)-1][0] = 1;

    for (int i = 0; i < N; ++i) {
        int a; cin >> a;
        for (int k = K-1; k >= 0; --k) {
            for (auto& pa : dp[k]) {
                int prod = pa.first;
                for (auto& pb : pa.second) {
                    int sum = pb.first;
                    dp[k+1][prod & a][sum | a] += pb.second;
                }
            }
        }
    }

    long long ans = 0;
    for (int k = 1; k <= K; ++k) {
        ans += dp[k][S][T];
    }
    cout << ans << endl;

    return 0;
}

