int main() {
   ios_base::sync_with_stdio(false); cin.tie(nullptr);
   int N, K, S, T;
   cin >> N >> K >> S >> T;
   if ((S & T) != S) {
      cout << 0;
      return 0;
   }
   vector<int> A(N);
   for (int i = 0; i < N; ++i) cin >> A[i];
   vector<int> cnt(1 << 18);
   for (int i = 0; i < N; ++i) {
      if ((A[i] & S) != S) continue;
      if ((A[i] | T) != T) continue;
      ++cnt[A[i]];
   }
   vector<int> up_cnt = cnt;
   vector<int> down_cnt = cnt;
   for (int i = 0; i < 18; ++i) {
      for (int j = 0; j < (1 << 18); j += (1 << (i + 1))) {
         up_cnt[j + (1 << i)] += up_cnt[j];
         down_cnt[j] += down_cnt[j + (1 << i)];
      }
   }
   vector<int> bits;
   vector<char> state(18);
   for (int i = 0; i < 18; ++i) {
      if (S & (1 << i)) state[i] = 1;
      else if (T & (1 << i)) state[i] = 2;
   }
   // cerr << "clgt\n";
   vector<ll> cf(N + 1);
   function<void(int, int, int, int)> brute = [&](int i, int cnt, int orv, int andv) {
      if (i == 18) {
         int q = 0;
         for (int z : A) q += ((z & andv) == andv) && ((z | orv) == orv);
         cf[q] += (cnt & 1) ? -1 : +1;
         return;
      }
      if (state[i] == 0) {
         brute(i + 1, cnt, orv, andv);
      } else if (state[i] == 1) {
         brute(i + 1, cnt, orv + (1 << i), andv + (1 << i));
      } else {
         brute(i + 1, cnt + 1, orv, andv);
         brute(i + 1, cnt + 1, orv + (1 << i), andv + (1 << i));
         brute(i + 1, cnt, orv + (1 << i), andv);
      }
   };
   brute(0, 0, 0, 0);
   vector<vector<ll>> C(N + 1, vector<ll>(N + 1));
   for (int i = 0; i <= N; ++i) {
      C[i][0] = 1;
      for (int j = 1; j <= i; ++j) C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
   }
   ll ans = 0;
   for (int q = 1; q <= N; ++q) {
      ll z = cf[q];
      for (int i = 0; i <= K; ++i) ans += z * C[q][i];
   }
   cout << ans << "\n";
}

