vector<int> nums, tinv(MAX_N), cinv(MAX_N);
map<int, int> cnt;
ll ret = 0;

void dfs(int p, int q, int s, int t, ll num) {
  // cerr << p << " " << q << " " << s << " " << t << " " << num << endl;
  if (p == (int)nums.size() - 1) {
    if (1 <= q && q <= k && s == seki && t == wa) {
      ret += num;
    }
    return;
  }
  if ((seki & s) != seki) return;
  if ((wa | t) != wa) return;
  if (q > k) return;
  if ((wa & (t | tinv[p + 1])) != wa) return;
  // nums[cur] について
  int cur = p + 1;
  int c = cnt[nums[cur]];
  dfs(p + 1, q, s, t, num);
  for (int i = 1; i <= c; i++) {
    dfs(p + 1, q + i, s & nums[cur], t | nums[cur], num * comb[c][i]);
  }
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  for (int i = 0; i < MAX_N; i++) {
    for (int j = 0; j <= i; j++) {
