    if ((s & t) != s) {
        cout << 0 << endl;
        return 0;
    }
    map<int, int> to;
    {
        int p = 1;
        for (int i : range(18)) {
            if (((s ^ t) >> i) & 1) {
                to[i] = p;
                p <<= 1;
            }
        }
    }
    for (int i : range(n)) {
        int x;
        cin >> x;
        if ((s & x) != s) continue;
        if ((t & x) != x) continue;
        int y = 0;
        for (int i : range(18)) {
            if (((x >> i) & 1) && to.count(i)) {
                y += to[i];
            }
        }
        a.push_back(y);
