    n = a.size();
    s = 0;
    t = to.rbegin()->second * 2 - 1;
    if (t == 0 && a.size() == 1) {
        cout << 1 << endl;
        return 0;
    }
    cerr << s << " " << t << endl;
    cerr << join(a, "\n") << endl;
    solve();
    return 0;
}

