struct Comb {
	std::vector<std::vector<s64> > a;
	Comb(int n) { // O(n^2)
		a.resize(n+1);
		for (int i = 0; i <= n; i++) {
			a[i].resize(i+1, 1);
			for (int j = 1; j < i; j++) a[i][j] = a[i-1][j] + a[i-1][j - 1];
		}
	}
	s64 ncr(int n, int r) {
		assert(n >= 0);
		assert(n <= (int)a.size());
		assert(r >= 0);
		assert(r <= n);
		return a[n][r];
	}
};

int64_t gu(int m, int k, const std::vector<int> &revised) {
	int n = revised.size();
	assert(n <= 25);
	int cnt = 0;
	for (int i = 1; i < 1 << n; i++) {
		u32 tmp0 = 0, tmp1 = ~0;
		for (int j = 0; j < n; j++) if (i >> j & 1) tmp0 |= revised[j], tmp1 &= revised[j];
		if (__builtin_popcount(i) <= k && tmp0 == (1U << m) - 1 && !tmp1) cnt++;
	}
	return cnt;
}
int64_t fast(int m, int k, const std::vector<int> &revised) {
	int n = revised.size();
	int64_t ncrsum[n + 1][n + 1];
	memset(ncrsum, 0, sizeof(ncrsum));
	for (int i = 0; i <= n; i++) {
		ncrsum[i][0] = ncrsum[i][i] = 1;
		for (int j = 1; j < i; j++) ncrsum[i][j] = ncrsum[i - 1][j - 1] + ncrsum[i - 1][j];
	}
	for (int i = 0; i <= n; i++) for (int j = 0; j < n; j++) ncrsum[i][j + 1] += ncrsum[i][j];
	uint64_t res = 0;
	for (int i = 0; i < 1 << m; i++) {
		std::map<int, int> ma;
		for (auto j : revised) ma[j & i]++;
		uint64_t cur = 0;
		for (auto j : ma) cur += ncrsum[j.second][k] - 1;
		if (__builtin_popcount(i) & 1) res -= cur;
		else res += cur;
	}
	return res;
}

