template<::std::uint_fast64_t mod>
class ModInt{
private:
  using value_type = ::std::uint_fast64_t;
  value_type n;
public:
  ModInt() : n(0) {}
  ModInt(value_type n_) : n(n_ % mod) {}
  ModInt(const ModInt& m) : n(m.n) {}

  template<typename T>
  explicit operator T() const { return static_cast<T>(n); }
  value_type get() const { return n; }

  friend ::std::ostream& operator<<(::std::ostream &os, const ModInt<mod> &a) {
    return os << a.n;
  }

  friend ::std::istream& operator>>(::std::istream &is, ModInt<mod> &a) {
    value_type x;
    is >> x;
    a = ModInt<mod>(x);
    return is;
  }

  bool operator==(const ModInt& m) const { return n == m.n; }
  bool operator!=(const ModInt& m) const { return n != m.n; }
  ModInt& operator*=(const ModInt& m){ n = n * m.n % mod; return *this; }

  ModInt pow(value_type b) const{
    ModInt ans = 1, m = ModInt(*this);
    while(b){
      if(b & 1) ans *= m;
      m *= m;
      b >>= 1;
    }
    return ans;
  }

  ModInt inv() const { return (*this).pow(mod-2); }
  ModInt& operator+=(const ModInt& m){ n += m.n; n = (n < mod ? n : n - mod); return *this; }
  ModInt& operator-=(const ModInt& m){ n += mod - m.n; n = (n < mod ? n : n - mod); return *this; }
  ModInt& operator/=(const ModInt& m){ *this *= m.inv(); return *this; }
  ModInt operator+(const ModInt& m) const { return ModInt(*this) += m; }
  ModInt operator-(const ModInt& m) const { return ModInt(*this) -= m; }
  ModInt operator*(const ModInt& m) const { return ModInt(*this) *= m; }
  ModInt operator/(const ModInt& m) const { return ModInt(*this) /= m; }
  ModInt& operator++(){ n += 1; return *this; }
  ModInt& operator--(){ n -= 1; return *this; }
  ModInt operator++(int){
    ModInt old(n);
    n += 1;
    return old;
  }
  ModInt operator--(int){
    ModInt old(n);
    n -= 1;
    return old;
  }
  ModInt operator-() const { return ModInt(mod-n); }
};

template<::std::size_t size, ::std::uint_fast64_t mod=1000000007>
class Factorial{
private:
  using value_type = ModInt<mod>;
  ::std::vector<value_type> fact, inv;
public:
  Factorial() : fact(size+1, 1), inv(size+1, 1){
    for(::std::size_t i = 1; i <= size; ++i){
      fact[i] = fact[i-1] * value_type(i);
      inv[i] = fact[i].inv();
    }
  }

  value_type comb(::std::int64_t a, ::std::int64_t b){
    assert(a >= b);
    assert(b >= 0);
    return fact[a]*inv[b]*inv[a-b];
  }

  value_type& operator[](::std::size_t k){ return fact[k]; }
};

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int64 N, K, S, T;
  cin >> N >> K >> S >> T;
  vector<int64> A, filter;
  int64 res = 0, a;

  REP(i, 18) {
    if ((S >> i & 1) || !(T >> i & 1)) continue;
    filter.push_back(i);
  }

  REP(i, N) {
    cin >> a;
    REP(j, 18) {
      if (((a >> j & 1) && !(T >> j & 1)) || (!(a >> j & 1) && (S >> j & 1))) {
        a = -1;
        break;
      }
    }
    if (a != -1) {
      A.push_back(a);
    }
  }

  REP(bit, 1 << filter.size()) {
    map<int64, int64> cnt;
    for (auto a : A) { // それぞれの数について、ビットが立っている場所が全て0であるか、もしくは1であるかを調べる
      int mask = 0;
      REP(i, filter.size()) {
        if ((bit >> i & 1) == 0) continue;
        int k = filter[i];
        mask |= (a >> k & 1) << i;
      }
      cnt[mask]++;
    }
    int sgn = (__builtin_popcount(bit) % 2 ? -1 : 1);
    for (auto&& x : cnt) {
//      cout << bitset<3>(bit) << " " << bitset<3>(x.fs) << ": " << x.sc << endl;
      int64 pat = 1;
      REP(i, min(K, x.sc)) {
        pat *= x.sc - i;
        pat /= i + 1;
        res += sgn * pat;
      }
    }
  }
  cout << res << endl;
}

