	for(int i = 0; i < 50; i++){
		for(int j = 0; j <= m; j++){
			if(j+1 <= m) dp[i+1][j+1] += dp[i][j];
			dp[i+1][j] += dp[i][j];
		}
	}
	for(int i = 0; i <= 50; i++){
		for(int j = 1; j <= m; j++){
			dp[i][j] += dp[i][j-1];
		}
	}

	int p = 0;
	for(int i = 0; i < 18; i++){
		if(s & (1<<i)) continue;
		if(!(t & (1<<i))) continue;
		for(int j = 1; j <= n; j++){
			llint x = (a[j] >> i) & 1;
			b[j] |= x<<p;
		}
		p++;
	}
	for(int i = 1; i <= n; i++) a[i] = b[i];

