            T = ~T;
            DP[0][{mx, mx}] = 1;
            rep(i, N) {
                if ((A[i] | S) != A[i]) continue;
                if (((mx - A[i]) | T) != (mx - A[i])) continue;
                dec(j, K - 1, 0) each(k, DP[j]) {
                    DP[j + 1][{k.fi.fi & A[i], k.fi.se & (mx - A[i])}] += k.se;
                }
            }
        } else {
            DP[0][{mx, 0}] = 1;
            rep(i, N) {
                if ((A[i] | S) != A[i]) continue;
                if ((T | A[i]) != T) continue;
                dec(j, K - 1, 0) each(k, DP[j]) {
                    DP[j + 1][{k.fi.fi & A[i], k.fi.se | A[i]}] += k.se;
                }
            }
        }
    }
    rep(i, K) res += DP[i + 1][{S, T}];
    cout << res << rt;
}

