const int N = 55;
int n, K, a[N], A, B, cnt[1 << 18 | 5];
ll C[N][N];
tr1:: unordered_map <ll, int> mp;
int main() {
  #ifdef ldxcaicai
  freopen("lx.in", "r", stdin);
  #endif
  n = read(), K = read(), A = read(), B = read();
  int tot = 0;
  for (ri i = 1; i <= n; ++i) {
    int x = read();
    if (((x & A) != A) || ((x | B) != B)) continue;
    a[++tot] = x;
  }
  if (!tot) return cout << 0, 0;
  for (ri i = 1, up = 1 << 18; i < 1 << 18; ++i) cnt[i] = cnt[i >> 1] + (i & 1);
  n = tot;
  for (ri i = 0; i <= n; ++i) for (ri j = C[i][0] = 1; j <= i; ++j) C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
  for (ri i = 0; i <= n; ++i) for (ri j = 2; j <= i; ++j) C[i][j] += C[i][j - 1];
  ll bas = 1 << 18;
  for (ri i = 1; i <= n; ++i) {
    int s1 = 0, s2 = 0;
    for (ri b = 0; b < 18; ++b) {
      if (!(A >> b & 1)) {
        if ((a[i] >> b & 1)) s1 |= 1 << b;
      }
      if (B >> b & 1) {
        if (!(a[i] >> b & 1)) s2 |= 1 << b;
      }
    }
    for (ll t1 = s1; ; t1 = (t1 - 1) & s1) {
      for (ll t2 = s2; ; t2 = (t2 - 1) & s2) {
        ++mp[t1 * bas + t2];
        if (!t2) break;
      }
      if (!t1) break;
    }
  }
  ll res = 0;
  for (tr1:: unordered_map <ll, int> :: iterator it = mp.begin(); it != mp.end(); ++it) {
    ll coe = C[it -> se][min(K, it ->se)];
    ll sta = it -> fi;
    ll X = sta / bas;
    ll Y = sta % bas;
    if ((cnt[X] + cnt[Y]) & 1) coe *= -1;
    res += coe;
  }
  cout << res;
  return 0;
}

#include<bits/stdc++.h>
using namespace std;

const long long K = 18, N = 55;

vector<long long> vv[1<<K];

long long C[N][N];

void pre() {
    for (long long i=0; i<N; i++) C[i][0] = 1;
    for (long long i=1; i<N; i++)
        for (long long j=1; j<N; j++)
            C[i][j] = C[i-1][j-1] + C[i-1][j];

    for (long long i=0; i<N; i++)
        for (long long j=1; j<N; j++)
            C[i][j] += C[i][j-1];
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    pre();


    long long n, k, S, T;
    cin>>n>>k>>S>>T;

    if ( (S&T) != S) {
        cout<<0<<endl;
        return 0;
    }

    for (long long i=0; i<n; i++) {
        long long x;
        cin>>x;

        if ((x&S) != S) continue;
        if ((x&T) != x) continue;

        for (long long mask = 0; mask < (1<<K); mask++) {
            if ((mask&S) != S) continue;
            if ((mask&T) != mask) continue;
            long long ans = 0;
            for (long long i=0; i<K; i++) {
                bool si = S & (1<<i);
                bool ti = T & (1<<i);
                if (si == ti)   continue;
                if ((mask & (1<<i)) == 0)       ans |= x&(1<<i);
            }
            vv[mask].push_back(ans);
        }
    }

    long long ans = 0;
    for (long long mask = 0; mask < (1<<K); mask++) {
        if ((mask&S) != S) continue;
        if ((mask&T) != mask) continue;
        sort(vv[mask].begin(), vv[mask].end());

        long long ww = 0;
        while (vv[mask].size()) {
            long long last = vv[mask].back();
            long long cnt = 0;
            while (vv[mask].size() && vv[mask].back() == last)  cnt++, vv[mask].pop_back();

            ww += C[cnt][k];
        }

        long long bc = __builtin_popcount(mask);
        if (bc%2)   ans += ww;
        else        ans -= ww;
    }
    cout<<abs(ans)<<endl;
}

