LL comb[100][100];
LL sumC[100][100];

inline LL calcC(int n, int k) {
    if (n == 0 && k >= 0) return 1;
    if (n <= 0 || k < 0) return 0;
    return sumC[n][k];
}

// U(S) = g となるサイズc-1個の集合S \in bを数える
LL solveSubProblem(vector<int> b, int c, int g) {
    int sz     = b.size();
    comb[0][0] = 1;
    for (int i : range(60)) {
        for (int j : range(i + 1)) {
            comb[i + 1][j] += comb[i][j];
            comb[i + 1][j + 1] += comb[i][j];
        }
        sumC[i][0] = comb[i][0];
        for (int j : range(1, c + 1)) {
            sumC[i][j] = sumC[i][j - 1] + comb[i][j];
        }
    }
    LL ret = 0;

    for (int bit : range(g + 1)) {
        int on = 0;
        for (auto e : b) {
            if (e & bit) on++;
        }
        LL cnt  = calcC(sz - on, c);
        int sgn = ((__builtin_popcountll(g - bit)) & 1) ? -1 : 1;
        // cerr << bitset<18>(bit).to_string().substr(16) << " " << sgn << " "
        // << cnt << endl;
        ret += sgn * cnt;
    }
    return ret;
}


int n, k;
int s, t;
vector<int> a;


void solve() {
    LL ret = 0;
    for (int i : range(n)) {
        vector<int> b;
        for (int j : range(i + 1, n)) {
            b.push_back(a[j] ^ a[i]);
        }
        auto c = solveSubProblem(b, k - 1, t);
        assert(c >= 0);
        ret += c;
    }
    cout << ret << endl;
}


