ll dfs(const vecll& a, ll s, ll t, ll i, ll k) {
  if (i == 18) {
    ll n = size(a);
    ll ans = 0;
    FOR(i,1,k+1) {
      if (i > n) break;
      ans += comb[n][i];
    }
    return ans;
  }
  if ((s>>i)&1) {
    return dfs(a, s, t, i+1, k);
  }
  if (((t>>i)&1) == 0) {
    return dfs(a, s, t, i+1, k);
  }
  vecll zero, one;
  for(auto&&e:a) {
    if ((e>>i)&1) {
      one.push_back(e);
    } else {
      zero.push_back(e);
    }
  }
  if (one.empty() || zero.empty()) return 0;
  return dfs(a, s, t, i+1, k) - dfs(zero, s, t, i+1, k) - dfs(one, s, t, i+1, k);
}

