const int BITS = 18;

int main() {
    int N, K, S, T;
    cin >> N >> K >> S >> T;

    if ((S | T) != T) {
        cout << 0 << '\n';
        return 0;
    }

    vector<int> A;

    for (int i = 0; i < N; i++) {
        int a;
        cin >> a;

        if ((a & S) != S || (a | T) != T)
            continue;

        A.push_back(a);
    }

    N = int(A.size());
    K = min(K, N);

    vector<vector<int64_t>> choose(N + 1, vector<int64_t>(N + 1, 0));

    for (int i = 1; i <= N; i++) {
        choose[i][0] = choose[i][i] = 1;

        for (int j = 1; j < i; j++)
            choose[i][j] = choose[i - 1][j] + choose[i - 1][j - 1];
    }

    vector<int64_t> up_to_K(N + 1, 0);

    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= K; j++)
            up_to_K[i] += choose[i][j];

    vector<int> freq(1 << BITS, 0);
    int64_t answer = 0;
    int overall = S ^ T;

    for (int mask = overall; ; mask = (mask - 1) & overall) {
        vector<int> ors(N);

        for (int i = 0; i < N; i++) {
            ors[i] = A[i] | mask;
            freq[ors[i]]++;
        }

        int64_t sum = 0;

        for (int i = 0; i < N; i++) {
            sum += up_to_K[freq[ors[i]]];
            freq[ors[i]] = 0;
        }

        answer += (__builtin_popcount(mask) % 2 == 0 ? +1 : -1) * sum;

        if (mask == 0)
            break;
    }

    cout << answer << '\n';
}

