const int N = 51;

int n, k, s, t;
ll C[N][N], ways[N];
vector <int> a;

ll solve(vector <int> &b){
    ll ret = 0;
    for(int mask = 0 ; mask <= (t ^ s) ; mask++){
        if((mask & (t ^ s)) != mask) continue;
        int sign = (__builtin_popcount(mask) % 2 ? -1 : 1);
        int cnt = 0;
        for(auto &i : b){
            cnt += (i & mask) == 0;
        }
        ret += sign * ways[cnt];
    }
    return ret;
}
