int bsf(ull x) { return __builtin_ctzll(x); }

Scanner sc = Scanner(stdin);
Printer pr = Printer(stdout);

int main() {
    int n, k, s, t;
    n = 50;
    k = 50;
    s = 0;
    t = (1 << 18) - 1;
    sc.read(n, k, s, t);

    // s == 1, t == 0
    if (s & ~t) {
        pr.writeln(0);
        return 0;
    }

    V<int> v;
    for (int i = 0; i < n; i++) {
        int x;
        x = 0;
        sc.read(x);

        // x == 0, s == 1
        if (~x & s) continue;
        // x == 1, t == 0
        if (x & ~t) continue;
        v.push_back(x);
    }
    n = int(v.size());

    V<int> idxs;
    for (int i = 0; i < 18; i++) {
        // s == 0, t == 1
        if (s & (1 << i)) continue;
        if (!(t & (1 << i))) continue;
        idxs.push_back(i);
    }

    int l = int(idxs.size());

    {
        V<int> v2;
        for (auto x: v) {
            int nx = 0;
            for (int i = 0; i < l; i++) {
                int p = idxs[i];
                if (x & (1 << p)) nx += 1 << i;
            }
            v2.push_back(nx);
        }
        v = v2;
    }

             ;
    V<ull> f0(l), f1(l);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < l; j++) {
            if (v[i] & (1 << j)) {
                f1[j] |= (1ULL << i);
            } else {
                f0[j] |= (1ULL << i);
            }
        }
    }
    VV<ll> C(55, V<ll>(55));
    C[0][0] = 1;
    for (int i = 1; i < 55; i++) {
        C[i][0] = 1;
        for (int j = 1; j < 55; j++) {
            C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
        }
    }

    V<ll> cnt(n + 1);
    for (int i = 0; i <= n; i++) {
        for (int j = 1; j <= min(i, k); j++) {
            cnt[i] += C[i][j];
        }
    }
            ;
    auto dfs = [&](auto self, ull f, int p) -> ll {
        if (p == l) {
            return cnt[popcnt(f)];
        }
        ll ans = 0;
        ans -= self(self, f & f0[p], p + 1);
        ans -= self(self, f & f1[p], p + 1);
        ans += self(self, f, p + 1);
        return ans;
    };
    pr.writeln(dfs(dfs, (1ULL << n) - 1, 0));
    return 0;
}

