			(dp[i + 1][j] += dp[i][j]) %= mod;
			if (j + 1 <= k) (dp[i + 1][j + 1] += dp[i][j]) %= mod;
		}
	}
	for (int i = 0; i <= n; i++) {
		for (int j = 1; j <= k; j++) {
			(dp[i][j] += dp[i][j - 1]) %= mod;
		}
