long long binomialCoefficients(int n, int k) {
	vector<long long> C(70, 0);
	C[0] = 1;
	for (int i = 1; i <= n; i++) {
		for (int j = min(i, k); j > 0; j--)
			C[j] = C[j] + C[j - 1];
	}
	return C[k];
}

long long calc_ways(vector<int>& nums, vector<long long>& cnts, int mask)
{
	map<int, int> mm;
	for (int x : nums)
	{
		mm[x & mask]++;
	}
	long long ret = 0;
	for (auto& x : mm)
	{
		ret += cnts[x.second];
	}
	return ret;
}

int main() {

#if defined(_DEBUG)
	freopen("input.txt", "r", stdin);
	freopen("output.txt", "w", stdout);
#endif

	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);

	int n, k, s, t;
	fio >> n >> k >> s >> t;

	if ((s & t) != s)
	{
		fio << 0;
		return 0;
	}

	vector<int> nums(n);
	fio >> nums;

	vector<int> bits;
	for (int i = 0; i < 18; i++)
	{
		bool sb = ((1 << i) & s) > 0;
		bool tb = ((1 << i) & t) > 0;

		if (sb != tb)
		{
			bits.push_back(i);
		}
	}

	vector<int> nums2;
	for (int i = 0; i < n; i++)
	{
		if ((nums[i] & s)!=s) continue;
		int pos = 0, ans =0;
		for (int j : bits)
		{
			if ((1 << j) & nums[i])
				ans |= (1 << pos);
			pos++;
		}
		nums2.push_back(ans);
	}

	if (bits.size() == 0)
	{
		int x = 1 << nums2.size();
		fio << x - 1;
		return 0;
	}

	vector<long long> cnts;
	cnts.push_back(0);
	for (int i = 1; i <= n; i++)
	{
		long long ans = 0;
		for (int j = 1; j <= min(i, k); j++)
		{
			ans += binomialCoefficients(i, j);
		}
		cnts.push_back(ans);
	}

	long long resp = 0;
	int mx = 1 << bits.size();
	for (int mask = 0; mask < mx; mask++)
	{
		long long sign = (__builtin_popcount(mask) % 2 == 0) ? 1 : -1;
		resp += sign * calc_ways(nums2, cnts, mask);
	}
	fio << resp;

	return 0;
}

