ll llpow(ll a, ll b){
    if(b == 0){
        return 1;
    }
    ll ans = llpow(a, b / 2);
    ans = ans * ans; // % MOD; (MODつけたい場合のコピー用)
    if(b % 2 == 1){
        ans = ans * a; // % MOD; (MODつけたい場合のコピー用)
    }
    return ans;
}

ll comb(ll n, ll k){
  if (n < k) return 0;
  if (k > n / 2) k = n - k;
  ll ret = 1;
  ll divider = 1;
  rep(i, k) ret *= (n - i);
  rep(i, k) divider *= (i + 1);
  return ret / divider;
}

