int main()
{
    constexpr int B         = 4;
    const auto [N, K, S, T] = in.tup<int, int, uint, uint>();
    const auto as           = in.vec<uint>(N);
    if ((S & T) != S) { return out.ln(0); }
    std::vector<uint> bs;
    for (int i = 0; i < N; i++) {
        if (((as[i] & T) == as[i]) and ((as[i] & S) == S)) { bs.push_back(as[i]); }
    }
    SHOW(bs);
    const int M = bs.size();
    auto dp     = std::vector<ll>(1 << B, 0);
    for (int m = 0; m < (1 << B); m++) {  // 違反集合
        bool ng = false;
        for (int b = 0; b < B; b++) {
            if (btest(m, b)) {
                if (btest(S, b) == 1 or btest(T, b) == 0) { ng = true; }
            }
        }
        if (ng) { continue; }
        for (int i = 0; i < M; i++) {
            std::vector<ll> idp(K + 1, 0);
            idp[1] = 1;
            for (int j = i + 1; j < M; j++) {
                for (int k = K - 1; k >= 0; k--) {
                    bool usable = true;
                    for (int b = 0; b < B; b++) {
                        if (btest(m, b)) {
                            if (btest(as[i], b) != btest(as[j], b)) { usable = false; }
                        }
                    }
                    if (usable) { idp[k + 1] += idp[k]; }
                }
            }
            SHOW(m, i, idp);
            for (int k = 0; k <= K; k++) { dp[m] += idp[k]; }
        }
    }
    SHOW(dp);
    ll ans = 0;
    for (int m = 0; m < (1 << B); m++) { ans += (popcount(m) % 2 == 0 ? 1LL : -1LL) * dp[m]; }
    out.ln(ans);
    return 0;
}

