const Int B = 19;
signed main() {
    auto comb = make_vec<Int>(55, 55, 0);
    REP(i, 55 - 1) {
        comb[i][0] = 1;
        REP(j, i + 1) { comb[i + 1][j + 1] = comb[i][j] + comb[i][j + 1]; }
    }
    auto acc = make_vec<Int>(56, 56, 0);
    REP(i, 55) {
        REP(j, i + 1) { acc[i][j + 1] = acc[i][j] + comb[i][j]; }
    }
    auto calc = [&](Int n, Int r) { return std::max(0LL, acc[n][std::min(n, r) + 1] - 1); };
    Int n, K, s, t;
    std::cin >> n >> K >> s >> t;
    std::vector<Int> a(n);
    REP(i, n) std::cin >> a[i];
    std::vector<Int> bits;
    REP(k, B) {
        Int x = s >> k & 1, y = t >> k & 1;
        if (x == 1) {
            for (Int i = (Int)a.size() - 1; i >= 0; i--) {
                if ((a[i] >> k & 1) == 0) a.erase(a.begin() + i);
            }
        } else if (y == 0) {
            for (Int i = (Int)a.size() - 1; i >= 0; i--) {
                if ((a[i] >> k & 1) == 1) a.erase(a.begin() + i);
            }
        } else {
            bits.push_back(k);
        }
    }

    Int m = bits.size();
    std::vector<Int> b(a.size());
    REP(i, a.size()) {
        REP(j, m) { b[i] |= (a[i] >> bits[j] & 1) << j; }
    }

    __int128_t ans = 0;
    REP(S, 1 << m) {
        std::unordered_map<Int, Int> mp;
        for (Int x : b) mp[x & S]++;
        Int cnt = 0;
        for (auto& p : mp) cnt += calc(p.second, K);
        ans += cnt * (__builtin_popcount(S) % 2 ? -1 : 1);
    }
    std::cout << (Int)ans << std::endl;
}

