class EOrand {
public:
    void solve() {
        int n = in.readInt();
        int k = in.readInt();
        auto s = in.readUnsigned();
        auto t = in.readUnsigned();
        auto a = in.readArray<unsigned>(n);

        if ((s & t) != s) {
            out.printLine(0);
            return;
        }
        vector<unsigned> b;
        for (unsigned i : a) {
            if ((i & s) != s || (i | t) != t) {
                continue;
            }
            b.push_back(i - s);
        }
        t -= s;
        vector<unsigned> bits;
        for (int i : range(18)) {
            if (isSet(t, i)) {
                bits.push_back(1u << i);
            }
        }
        for (unsigned& i : b) {
            unsigned x = 0;
            for (int j : range(bits.size())) {
                if ((i & bits[j]) != 0) {
                    x += 1u << j;
                }
            }
            i = x;
        }
        int len = bits.size();
        arr2d<ll> res(k, 1 << len);
        unsigned ab = allBits(len);
        ll answer = 0;
        for (int i : range(b.size())) {
            fill(all(res), 0);
            res(0, ab) = 1;
            unsigned missing = ab - b[i];
            unsigned present = b[i];
            for (int j : range(i + 1, b.size())) {
                for (int l : RevRange(k - 1)) {
                    for (int m : range(1 << len)) {
                        unsigned nPresent = present & m & b[j];
                        unsigned nMissing = missing & m & (ab - b[j]);
                        res(l + 1, nPresent + nMissing) += res(l, m);
                    }
                }
            }
            for (int j : range(k)) {
                answer += res(j, 0);
            }
        }
        out.printLine(answer);
    }
};


