void solve() {
  int n, k, s, t; cin >> n >> k >> s >> t;
  if ((s & t) != s || (s | t) != t) {
    cout << 0 << endl;
    return;
  }
  vi arr;
  rep(_,n) {
    int a; cin >> a;
    if ((s & a) == s && (t | a) == t) {
      arr.emplace_back(a);
    }
  }
  n = arr.size();
  if (n == 0) {
    cout << 0 << endl;
    return;
  }
  chmin(k,n);

  Graph<ll> pascal(n+1, vl(k, 0));
  pascal[0][0] = 1;
  vl comb(1, 1);
  rep1eq(i,n) {
    pascal[i][0] = 1;
    rep1(j,k) {
      pascal[i][j] = pascal[i-1][j-1] + pascal[i-1][j];
    }
    comb.emplace_back(accumulate(ALL(pascal[i]), 0LL));
  }

  bitset<18> x(s ^ t);
  ll ans = 0;

  rep(i,n) {
    vector<bitset<50>> g(18, 0);
    rep(j,i) {
      bitset<18> tmp(arr[i] ^ arr[j]);
      tmp = ~tmp & x;
      rep(d,18) {
        if (tmp[d]) g[d].set(j);
      }
    }

    rep(j,1<<18) {
      bitset<18> tmp(j);
      if ((tmp & ~x).any()) continue;
      bitset<50> cnt((1LL<<i)-1);
      rep(d,18) {
        if (tmp[d]) cnt &= g[d];
      }
      if (tmp.count() & 1) ans -= comb[cnt.count()];
      else ans += comb[cnt.count()];
    }
  }

  cout << ans << endl;
}


/* -------- <programs end> -------- */


signed main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);
  solve();
  return 0;
}

