VI v;

int p3[30];
unordered_map<int, int> ile;
unordered_map<int, int> dwojki;


lint bin[55][55];
lint bin2[55];

int memo[300000];
int memo2[300000];

int logi[300000];

int main() {
	FOR(i,0,19) logi[1<<i] = i;
	read4(n, k, s, t);
	FOR(i,0,n) {
		make(a);
		if ( ((a&s) == s) && ((a|t) == t)) {
			v.pb(a);
		}
	}	
	n = v.size();
	if (((t&s) != s) || n == 0) {
		printf("0\n"); return 0;
	}
	k = min(k, n);
	FOR(i,0,n+1) bin[i][i] = bin[i][0] = 1;
	FOR(i,2,n+1) {
		FOR(j,1,i) bin[i][j] = bin[i-1][j-1] + bin[i-1][j];
	}
	FOR(i,0,n+1) {
		bin2[i] = 0;
		FOR(j,0,min(i+1,k+1)) bin2[i] += bin[i][j];
	}

	VI cyfry;
	FOR(i,0,18) {
		if ((s&(1<<i)) != (t&(1<<i))) cyfry.pb(i);
	}
	int h = cyfry.size();
	// debug() << imie(cyfry) imie(h);

	int p2 = 1 << h;
	p3[0] = 1;
	FOR(i,1,h+1) p3[i] = p3[i-1] * 3;

	FOR(i,0,n) {
		int a = v[i];
		//debug() << imie(a);

		int mask0 = 0;
		FOR(u,0,h) {
			int c = cyfry[u];
			if (a & (1<<c)) mask0 += p3[u];
		}
		if (ile.find(mask0) == ile.end()) ile[mask0] = 1;
		else ile[mask0]++;
		dwojki[mask0] = 0;
		memo[0] = 0;
		memo2[0] = 0;

		FOR(j,1,p2) {
			int maxi = logi[j&(-j)];
			int reszta = j - (1<<maxi);
			int mask = memo[reszta];
			int dw = memo2[reszta] + 1;
			memo2[j] = dw;

			int c = cyfry[maxi];
			int d = 2;
			if (a & (1<<c)) {
					d = 1;
			}
			mask += p3[maxi] * d;
			memo[j] = mask;

			mask += mask0;
			if (ile.find(mask) == ile.end()) ile[mask] = 1;
			else ile[mask]++;	
			dwojki[mask] = dw;
		}
