        } else if(~s & (1 << i) and ~t & (1 << i)) {
            C++;
            rep(j, n) {
                if(a[j] & (1 << keta)) continue;
                nxt.eb((a[j] % (1 << keta)) + ((a[j] >> (keta + 1)) << keta));
            }
            a = nxt;
        }
