template<const char ch, class T>
std::vector<T> FWHT(std::vector<T> a, const bool inv = false) {
	int n = (int) a.size();
	for(int len = 1; len < n; len += len) {
		for(int i = 0; i < n; i += 2 * len) {
			for(int j = 0; j < len; j++) {
				auto u = a[i + j], v = a[i + j + len];
				if(ch == '^') {
					a[i + j] = u + v;
					a[i + j + len] = u - v;
				}
				if(ch == '|') {
					if(!inv) {
						a[i + j + len] += a[i + j];
					} else {
						a[i + j + len] -= a[i + j];
					}
				}
				if(ch == '&') {
					if(!inv) {
						a[i + j] += a[i + j + len];
					} else {
						a[i + j] -= a[i + j + len];
					}
				}
			}
		}
	}
	if(ch == '^' && inv) {
		for(int i = 0; i < n; i++) {
			a[i] = a[i] / n;
		}
	}
	return a;
}

long long comb[55][55], val[55];

long long solve(const std::vector<int> &a, int k, int B) {
	int n = (int) a.size();
	for(int i = 0; i <= n; i++) {
		comb[i][0] = 1;
		for(int j = 1; j <= i; j++) {
			comb[i][j] = comb[i-1][j] + comb[i-1][j-1];
		}
	}
	k = std::min(k, n);
	for(int i = 0; i <= n; i++) {
		for(int j = 0; j < k; j++) {
			val[i] += comb[i][j];
		}
	}
	long long ans = 0;
	std::vector<long long> wtf;
	for(int f = 0; f < n; f++) {
		wtf.assign(1 << B, 0);
		for(int i = f+1; i < n; i++) {
			wtf[a[i] ^ a[f]]++;
		}
		wtf = FWHT<'|'>(wtf);
		for(auto &x : wtf) x = val[x];
		wtf = FWHT<'|'>(wtf, true);
		ans += wtf.back();
	}
	return ans;
}

