    for (int r = 1; r < MAX_N; ++r)
    {
        C[r][0] = 1;
        C[r][r] = 1;
        for (int j = 1; j < r; ++j)
        {
            C[r][j] = C[r-1][j] + C[r-1][j-1];
        }
    }

    for (int r = 0; r < MAX_N; ++r)
    {
        C[r][0] = 0;
        for (int j = 1; j < MAX_N; ++j)
            C[r][j] += C[r][j - 1];
    }
}

