template<typename T> struct Combination {
	LL n;
	vector<T> f, r;
	Combination(LL nn) {
		n = nn;
		f = r = vector<T>(n + 1);
		inc(i, n + 1) { f[i] = (i == 0 ? 1        : f[i - 1] *  i     ); }
		dec(i, n + 1) { r[i] = (i == n ? 1 / f[n] : r[i + 1] * (i + 1)); }
	}
	T P(LL a, LL b) {
		assert(inII(a, 0, n) && inII(b, 0, n));
		return (a < b ? 0 : f[a] / f[a - b]);
	}
	T C(LL a, LL b) {
		assert(inII(a, 0, n) && inII(b, 0, n));
		return (a < b ? 0 : f[a] / f[a - b] / f[b]);
	}
	T H(LL a, LL b) {
		assert(inII(a, 0, n) && inII(b, 0, n) && inII(a + b - 1, -1, n));
		return (a == 0 ? (b == 0 ? 1 : 0) : f[a + b - 1] / f[a - 1] / f[b]);
	}
};

