    if((t|tmp)!=t) continue;
    if((s&tmp)!=s) continue;
    a.push_back(tmp);
  }

  n = a.size();
  k = min(k, n);
  ll ans = 0;
  for(int i=0;i<n;i++){
    // iを確定
    // 全てのbitに「残りの要素全てが1だとダメ」(and) , 「残りの要素全てが0だとダメ」(or)のどちらかが科される
    vll c(1<<18, 0); //k個以下取り、bitの条件に引っかかってダメな場合の数

    for(int b=1;b<(1<<18);b++){
      ll cnt = 0;
      for(int j=i+1;j<n;j++){
        bool f = true;

        for(int p=0;p<18;p++){
          if(((b>>p)&1)==0) continue;
          if(((t>>p)&1) == ((s>>p)&1)) {
            f = false;
            break;
          }
          if(((t>>p)&1)==0&&((s>>p)&1)==1) continue;

          if(((a[i]>>p)&1) != ((a[j]>>p)&1)){
            f = false;
            break;
          }
        }
        if(f) cnt++;
      }
      //全体
      for(int j=0;j<=(min(cnt, k-1));j++) c[b] += V[cnt][j];
    }
    ll num = n - i - 1;
    ll all_pat = 0;
    for(int j=0;j<=min(k-1, num);j++) all_pat += V[num][j];

    //k個以下取って、どれかの条件に引っかかってダメな場合 包除原理(奇数bit立っているなら加算、偶数なら減算)
    ll bad = 0;
    for(int b=1;b<(1<<18);b++){
      if(__builtin_popcount(b)%2) bad += c[b];
      else bad -= c[b];
    }
    //k個以下取って可能な場合　= all_pat - どれかでダメ
    ans += all_pat - bad;
  }
  std::cout << ans << '\n';
  return 0;
}

