ll llpow(ll a, ll b){
    if(b == 0){
        return 1;
    }
    ll ans = llpow(a, b / 2);
    ans = ans * ans; // % MOD; (MODつけたい場合のコピー用)
    if(b % 2 == 1){
        ans = ans * a; // % MOD; (MODつけたい場合のコピー用)
    }
    return ans;
}

// MOD版（modinvも入れること）
const ll ll_MOD = 9007199254740997LL;

// mod. m での a の逆元 a^{-1} を計算する
long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

ll comb(ll n, ll k){
  if (n < k) return 0;
  if (k > n / 2) k = n - k;
  ll ret = 1;
  ll divider = 1;
  rep(i, k) ret = ret * (n - i) % ll_MOD;
  rep(i, k) divider = divider * (i + 1) % ll_MOD;
  return ret * modinv(divider, ll_MOD) % ll_MOD;
}

