struct solver
{
    int bit(int x,int k)
    {
        return (x>>k)&1;
    }

    solver()
    {
        int n,k,S,T; cin>>n>>k>>S>>T;
        vector<int> a(n);
        vector<int> ng(n);
        for(int i=0; i<n; ++i)
        {
            int x; cin>>x;
            a[i]=x;
            for(int j=0; j<18; ++j)
            {
                if(bit(x,j) and !bit(T,j))
                {
                    ng[i]=1;
                }
                if(!bit(x,j) and bit(S,j))
                {
                    ng[i]=1;
                }
            }
        }
        // vector ax(n,vector<int>(n));

        i64 ans=0;
        const int allb=(1<<18)-1;

        // for(int st=n-1; st>=0; --st)
        // {
        //     for(int j=st+1; j<n; j++)
        //     {
        //         int xo=a[st]^a[j];
        //         for(int s=0; s<=allb; s++)
        //         {
        //             int ss=xo|s;

        //         }
        //     }
        // }

        for(int st=0; st<n; ++st)
        {
            if(ng[st]) continue;
            int rst=n-st;
            vector dp(rst+1,vector<i64>(1<<18));
            dp[1][0]=1;
            for(int i=1; i<rst; i++)
            {
                int xo=a[st]^a[i+st];

                // vector nxt(rst+1,vector<i64>(1<<rst));
                for(int j=i; j>0; j--)
                {
                    for(int s=0; s<=allb; s++)
                    {
                        int ns=s|xo;
                        dp[j+1][ns]+=dp[j][s];
                    }
                }
            }
            int bot=0;
            for(int i=0; i<18; i++)
            {
                if(bit(S,i)!=bit(T,i)) bot|=1<<i;
            }
            for(int i=1; i<=rst and i<=k; i++)
            {
                ans+=dp[i][bot];
            }
        }
        cout << ans << "\n";
    }
};
