int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);
    int n, k, s, t;
    cin >> n >> k >> s >> t;
    if ((s | t) != t) {
        cout << 0 << '\n';
        return 0;
    }
    vector<int> a;
    for (int i = 0; i < n; ++i) {
        int aa;
        cin >> aa;
        if ((aa & s) == s && (aa | t) == t) {
            a.push_back(aa);
        }
    }
    n = a.size();
    k = min(n, k);
    vector<P> cond;
    for (int i = 0; i < 18; ++i) {
        if (((s >> i) & 1) == 0) {
            cond.push_back({ i, 0 });
        }
        if (((t >> i) & 1) == 1) {
            cond.push_back({ i, 1 });
        }
    }
    vector<unordered_map<long long, long long>> dp(k + 1);
    for (int i = 0; i <= k; ++i) {
        dp[i].reserve(1 << 20);
    }
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        long long mask = 0;
        for (int j = 0; j < (int)cond.size(); ++j) {
            if (((a[i] >> cond[j].first) & 1) == cond[j].second) {
                mask ^= 1LL << j;
            }
        }
        for (int j = k - 1; j >= 0; --j) {
            for (auto& l : dp[j]) {
                dp[j + 1][l.first | mask] += l.second;
            }
        }
    }
    long long ans = 0;
    for (auto& i : dp) {
        ans += i[(1LL << (int)cond.size()) - 1];
    }

    cout << ans << '\n';

    return 0;
}

