int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N,K,S,T; cin >> N >> K >> S >> T;
    vector<int> A;
    for (;N--;){
        int a; cin >> a;
        bool ok=true;
        for (int j=0;j<18;++j){
            if ((S&1<<j)&&!(a&1<<j)) ok=false;
            if (!(T&1<<j)&&(a&1<<j)) ok=false;
        }
        if (ok) A.emplace_back(a);
    }
    vector<int> diff;
    for (int i=0;i<18;++i){
        if ((S&1<<i)&&!(T&1<<i)){
            cout << 0 << '\n';
            return 0;
        }
        if (!(S&1<<i)&&(T&1<<i)){
            diff.emplace_back(i);
        }
    }
    N=A.size();
    vector<vector<ll>> choose(N+1,vector<ll>(N+1,0));
    for (int i=1;i<=N;++i){
        choose[i][0]=1;
        for (int j=0;j<min(K,i);++j){
            choose[i][j+1]=choose[i][j]*(i-j)/(j+1);
        }
        for (int j=0;j<N;++j) choose[i][j+1]+=choose[i][j];
    }
    int M=diff.size();
    ll ans=0;
    for (int mask=0;mask<(1<<M);++mask){
        map<int,int> mp;
        for (int i=0;i<N;++i){
            int cnt=0;
            for (int j=0;j<M;++j){
                if (mask&1<<j){
                    cnt|=((A[i]&1<<diff[j])>>diff[j])<<j;
                }
            }
            ++mp[cnt];
        }
        int flag=__builtin_popcount(mask);
        for (auto p:mp){
            if (flag&1) ans-=choose[p.second][min(N,K)]-1;
            else ans+=choose[p.second][min(N,K)]-1;
        }
    }
    cout << ans << '\n';
}

