int main() {
	scanf("%d%d%d%d",&n,&k,&s,&t);

	for (int i = 0; i <= n; i++)
		D[i][0] = C[i][0] = 1;
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= i; j++) {
			C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
			D[i][j] = D[i][j - 1] + C[i][j]; 
		}
	for (int i = 1, x; i <= n; i++) {
		scanf("%d",&x);
		if ((x & s) == s && (x & t) == x)
			a[++tot] = x;
	} 
	t ^= s;
	int cnt = 0;
	for (int j = 0; j < 18; j++)
		if (t >> j & 1) cnt++;
	//printf("%d %d\n",cnt,tot);
	for (int i = 1; i <= tot; i++) {
		int val = 1, sum = 0;
		for (int j = 0; j < 18; j++) {
			if ((a[i] >> j & 1) && (t >> j & 1))
				sum += val;
			if (t >> j & 1)
				val *= 2;
		}
		a[i] = sum;
	}
	ll ans = 0;
	for (int i = 0; i < (1 << cnt); i++)
		vis[i] = 0;
	for (int t = 0; t < (1 << cnt); t++) {
		int s = 1;
		for (int j = 0; j < cnt; j++)
			if (t >> j & 1) s *= -1;
		ll sum = 0;
		for (int i = 1; i <= tot; i++) {
			sum -= D[vis[a[i] & t]][min(vis[a[i] & t],k)];
			vis[a[i] & t]++;
			sum += D[vis[a[i] & t]][min(vis[a[i] & t],k)];
		}
		//if (t == 0) printf("****%lld %lld\n",vis[0],C[5][5]);
		for (int i = 1; i <= tot; i++)
			vis[a[i] & t]--;
		//printf("%lld %lld\n",t,s * sum);
		ans += s * sum;
	}
	printf("%lld\n",ans);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int K = 18, N = 55;

vector<int> vv[1<<K];

long long C[N][N];

void pre() {
    for (int i=0; i<N; i++) C[i][0] = 1;
    for (int i=1; i<N; i++)
        for (int j=1; j<N; j++)
            C[i][j] = C[i-1][j-1] + C[i-1][j];

    for (int i=0; i<N; i++)
        for (int j=1; j<N; j++)
            C[i][j] += C[i][j-1];
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    pre();


    int n, K, S, T;
    cin>>n>>K>>S>>T;

    if ( (S&T) != S) {
        cout<<0<<endl;
        return 0;
    }

    for (int i=0; i<n; i++) {
        int x;
        cin>>x;

        if ((x&S) != S) continue;
        if ((x&T) != x) continue;

        for (int mask = 0; mask < (1<<K); mask++) {
            if ((mask&S) != S) continue;
            if ((mask&T) != mask) continue;
            int ans = 0;
            for (int i=0; i<K; i++) {
                bool si = S & (1<<i);
                bool ti = T & (1<<i);
                if (si == ti)   continue;
                if ((mask & (1<<i)) == 0)       ans |= x&(1<<i);
            }
            vv[mask].push_back(ans);
        }
    }

    int ans = 0;
    for (int mask = 0; mask < (1<<K); mask++) {
        if ((mask&S) != S) continue;
        if ((mask&T) != mask) continue;
        sort(vv[mask].begin(), vv[mask].end());

        long long ww = 0;
        while (vv[mask].size()) {
            int last = vv[mask].back();
            int cnt = 0;
            while (vv[mask].size() && vv[mask].back() == last)  cnt++, vv[mask].pop_back();

            ww += C[cnt][K];
        }

        int bc = __builtin_popcount(mask);
        if (bc%2)   ans += ww;
        else        ans -= ww;
    }
    cout<<abs(ans)<<endl;
}

