int n, a[55], k, s, t;
LL comb[55][55];
LL hv[25];
LL ab[262144], ob[262144];

int main()
{
	scanf("%d%d%d%d", &n, &k, &s, &t);
	rep(i, n) scanf("%d", &a[i]);
	if((s & t) != s) {
		printf("0\n");
		return 0;
	}
	comb[0][0] = 1;
	rep(i, n + 1) rep(j, n + 1) {
		comb[i + 1][j] += comb[i][j];
		comb[i + 1][j + 1] += comb[i][j];
	}
	rep(i, n + 1) {
		comb[i][0] = 0;
		rep1(j, n) comb[i][j] += comb[i][j - 1];
	}

	rep(i, n) rep(j, 18) if(a[i] >> j & 1) hv[j] |= 1LL << i;
	rep(i, 262144) {
		ab[i] = (1LL << n) - 1;
		rep(j, 18) if(i >> j & 1) ab[i] &= hv[j];
		ob[i] = (1LL << n) - 1;
		rep(j, 18) if(!(i >> j & 1)) ob[i] &= ~hv[j];
	}
	t ^= s;

	LL ans = 0;
	for(int i = t; i != -1; i = i - 1 & t) {
		for(int j = i; j != -1; j = j - 1 & i) {
			if(__builtin_parity(t ^ i ^ j)) ans -= comb[__builtin_popcountll(ab[j | s] & ob[i | s])][k];
			else ans += comb[__builtin_popcountll(ab[j | s] & ob[i | s])][k];
			if(j == 0) break;
		}
		if(i == 0) break;
	}
	printf("%lld\n", ans);
	return 0;
}

