      for (int j = 1; j <= i; ++j) {
         C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
         if (j <= K) ways[i] += C[i][j];
      }
   }
   ll ans = 0;
   for (int mask = 0; mask < (1 << 18); ++mask) {
      if ((mask & (S ^ T)) != mask) continue;
      map<int, int> cnts;
      for (int i = 0; i < N; ++i) {
         if ((A[i] & S) != S) continue;
         if ((A[i] | T) != T) continue;
         ++cnts[A[i] & mask];
      }
      int cf = __builtin_popcount(mask) & 1 ? -1 : 1;
      for (auto z : cnts) ans += cf * ways[z.second];
   }
   cout << ans << "\n";
}

