signed main() {
	INIT;

	VAR(int, n, k);
	VAR(u64, s, t);
	VEC(u64, a, n);

	const int L = 18;
	const int MASK = (1ull << L) - 1;
	dp[0][MASK << L] = 1;

	REP(j, k + 1) dp[j].reserve(1ull << L);

	REP(i, n) RREP(j, k) {
		for (const auto& p : dp[j]) {
			u64 bit, sum;
			std::tie(bit, sum) = p;

			bit &= (a[i] << L) + MASK;
			bit |= a[i];
			if (((bit >> L) & s) != s) continue;
			if ((~(bit & MASK) & ~t) != ~t) continue;
			dp[j + 1][bit] += sum;
		}
	}
	u64 ans = 0;
	const u64 bit = (s << L) + t;
	REP(j, k + 1) ans += dp[j][bit];
	OUT(ans)BR;

	return 0;
}

