void solv()
{
    for (int i = 0; i < N; ++i)
    {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
    }
    scanf("%d%d", &n, &k);
    scanf("%d%d", &s, &t);
    for (int i = 0; i < n; ++i)
        scanf("%d", &a[i]);
