const int mod=1000000007,MAX=200005,INF=1<<30;

ll inv[MAX],fac[MAX],finv[MAX];

void make(){

    fac[0]=fac[1]=1;
    finv[0]=finv[1]=1;
    inv[1]=1;

    for(int i=2;i<MAX;i++){
        inv[i]=mod-inv[mod%i]*(mod/i)%mod;
        fac[i]=fac[i-1]*(ll)i%mod;
        finv[i]=finv[i-1]*inv[i]%mod;
    }

}

ll comb(ll a,ll b){
    if(a<b) return 0;
    return fac[a]*(finv[b]*finv[a-b]%mod)%mod;
}

ll perm(ll a,ll b){
    if(a<b) return 0;
    return fac[a]*finv[a-b]%mod;
}

int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);

    make();

    int N,K,S,T;cin>>N>>K>>S>>T;

    if(S&(~T)){
        cout<<0<<endl;
        return 0;
    }
    vector<int> A;

    for(int i=0;i<N;i++){
        int a;cin>>a;

        if((S&a)!=S) continue;
        if((a|T)!=T) continue;

        A.push_back(a);
    }

    N=si(A);

    for(int a:A) a-=S;
    T-=S;
    S=0;

    vector<int> bi;
    for(int i=0;i<20;i++) if(T&(1<<i)) bi.push_back(i);
    for(int &a:A){
        int to=0;
        for(int i=0;i<si(bi);i++){
            if(a&(1<<bi[i])) to+=(1<<i);
        }
        a=to;
    }
    T=(1<<si(bi))-1;

    int L=si(bi);

    if(L==0){
        ll res=0;
        for(int j=1;j<=K;j++){
            res+=comb(N,j);
        }
        cout<<res<<endl;
        return 0;
    }

    if(K==1){
        cout<<0<<endl;
        return 0;
    }

    ll res=0;

    vector<ll> sum(L+1);

    for(int i=0;i<N;i++){
        for(int bit=0;bit<(1<<L);bit++){
            int cnt=0;
            for(int j=i+1;j<N;j++){
                if(((~(A[i]^A[j]))&bit)==bit) cnt++;
            }

            for(int j=0;j<K;j++){
                sum[__builtin_popcount(bit)]+=comb(cnt,j);
            }
        }
    }

    for(int j=0;j<=L;j++){
        if(j&1) res-=sum[j];
        else res+=sum[j];
    }

    cout<<res<<endl;

}

