        }
    }
    for(int mask1=t;mask1>=0;mask1=(mask1-1) & t)
    {
        for(int mask2=mask1;mask2>=0;mask2=(mask2-1) & mask1)
        {
            int o=(z2[mask1] & z1[mask2]).count();
            int h=1;
            int x=__builtin_popcount(mask1)+__builtin_popcount(mask2)+__builtin_popcount(t);
