inline int dfs(re int p,re int x,re int y,re int cnt){
	re long long hsh=1ll*(1ll<<18)*x+y+(1ll<<40)*cnt;
	if(v.find(hsh)!=v.end())return v[hsh];
	if(p==0){
		if(x==s&&y==t)return 1;
