typedef long long ll;
const int maxn = 55;
int n, K, S, T, a[maxn], b[maxn];
ll ans, C[maxn][maxn], coef[maxn], cnt[1 << 18];

int main() {
    scanf("%d %d %d %d", &n, &K, &S, &T);
    auto chk = [&](int x, int y) { return (x & y) == y; };
    if (!chk(T, S)) printf("0\n"), exit(0);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        if (!chk(a[i], S) || !chk(T, a[i])) { i--, n--; continue; }
    }
    T ^= S;
    for (int i = 1; i <= n; i++) {
        a[i] ^= S;
        for (int j = 0; j < 18; j++) if (T >> j & 1) {
            if (!(a[i] >> j & 1)) b[i] |= 1 << j;
        }
    }
    auto FWT = [&](ll *a, int lim) {
        for (int i = 1; i < lim; i <<= 1) {
            for (int j = 0; j < lim; j += i << 1) {
                for (int k = 0; k < i; k++) {
                    a[j + k] += a[i + j + k];
                }
            }
        }
    };
    for (int i = 0; i <= n; i++) {
        for (int j = C[i][0] = 1; j <= i; j++) {
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
        for (int j = 0; j < K; j++) {
            coef[i] += C[i][j];
        }
    }
    for (int i = 1; i <= n; i++) {
        memset(cnt, 0, sizeof(cnt));
        for (int j = i + 1; j <= n; j++) {
            cnt[b[i] ^ a[j]]++;
        }
        FWT(cnt, 1 << 18);
        for (int j = 0; j < 1 << 18; j++) {
            if (__builtin_popcount(j) & 1) ans -= coef[cnt[j]];
            else ans += coef[cnt[j]];
        }
    }
    printf("%lld\n", ans);
    return 0;
}

