struct Xorshift {
  uint64_t x = 88172645463325252LL;
  unsigned next_int() {
    x = x ^ (x << 7);
    return x = x ^ (x >> 9);
  }
  unsigned next_int(unsigned mod) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % mod;
  }
  unsigned next_int(unsigned l, unsigned r) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % (r - l + 1) + l;
  }
  double next_double() {
    return double(next_int()) / UINT_MAX;
  }
} rnd;

template<typename T>
void shuffle_vector(vector<T>& v, Xorshift& rnd) {
  int n = v.size();
  for (int i = n - 1; i >= 1; i--) {
    int r = rnd.next_int(i);
    swap(v[i], v[r]);
  }
}



unsigned popcount(unsigned bits) {
  bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
  bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
  bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
  bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
  return (bits & 0x0000ffff) + (bits >> 16 & 0x0000ffff);
}

int N, K, S, T;
vector<int> A;
ll ans = 0;

// pos 個目以降から選ぶ いままで k 個選んだ
void rec(int pos, int k, int s, int t) {
  if (1 <= k && k <= K && s == S && t == T) {
    ans++;
  }
  if (pos == N || k == K) return;
  for (int p = pos; p < N; p++) {
    // p を選べるか？
    if ((s & A[p] & S) != S || (t | A[p] | T) != T) continue;
    // 選べる
    rec(p + 1, k + 1, s & A[p], t | A[p]);
  }
}

