#include <bits/stdc++.h>
using namespace std;
#define ll long long
int main(){
  ll N,K,S,T;
  cin>>N>>K>>S>>T;
  vector<ll> vec(0);
  for(ll i=0;i<N;i++){
    ll a;
    cin>>a;
    ll b=a|T;
    ll c=a&S;
    if(b==T && c==S){//論理積がSと一致、論理和がTと一致するならvecに放り込む
      vec.push_back(a);
    }
  }
  ll ans=0;
  ll n=vec.size();
  for(ll bit=1;bit<(1<<n);bit++){//bit全探索
    ll x,y;//xは論理積、yは論理和
    ll count=0;//何個選ぶか
    queue<ll> q;
    for(ll i=0;i<n;++i){
      if(bit&(ll)(1<<i)){
        q.push(i);
      }
    }
    if(q.size()>K){continue;}
    while(!q.empty()){
      if(count==0){//一個目はvecの値をそのまま
        x=vec.at(q.front());
        y=vec.at(q.front());
        count++;
      }else{//2個目以降があるなら、それぞれ論理積と論理和を取って更新   
        x=x&vec.at(q.front());
        y=y|vec.at(q.front());
      }
      q.pop();
    }
    if(x==S && y==T){ans++;}//それぞれS,Tと一致してかつ選んだのがK個以下ならans++をする
  }
  cout<<ans<<endl;
}

