void solve(vector<int> ve,int b,int k){
	int n=ve.size();
	//for(auto v:ve)cout<<v<<endl;
	vector<int> P(b);
	vector<int> Q(b);

	for(int i=0;i<n;i++){
		for(int j=0;j<b;j++){
			if(ve[i]&(1<<j))P[j]+=(1ll<<i);
			else Q[j]+=(1ll<<i);
		}
	}
//	for(auto v:P)cout<<v<<endl;
//	for(auto v:Q)cout<<v<<endl;
	map<int,int>dp[20][2];
	dp[0][0][(1ll<<n)-1]=1;
	for(int i=0;i<b;i++){
		for(int j=0;j<2;j++){
			for(auto it:dp[i][j]){
				 dp[i+1][j][it.first]+=it.second;
				 dp[i+1][j^1][it.first&P[i]]+=it.second;	
				 dp[i+1][j^1][it.first&Q[i]]+=it.second;
			}
		}
	}
	int A[60]={};
	for(int j=0;j<2;j++)for(auto it:dp[b][j]){
		int d=__builtin_popcount(it.first);
		if(d==0)continue;
	//	cout<<it.first<<" "<<it.second<<endl;
		for(int i=1;i<=d;i++)A[i]+=co[d][i]*it.second*(j?(-1):1);
	}
	int ans=0;
	for(int i=1;i<=k;i++)ans+=A[i];
	cout<<ans<<endl;

}
