std::unordered_map<u64, u64> dp[51];

signed main() {
	INIT;

	VAR(int, n, k);
	VAR(u64, s, t);
	VEC(u64, a, n);

	const int L = 18;
	dp[0][((1ull << L) - 1) << L] = 1;

	REP(j, k + 1) dp[j].reserve(1 << L);
	REP(i, n) RREP(j, k) {
		for (auto& p : dp[j]) {
			u64 bit, sum;
			std::tie(bit, sum) = p;

			bit &= (a[i] << L) + (1ull << L) - 1;
			bit |= a[i];
			if (((bit >> L) & s) != s) continue;
			if ((~(bit & ((1ull << L) - 1)) & ~t) != ~t) continue;
			dp[j + 1][bit] += sum;
		}
	}
	u64 ans = 0;
	const u64 bit = (s << L) + t;
	REP(j, k + 1) ans += dp[j][bit];
	OUT(ans)BR;

	return 0;
}

