ll combi[N][N], csum[N][N];
void solve() {
  int n,k,s,t;
  scanf("%d %d %d %d ", &n,&k,&s,&t);
  if((t&s)!=s) {
    printf("0\n");
    return;
  }
  for(int i=0;i<N;++i) {
    combi[i][0] = 1;
    for(int j=1;j<i;++j) {
      combi[i][j] = combi[i-1][j] + combi[i-1][j-1];
    }
    combi[i][i] = 1;
    for(int j=1;j<N;++j) {
      csum[i][j] = csum[i][j-1] + combi[i][j];
    }
  }
  vector<int> in;
  for(int i=0;i<n;++i) {
    int a;
    scanf("%d ", &a);
    if( ((a&s) ==s )&& ( (t&a) ==a) ) {
      in.push_back(a^s);
    }
  }
  t^=s;
  int tb = 0;
  for(int b=0;b<B;++b) {
    if(t&(1<<b)) {
      ++tb;
    }
  }
  for(int i=0;i<in.size();++i) {
    int sum = 0, cur = 1;
    for(int b=0;b<B;++b) {
      if(in[i]&(1<<b)) {
        sum += cur;
      }
      if(t&(1<<b)) {
        cur = cur*2;
      }
    }
    in[i] = sum;
  }
  ll ret = 0;
  for(int bit=0;bit<(1<<tb);++bit) {
    parity[bit] = parity[bit/2];
    if(bit&1) {
      parity[bit] ^= 1;
    }
    ll sum = 0;
    for(int a : in) {
      sum -= csum[cc[(bit&a)]][min(cc[(bit&a)],k)];
      ++cc[bit&a];
      sum += csum[cc[(bit&a)]][min(cc[(bit&a)],k)];
    }
    for(int a : in) {
      --cc[bit&a];
    }
    if(parity[bit]) {
      sum *= -1;
    }
    ret += sum;
  }
  printf("%lld\n", ret);
}

