struct sp64_hash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }
    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = splitmix64(((uint64_t) new char | 1)
                * chrono::steady_clock::now().time_since_epoch().count());
        return splitmix64(x ^ FIXED_RANDOM);
    }
};
template<class K> struct sp64_pair_hash {
    size_t operator()(const pair<K, K>& x) const {
        static_assert(sizeof(K) <= 4);
        static sp64_hash sp64;
        return sp64(((uint64_t) x.first << 32) ^ x.second);
    }
};

template<class K, class V> using umap = gp_hash_table<K, V, sp64_hash>;

int main() {
    setIO();

    const int B = 18;
    const int M = 1 << B;

    int N, K, S, T; re(N, K, S, T);
    vi a(N); re(a);

    vvll ncr(N+1, vll(N+1));
    ncr[0][0] = 1;

    FOR (n, 1, N + 1) {
        F0R (r, n + 1) {
            ncr[n][r] = ncr[n-1][r];
            if (r) ncr[n][r] += ncr[n-1][r-1];
        }
    }

    vll pick(N + 1);
    FOR (v, 1, N + 1)
        FOR (c, 1, min(K, v) + 1)
            pick[v] += ncr[v][c];

    gp_hash_table<pii, int, sp64_pair_hash<int>> table;
    trav (e, a) {
        for (int s = e; s >= 0; s = (s-1)&e) {
            if ((S | s) != s) { if (!s) break; continue; }
            for (int t = e; t < M; t = (t+1)|e) {
                if ((t | T) != T) continue;
                table[{s,t}] += 1;
            }
            if (!s) break;
        }
    }

    ll ans = 0;

    trav (e, table) {
        auto [s, t] = e.f;

        int td = __builtin_popcount(T) - __builtin_popcount(t);
        int sd = __builtin_popcount(s) - __builtin_popcount(S);

        bool sign = (td ^ sd)&1;

        int betw = e.s;
        if (sign)
            ans -= pick[betw];
        else
            ans += pick[betw];
    }

    ps(ans);

    return 0;
}

