int main() {
	int n, k, S, T;
	scanf("%d%d%d%d", &n, &k, &S, &T);
	vector<int> A(n);
	for (int i = 0; i < n; ++i) {
		scanf("%d", &A[i]);
	}
	if ((T & S) != S) {
		printf("0\n");
		return 0;
	}
	vector<int> bits;
	for (int j = 0; j < 18; ++j) {
		if ((T & (1 << j)) && !(S & (1 << j))) bits.push_back(j);
	}
	int s = bits.size();
	vector<int> B;
	for (int i = 0; i < n; ++i) {
		if (~T & A[i]) continue;
		if ((S & A[i]) != S) continue;
		int b = 0;
		for (int j = 0; j < s; ++j) {
			if (A[i] & (1 << bits[j])) b |= 1 << j;
		}
		B.push_back(b);
	}
	int req = (1 << s);
	int m = B.size();
	int ans = 0;
	for (int i = 0; i < m; ++i) {
		vector<int> V;
		for (int j = i + 1; j < m; ++j) {
			int d = B[j] ^ B[i];
			V.push_back(d);
		}
		// 0..K-1 things ORing to req-1.
		vector<vector<int>> dp(k, vector<int>(req));
		dp[0][0] = 1;
		for (int x : V) {
			for (int c = k - 1; c; --c) {
				for (int j = 0; j < req; ++j) {
					dp[c][j | x] += dp[c - 1][j];
				}
			}
		}
		for (int c = 0; c < k; ++c) ans += dp[c][req - 1];
	}
	printf("%d\n", ans);
}

