ll dp[55][400000];
ll C(ll n,ll k){
	if(n<k)return 0;
	if(k<0)return 0;
	return dp[k][n-k];
}
void init(){
	rep(i,55)rep(j,400000){
		if(i==0&&j==0){
			dp[i][j]=1;
		}
		else{
			dp[i][j]=0;
			if(i)dp[i][j]+=dp[i-1][j];
			if(j)dp[i][j]+=dp[i][j-1];
		}
	}
}

ll n,k,a[50],s,t;

ll calc(ll x){
	ll res=0;
	for(ll i=1;i<=k;i++){
		res+=C(x,i);
	}
	return res;
}

int main(){
	init();
	cin>>n>>k>>s>>t;
	rep(i,n)cin>>a[i];
	bool alv[50];
	rep(i,n)alv[i]=1;
	vector<ll> dig;
	rep(i,18){
		bool ss=s&(1<<i);
		bool tt=t&(1<<i);
		if(ss==1&&tt==0){
			cout<<0<<endl;
			return 0;
		}
		if(ss==1){
			rep(j,n)if(!(a[j]&(1<<i)))alv[j]=0;
		}
		else if(tt==0){
			rep(j,n)if(a[j]&(1<<i))alv[j]=0;
		}
		else{
			dig.push_back(i);
		}
	}
	int m=0;
	rep(i,n){
		if(alv[i]){
			a[m]=a[i];
			m++;
		}
	}
	n=m;
	ll ans=0;
	rep(i,(1<<(int)dig.size())){
		bool us[18];
		rep(j,18)us[j]=0;
		rep(j,dig.size()){
			if(i&(1<<j)){
				us[dig[j]]=1;
			}
		}
		unordered_map<ll,ll> mas;
		rep(j,n){
			ll res=0;
			rep(r,18){
				if(us[r]){
					res+=a[j]&(1<<r);
				}
			}
			mas[res]++;
		}
		ll res=0;
		for(auto t:mas){
			res+=calc(t.second);
		}

		int pcnt=0;
		rep(j,18)pcnt+=us[j];
		if(pcnt%2==0)ans+=res;
		else ans-=res;
	}
	cout<<ans<<endl;
}

