int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    REP(i, 55) REP(j, 55) {
        if(j == 0 || j == i) comb[i][j] = 1;
        else comb[i][j] = comb[i - 1][j] + comb[i - 1][j - 1];
    }
    REP(i, 55) REP(j, 55) if(j) comb[i][j] += comb[i][j - 1];
    int n, k, s, t;
    cin >> n >> k >> s >> t;
    if((s & t) != s) {
        cout << 0 << endl;
        return 0;
    }
    bitset<20> bs_s(s);
    bitset<20> bs_t(t);
    int d = 0;
    REP(i, 20) if(bs_s[i] == 0 && bs_t[i] == 1) d++;
    vector<int> a(n);
    vector<int> b;
    REP(i, n) cin >> a[i];
    REP(i, n) {
        if((s & a[i]) != s) continue;
        if((a[i] & t) != a[i]) continue;
        bitset<20> bs_a(a[i]);
        bitset<20> new_num(0);
        int crt_digit = 0;
        REP(j, 20) {
            if(bs_s[j] == 0 && bs_t[j] == 1) {
                new_num[crt_digit] = bs_a[j];
                crt_digit++;
            }
        }
        b.pb(new_num.to_ulong());
    }
    n = (int)b.size();
    k = min(n, k);
    if(n == 0) {
        cout << 0 << endl;
        return 0;
    }
    if(d == 0) {
        cout << comb[n][k] - 1 << endl;
        return 0;
    }
    set<pair<unsigned, int>> valid_term;
    REP(i, n) FOR(j, 1, (1 << d)) {
        valid_term.insert({(unsigned)j, (j & b[i])});
    }
    ll ans = (comb[n][k] - 1);
    for(auto [mask, tgt]: valid_term) {
        int cnt_cand = 0;
        REP(i, n) {
            if((mask & b[i]) == tgt) cnt_cand++;
        }
        int popc = __builtin_popcount(mask);
        if(popc & 1) ans -= (comb[cnt_cand][min(k, cnt_cand)] - 1);
        else ans += (comb[cnt_cand][min(k, cnt_cand)] - 1);
    }
    cout << ans << endl;
    return 0;
}

