const int BITS = 18;

int N, K, S, T;
int64_t ALL;
vector<int> A;
array<array<int64_t, 2>, BITS> fail;
vector<vector<int64_t>> choose;
vector<int64_t> up_to_K;
int64_t answer;

void recurse(int index, int sign, int64_t mask) {
    if (mask == 0)
        return;

    if (index == BITS) {
        answer += sign * up_to_K[__builtin_popcountll(mask)];
        return;
    }

    recurse(index + 1, sign, mask);
    recurse(index + 1, -sign, mask & fail[index][0]);
    recurse(index + 1, -sign, mask & fail[index][1]);
}

int main() {
    cin >> N >> K >> S >> T;

    if ((S | T) != T) {
        cout << 0 << '\n';
        return 0;
    }

    for (int i = 0; i < N; i++) {
        int a;
        cin >> a;

        if ((a & S) != S || (a | T) != T)
            continue;

        A.push_back(a);
    }

    N = int(A.size());
    K = min(K, N);

    choose.assign(N + 1, vector<int64_t>(N + 1, 0));

    for (int i = 1; i <= N; i++) {
        choose[i][0] = choose[i][i] = 1;

        for (int j = 1; j < i; j++)
            choose[i][j] = choose[i - 1][j] + choose[i - 1][j - 1];
    }

    up_to_K.assign(N + 1, 0);

    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= K; j++)
            up_to_K[i] += choose[i][j];

    ALL = (1LL << N) - 1;

    for (int bit = 0; bit < BITS; bit++) {
        fail[bit] = {ALL, ALL};

        if ((S >> bit & 1) == 0) {
            fail[bit][0] = 0;

            for (int i = 0; i < N; i++)
                if (A[i] >> bit & 1)
                    fail[bit][0] |= 1LL << i;

            if (fail[bit][0] == 0)
                fail[bit][0] = ALL;
        }

        if ((T >> bit & 1) == 1) {
            fail[bit][1] = 0;

            for (int i = 0; i < N; i++)
                if ((A[i] >> bit & 1) == 0)
                    fail[bit][1] |= 1LL << i;

            if (fail[bit][1] == 0)
                fail[bit][1] = ALL;
        }
    }

    dbg(fail);

    answer = 0;
    recurse(0, 1, ALL);
    cout << answer << '\n';
}

