        if (!((A[j] >> i) & 1)) valid[j] = false;
      }
      if (!((T >> i) & 1)) {
        if ((A[j] >> i) & 1) valid[j] = false;
      }
    }
  }
  vi B;
  rep(i, 0, N) if (valid[i]) B.pb(A[i]);
  A.swap(B);
  N = sz(A);

  static int table[51][51];
  rep(n, 0, 51) {
    table[n][0] = 0;
    rep(k, 1, 51) { table[n][k] = table[n][k - 1] + combination[n][k]; }
  }

  static int dp[1 << 18];
  rep(mask, 0, 1 << 18) {
    map<int, int> cnt;
    rep(i, 0, N) cnt[mask & A[i]]++;
    for (auto p : cnt) {
      dp[mask] += table[p.second][K];
    }
    if (mask & overall) dp[mask] = 0;
  }

  int ans = 0;
  rep(s, 0, 1 << 18) {
    if (!dp[s]) continue;
    int p = __builtin_popcount(s);
    if (p % 2) {
      ans -= dp[s];
    } else {
      ans += dp[s];
    }
  }
  cout << ans << endl;
  return (0 ^ _ ^ 0);
}

