    for (int i = 0; i <= n; ++i) {
        c[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            c[i][j] = c[i - 1][j - 1] + c[i - 1][j];
        }
    }
    vector<i64> coef(n + 1);
    for (int i = 0; i <= n; ++i) {
        coef[i] = accumulate(begin(c[i]) + 1, begin(c[i]) + k + 1, 0LL);
