ll solve() {
    comb[0][0] = 1;
    for (int i = 1; i <= 50; i++) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
