  int n, k, s, t;
  cin >> n >> k >> s >> t;
  rep(i, 1000000) {
    cnt[i] = 0;
  }

  rep(i, n + 1) rep(j, n + 1) c[i][j] = 0;
  rep(i, n + 1) {
    c[i][0] = 1;
    for (int j = 1; j <= i; j++) {
      c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
    }
  }
  rep(i, n + 1) {
    cc[i][0] = 0;
    for (int j = 1; j <= n; j++) {
      cc[i][j] = cc[i][j - 1] + c[i][j];
    }
  }

  // if si = 1 and ti = 0, no set meets the condition;
  // if si = 0 and ti = 1, the i-th bit is to be considered;
  vector<int> bit; int maxb = -1;
  rep(i, 20) {
    if (s&(1<<i) && !(t&(1<<i))) { cout << 0 << endl; return 0; }
    else if (!(s&(1<<i)) && t&(1<<i)) { bit.push_back(i); maxb++; }
  }

  // if aij = 0 and sj = 1 or aij = 1 and tj = 0, ai is not included in any set;
  // only bits included in bit are added to a;
  vector<int> a;
  rep(i, n) {
    int ai;
    cin >> ai;
    bool flug = true;
    rep(j, 20) {
      if ((!(ai&(1<<j)) && s&(1<<j)) || (ai&(1<<j) && !(t&(1<<j)))) { flug = false; }
    }
    if (flug) {
      a.push_back(0);
      rep(j, bit.size()) {
        int aij = ai & (1<<bit[j]);
        if (aij) {
          maxb = max( maxb, j );
          a[a.size() - 1] += 1<<j;
        }
      }
    }
  }
  if (a.size() == 0) { cout << 0 << endl; return 0; }
/*
