rep(i, bit.size()) cout << " " << bit[i]; cout << endl;
cout << "a ";
rep(i, a.size()) cout << a[i] << " "; cout << endl; cout << "maxb " << maxb << endl;
*/
  int ans = 0;
  rep(i, 1<<(maxb + 1)) {
    int odd = 0;
    rep(l, maxb + 1) odd += (i>>l) & 1;
    rep(l, a.size()) {
      int ani = a[l]&i;
      cnt[ani]++;
      cntid[l] = ani;
    }
    //cout << "i:" << i << ":"; rep(l, 1<<(maxb + 1)) cout << " " << cnt[l]; cout << endl;
    rep(l, a.size()) {
      // choose at most k element from a set of size cnt[cntid[l]];
      ans += (odd % 2 == 0 ? 1 : -1) * cc[cnt[cntid[l]]][k];
      cnt[cntid[l]] = 0;
    }
  }

  cout << ans << endl;

  return 0;
}

