			else B.push_back(a);
		}
	}
	for(int i=0;i<A.size();i++) for(int j=1<<i;j<(2<<i);j++) {
		BB[j]=BB[j^(1<<i)]+1;
		AND[j]=AND[j^(1<<i)]&A[i];
		OR[j]=OR[j^(1<<i)]|A[i];
		if(AND[j]==S) D1[BB[j]][OR[j]]++;
	}
	for(int i=0;i<B.size();i++) for(int j=1<<i;j<(2<<i);j++) {
		AND[j]=AND[j^(1<<i)]&B[i];
