	for(int p=1;p<=B.size();p++) for(int i=0;i<SZ;i++) D2[p][i]+=D2[p-1][i];
	for(int p=min(K-1,25);p>0;p--) for(int i=0;i<SZ;i++) ans+=1LL*D1[p][i]*D2[min(K-p,25)][~i&T];
	cout<<ans<<'\n';
	return 0;
}

