	u32 s = ri(); // and
	u32 t = ri(); // or
	if ((s & t) != s) {
		puts("0");
		return 0;
	}
	u32 a[n];
	for (auto &i : a) i = ri();

	u32 mask = ~s & t;
	std::vector<int> all;

	std::vector<int> revised;
	for (int i = 0; i < 18; i++) if (mask >> i & 1) all.push_back(i);
	int m = all.size();
	for (auto i : a) {
		if ((i & s) != s) continue;
		if (~t & i) continue;
		int cur = 0;
		for (int j = 0; j < (int) all.size(); j++) if (i >> all[j] & 1) cur |= 1 << j;
		revised.push_back(cur);
	}
	n = revised.size();
	printf("%" PRId64 "\n", revised.size() <= 0 ? gu(m, k, revised) : fast(m, k, revised));

	return 0;
}

