	int n, k, s, t;
	scanf("%d%d%d%d", &n, &k, &s, &t);
	if ((s & t) != s) {
		puts("0");
		return 0;
	}
	for (int i = 0; i < n; i++) {
		scanf("%d", &a[i]);
	}
	for (int i = 0; i < n; i++) {
		if ((a[i] & s) == s && (a[i] | t) == t) {
			v.push_back(a[i]);
		}
	}
	int ma = (1 << 18) - 1;
	long long ans = 0;
	for (int i = 0; i < v.size(); i++) {
		dp[0][i][0] = 1;
	}
	int y = 0, z = 1;
	for (int i = 0; i < k; i++) {
		for (int j = 0; j < v.size(); j++) {
			for (int l = 0; l < 1 << 18; l++) {
				dp[z][j][l] = 0;
			}
		}
		for (int j = 0; j < v.size(); j++) {
			for (int l = 0; l < 1 << 18; l++) {
				if (dp[y][j][l] == 0) continue;
				for (int m = j + 1; m < v.size(); m++) {
					int o = v[j] & ~l, e = (ma ^ v[j]) & ~l;
					int no = o & v[m], ne = e & ~v[m];
					int nl = ma ^ no ^ ne;
					dp[z][m][nl] += dp[y][j][l];
				}
			}
			ans += dp[y][j][s^t];
		}
		for (int j = 0; j < v.size(); j++) {
			for (int l = 0; l < 1 << 18; l++) {
				dp[y][j][l] = dp[z][j][l];
			}
