int my_popcount(long long x)
{
	int cnt = 0;
	long long cur = 1LL;
	for (int i = 0; i < 63; i++) {
		if (x & cur) cnt++;
		cur = cur << 1;
	}
	return cnt;
}

void fun(int pos, int sign, long long candi)
{
	if (pos == 18) {
		long long u = (acc[my_popcount(candi)]) * sign;
		ans += u;
		//tmp[tc].pb(u);

	}
	else {
		fun(pos + 1, sign, candi);
		fun(pos + 1, -sign, candi & (occ[pos][0]));
	}
}

