ll solve (ll n, ll k) {
	if (k > n || n < 0 || k < 0) {
		nck[n][k] = 0;
		return 0;
	}
	if (nck[n][k] != -1) {
		return nck[n][k];
	}
	nck[n][k] = solve (n - 1, k) + solve (n - 1, k - 1);
	return nck[n][k];
}

