int choose(int N, int C){
	if(C > N) return 0;
	if(N == C) return 1;
	if(C == 0) return 1;
	if(memo[N][C] != 0) return memo[N][C];
	return memo[N][C] = choose(N-1,C) + choose(N-1,C-1);
}

