vector<int> tr;

inline int addMod(int a, int b) {
	return (a += b) >= mod ? a - mod : a;
}

inline ll quickpow(ll base, ll pw) {
	ll ret = 1;
	while (pw) {
		if (pw & 1) ret = ret * base % mod;
		base = base * base % mod, pw >>= 1;
	}
	return ret;
}

template <class T>
inline void read(T &x) {
	x = 0;
	char ch = getchar(), w = 0;
	while (!isdigit(ch)) w = (ch == '-'), ch = getchar();
	while (isdigit(ch)) x = (x << 1) + (x << 3) + (ch ^ 48), ch = getchar();
	x = w ? -x : x;
	return;
}

inline int popc(ll w) {
	w = (w & 0x5555555555555555) + ((w & 0xaaaaaaaaaaaaaaaa) >> 1);
	w = (w & 0x3333333333333333) + ((w & 0xcccccccccccccccc) >> 2);
	w = (w & 0x0f0f0f0f0f0f0f0f) + ((w & 0xf0f0f0f0f0f0f0f0) >> 4);
	w = (w & 0x00ff00ff00ff00ff) + ((w & 0xff00ff00ff00ff00) >> 8);
	w = (w & 0x0000ffff0000ffff) + ((w & 0xffff0000ffff0000) >> 16);
	w = (w & 0x00000000ffffffff) + ((w & 0xffffffff00000000) >> 32);
	return w;
}

void dfs(ll now, int step, int val) {
	if (!now) return;
	if (step == num) {
		ans += val * f[popc(now)];
		return;
	}
	dfs(now, step + 1, val);
	dfs(now & bs[step], step + 1, -val);
	dfs(now & rbs[step], step + 1, -val);
	return;
}

int main() {
	read(n), read(k), read(s), read(t);
	if ((s & t) != s) {
		cout << "0\n";
		return 0;
	}
	for (R int j = 0; j <= 18; ++j) {
		if ((s & (1 << j)) || (~t & (1 << j))) continue;
		tr.push_back(j), ++num;
	}
	for (R int i = 1; i <= n; ++i) {
		read(a[i]);
		if ((a[i] & s) != s || (a[i] & t) != a[i])
			continue;
		for (R int j = 0; j < num; ++j)
			if (a[i] & (1 << tr[j]))
				bs[j] |= 1ll << m;
		++m;
	}
	for (R int i = 0; i < num; ++i)
		rbs[i] = ((1 << m) - 1) ^ bs[i];
	for (R int i = 0; i <= m; ++i) {
		comb[i][0] = 1;
		for (R int j = 1; j <= i; ++j) {
			comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
			if (j <= k) f[i] += comb[i][j];
		}
	}
	dfs((1ll << m) - 1, 0, 1);
	cout << ans << endl;
	return 0;
}

