int D = 18;

void output(ll ans) {
  cout << ans << endl;
  exit(0);
}

// x includes y
// y is in x
bool includes(ll x, ll y) {
  return ((x & y) == y) != 0;
}

ll del(ll x, int z) {
  return
    (x & ((1ll << z) - 1)) |
    ((x >> (z + 1)) << z);
}

bool getbit(ll x, int z) {
  return !!(x & (1ll << z));
}

auto rekkyo(vector<ll> a) {
  int n = a.size();
  vector<vector<pair<ll, ll>>> res(25);
  for(int i = 0; i < (1 << n); i++) {
    int cnt = 0;
    ll vAND = (1ll << D) - 1;
    ll vOR = 0;
    for(int j = 0; j < n; j++) {
      if((i >> j) & 1) {
        cnt++;
        vAND &= a[j];
        vOR |= a[j];
      }
    }
    res[cnt].emplace_back(vAND, vOR);
  }
  return res;
}

using P = pair<int, ll>;
vector<P> mrg(vector<P> a, vector<P> b) {
  vector<P> r;
  int ai = 0, bi = 0;
  while(ai < a.size() || bi < b.size()) {
    bool chooseA = 0;
    if(ai == a.size()) chooseA = 0;
    else if(bi == b.size()) chooseA = 1;
    else if(a[ai] < b[bi]) chooseA = 1;
    else chooseA = 0;
    if(chooseA) {
      r.push_back(a[ai]);
      ai++;
    } else {
      r.push_back(b[bi]);
      bi++;
    }
  }
  return r;
}

// fzt {{{
// n is power of 2
vector<vector<P>> fzt(vector<vector<P>> a) {
  int n = a.size();
  for(int i = 1; i < n; i <<= 1)
    for(int j = 0; j < n; j++)
      if((j & i) == 0) {
        // a[j] += a[j | i];
        a[j] = mrg(a[j], a[j | i]);
      }
  return a;
}
// }}}

int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  assert(del(0b1011, 0) == 0b101);
  assert(del(0b0011, 1) == 0b001);
  assert(del(0b0011, 2) == 0b011);
  ll n, k, sOR, sAND;
  cin >> n >> k >> sAND >> sOR;
  dump(sAND, sOR);
  vector<ll> a0(n);
  for(int i = 0; i < n; i++) cin >> a0[i];
  vector<ll> a;
  if(!includes(sOR, sAND)) output(0);
  for(int i = 0; i < n; i++) {
    ll t = a0[i];
    dump(t, i);
    dump(includes(sOR, t), includes(t, sAND));
    if(includes(sOR, t) && includes(t, sAND)) {
      int j2 = 0;
      for(int j = 0; j < 18; j++) {
        if(getbit(sOR, j) == 0 || getbit(sAND, j) == 1) {
          t = del(t, j2);
        } else j2++;
      }
      a.push_back(t);
    }
  }
  {
    int j2 = 0;
    for(int j = 0; j < 18; j++) {
      if(getbit(sOR, j2) == 0 || getbit(sAND, j2) == 1) {
        sOR = del(sOR, j2);
        sAND = del(sAND, j2);
        D--;
      } else j2++;
    }
  }
  n = a.size();
  if(n == 0) output(0);
  dump(n, a);

  vector<ll> b;
  for(int i = 0; i < n / 2; i++) {
    b.push_back(a.back());
    a.pop_back();
  }
  dump(D, a, b);
  // (and, or)
  auto ra = rekkyo(a);
  auto rb = rekkyo(b);

  vector<vector<P>> f(1 << D);
  for(int i = 0; i < k; i++) {
    for(auto rbx: rb[i]) {
      auto &it = f[rbx.second];
      P p(i, rbx.first);
      it.insert(lower_bound(it.begin(), it.end(), p), p);
    }
  }

  auto t = fzt(f);
  dump(ra);
  dump(rb);
  dump(t);
  dump(sAND, sOR);

  ll ans = 0;
  for(int i = 0; i <= k; i++) {
    for(auto&rax: ra[i]) {
      auto [tAND, tOR] = rax;
      auto tORrev = tOR ^ ((1ll << D) - 1);
      dump(tORrev);
      auto & it = t[tORrev];
      for(int j = 0; j < it.size() && it[j].first <= k - i; j++) {
        dump(it[j].second, tAND);
        if((it[j].second & tAND) == sAND) {
          ans++;
        }
      }
    }
  }

  output(ans);
  return 0;
}

