const int L = 18;
const int M = (1 << L);
const int N = 52;
ll C[N][N];
ll D[N];
int cnt[M];
int ppc[M];
int n, k;
int S, T;

ll solve(vector<int> b) {
	/*
	printf("solve");
	for (int x : b)
		printf(" %d", x);
	printf("\n");
	*/
	for (int i = 0; i < M; i++)
		cnt[i] = 0;
	for (int x : b)
		cnt[x]++;
	for (int k = 0; k < L; k++)
		for (int mask = 0; mask < M; mask++)
			if (((mask >> k) & 1) == 1)
				cnt[mask] += cnt[mask ^ (1 << k)];
	ll ans = 0;
	for (int mask = 0; mask < M; mask++) {
		if ((mask & T) != mask) continue;
		if (ppc[T ^ mask] % 2 == 0)
			ans += D[cnt[mask]];
		else
			ans -= D[cnt[mask]];
	}
	return ans;
}

