		ppc[i] = ppc[i / 2] + (i & 1);

	scanf("%d%d%d%d", &n, &k, &S, &T);
	if ((S & T) != S) {
		printf("0\n");
		return 0;
	}
	for (int i = 0; i < N; i++)
		C[i][0] = C[i][i] = 1;
	for (int i = 1; i < N; i++)
		for (int j = 1; j < i; j++)
			C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
	for (int i = 0; i < N; i++)
		for (int j = 0; j < k; j++)
			D[i] += C[i][j];

	vector<int> a;
	for (int i = 0; i < n; i++) {
		int x;
		scanf("%d", &x);
		if ((x & S) != S) continue;
		if ((x & T) != x) continue;
		a.push_back(x ^ S);
	}
	T ^= S;
	//printf("T = %d\n", T);
	n = (int)a.size();
	ll ans = 0;
	for (int i = 0; i < n; i++) {
		vector<int> b;
		for (int j = 0; j < i; j++)
			b.push_back(a[j] ^ a[i]);
		ans += solve(b);
	}
	printf("%lld\n", ans);

	return 0;
}

