const int N = 18;
const int K = 55;

ll C[K][K];
ll sm[K];
ll masks[2][N];
int okay[K];
int x[K];

ll ans = 0;
int positions[N], cnt;

void go(int i, int sgn, ll possible){
	if(i == cnt){
		ans += sgn * sm[__builtin_popcountll(possible)];
		return;
	}
	go(i + 1, sgn, possible);
	go(i + 1, sgn * -1, possible & masks[0][positions[i]]);
	go(i + 1, sgn * -1, possible & masks[1][positions[i]]);
}

int main(){
	ll s = 0, t = (1LL << 50) - 1;
	int n = 50, k = 50; 
	sd(n); sd(k); 
	scanf("%lld %lld", &s, &t);
	for(int i = 0; i < n; i++){
		x[i] = (rand() * (ll) rand()) % (1LL << 50);
		cin >> x[i];
	}

	for(int i = 0; i < K; i++){
		C[i][0]= 1;
		for(int j = 1; j <= i; j++){
			C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
			if(j <= k) sm[i] += C[i][j];
		}
	}

	fill(okay, okay + n, 1);
	for(int i = 0; i < N; i++){
		int u = s >> i & 1, v = t >> i & 1;
		if(u && !v){
			printf("0\n");
			return 0;
		}
		if(!u && !v){
			for(int j = 0; j < n; j++) if(x[j] >> i & 1) okay[j] = 0;
			continue;
		}
		if(u && v){
			for(int j = 0; j < n; j++) if(!(x[j] >> i & 1)) okay[j] = 0;
			continue;
		}
		positions[cnt++] = i;
	}
	ll possible = 0;
	for(int i = 0; i < n; i++) if(okay[i]){
		possible |= 1LL << i;
		for(int j = 0; j < N; j++) masks[x[i] >> j & 1][j] |= 1LL << i;

	}

	go(0, 1, possible);
	printf("%lld\n", ans);
}

