const int N=55;
int a[N],w[N],n,m,K,S,T,aim;
ull C[N][N],ans;

int main(){
	read(n),read(K);
	read(S),read(T);
	rep(i,1,n){
		read(a[++m]);
		if((a[m]&S)!=S) m--;
		else if((a[m]|T)!=T) m--;
	}
	n=m,aim=(~S)&T;
	C[0][0]=1;
	rep(i,1,n){
		C[i][0]=1;
		rep(j,1,n){
			C[i][j]=C[i-1][j]+C[i-1][j-1];
		}
	}
	rep(l,1,n){
		rep(r,l+1,n){
			w[r]=(a[l]^a[r])&aim;
		}
		for(int s=aim;;s=(s-1)&aim){
			int tot=0;
			rep(r,l+1,n){
				tot+=((w[r]|s)==s);
			}
			ull sum=0;
			rep(i,0,K-1){
				sum+=C[tot][i];
			}
			if(__builtin_popcount(aim^s)%2==0){
				ans+=sum;
			}
			else{
