ll dp[MAXV][N];

void solve(){
	ll n,k,s,t;
	cin >> n >> k >> s >> t;
	if((s&t) != s){
		cout << 0 << ln;
		return;
	}
	vector<pair<p64,ll> > vec1,vec2;
	vec1.pb(mp(mp(s,t),0)); 
	vec2.pb(mp(mp(s,t),0));
	ll c = 0;
	forn(i,n) {
		ll tempvar;
		cin >> tempvar;
		if((tempvar&s) == s && (tempvar|t) == t){
			if(c<lim){
				vector<pair<p64,ll> > temp;
				for(auto it : vec1){
					temp.pb(mp(mp((tempvar|it.fi.fi),(tempvar&it.fi.se)),it.se+1));
				}
				for(auto it : temp) vec1.pb(it);
			}
			else{
				vector<pair<p64,ll> > temp;
				for(auto it : vec2){
					temp.pb(mp(mp((tempvar|it.fi.fi),(tempvar&it.fi.se)),it.se+1));
				}
				for(auto it : temp) vec2.pb(it);
			}
			c++;
		}
		// for(auto j : vec1){
		// 	cout << j.fi << " " << j.se << ln;
		// }
		// cout << ln;
	}
	ll ans = 0;
	// cout << sz(vec1) << ln;
	for(auto it : vec1){
		if(it.se == 0 || it.se>k) continue;
		if(it.fi == mp(t,s) && it.se<=k) ans++;
		ll curval = (it.fi.se | (it.fi.fi ^ t));
		// cout << curval << ln;
		dp[curval][it.se-1]++;
	}
	forn(j,n) forn(i,18) forn(mask,MAXV) if(mask & (1<<i)) dp[mask][j] += dp[mask^(1<<i)][j];
	forn(j,n-1) forn(mask,MAXV) dp[mask][j+1]+=dp[mask][j];
	// forn(mask, MAXV){
	// 	forn(j,18){
	// 		if(mask & (1<<j)) dp[mask][j] = (j ? dp[mask][j-1] : a[mask]) + (j ? dp[mask ^ (1<<j)][j-1] : 0);
	// 		else dp[mask][j] = (j ? dp[mask][j-1] : a[mask]);
	// 	}
	// }
	for(auto it : vec2){
		if(it.se == 0 || it.se >k) continue;
		if(it.fi == mp(t,s) && it.se<=k) ans++;
		if(it.se == k) continue;
		// cout << it.fi << " " << it.se << ln;
		ll val1 = (it.fi.fi ^ s);
		ll val2 = (s | (it.fi.se ^ t));
		// cout << val1 << " " << val2 << ln;
		ans += dp[val1|val2][k-it.se-1];
	}
	cout << ans << ln;
}

