int64_t calc() {
    if ((S | T) != T)
        return 0;

    int m = 0;
    for (int i = 0; i < n; i++)
        if ((a[i] & S) == S && (a[i] | T) == T)
            b[m++] = a[i];

    int64_t total = 0;
    for (int i = 0; i < m; i++) {
        for (int num = 0; num < k; num++)
            cnt[num].clear();
        cnt[0][0] = 1;
        for (int j = i + 1; j < m; j++) {
            int mask = b[j] ^ b[i];
            for (int num = min(k - 1, j - i); num > 0; num--)
                for (auto kv : cnt[num - 1])
                    cnt[num][kv.first | mask] += kv.second;
        }
        for (int num = 0; num < k; num++)
            total += cnt[num][T ^ S];
    }
    return total;
}

