main() {
    INT(n, k, s, t);
    if((s & t) != s) {
        cout << 0 << endl;
        return 0;
    }
    VEC(int, a, n);
    int C = 0;
    rep(i, 18) {
        n = a.size();
        vi nxt;
        int keta = i - C;
        if(s & (1 << i) and t & (1 << i)) {
            C++;
            rep(j, n) {
                if(~a[j] & (1 << keta)) continue;
                nxt.eb((a[j] % (1 << keta)) + (a[j] >> (keta + 1)));
            }
            a = nxt;
        } else if(~s & (1 << i) and ~t & (1 << i)) {
            C++;
            rep(j, n) {
                if(a[j] & (1 << keta)) continue;
                nxt.eb((a[j] % (1 << keta)) + (a[j] >> (keta + 1)));
            }
            a = nxt;
        }
    }
    ll ans = 0;
    cmb[0][0] = 1;
    rep2(i, 1, 99) {
        cmb[i][0] = 1;
        rep2(j, 1, i) cmb[i][j] = cmb[i - 1][j] + cmb[i - 1][j - 1];
    }
    rep2(i, 1, 99) { rep(j, i) cmb[i][j + 1] += cmb[i][j]; }
    rep(mask, 1 << (18 - C)) {
        int id = popcount(mask) & 1;
        rep(i, n) {
            dp[a[i] & mask]++;
            int t = dp[a[i] & mask];
            // (t-1,min(t-1,k)) -> (t,min(t,k))
            if(id)
                ans += cmb[t][min(t, k)] - cmb[t - 1][min(t - 1, k)];
            else
                ans -= cmb[t][min(t, k)] - cmb[t - 1][min(t - 1, k)];
        }
        rep(i, n) dp[a[i] & mask] = 0;
    }
    cout << abs(ans) << endl;
}

