								if (x >> i & 1) 
										t.insert(x);
						s.clear();
						for (int x : t)
								s.insert(x);
				}
				if (!(S >> i & 1) && !(T >> i & 1)) {
						t.clear();
						for (int x : s) 
								if (!(x >> i & 1))
										t.insert(x);
						s.clear();
						for (int x : t)
								s.insert(x);
