				for (int j = 1; j <= N; ++j)
						f[i][j] = f[i - 1][j] + f[i - 1][j - 1];
		}
		for (int i = 1; i <= N; ++i)
		for (int j = 0; j <= N; ++j)
				g[i][j] = j ? g[i][j - 1] + f[i][j] : 1;
		LL ans = 0;
		for (int now = msk; ; now = (now - 1) & msk) {
				for (int i = 1; i <= M; ++i) 
						c[i] = b[i] & now;
				sort(c + 1 , c + 1 + M); LL cur = 0;
				for (int i = 1 , j = 1; i <= M; i = j) {
						while (j <= M && c[i] == c[j]) ++j;
						cur += g[j - i][K];
				}
				if (__builtin_popcount(now) & 1) ans -= cur;
				else ans += cur;
				if (now == 0) break;
		}
