   cin.tie(0);

   int n, K, S, T;
   cin >> n >> K >> S >> T;
   vector<int> a(n);
   for(int i = 0; i < n; i++) {
      cin >> a[i];
   }
   { 
      if((S & T) != S) {
         cout << "0\n";
         exit(0);
      }
      vector<int> new_a;
      for(int x : a) {
         if((x & S) == S && (x | T) == T) {
            new_a.push_back(x);
         }
      }
      a.swap(new_a);
      n = a.size();
      min_self(K, n);
   }
   vector<vector<long long>> binomial(n+1, vector<long long>(n+1));
   for(int i = 0; i <= n; i++) {
      binomial[i][0] = binomial[i][i] = 1;
      for(int j = 1; j < i; j++) {
         binomial[i][j] = binomial[i-1][j-1] + binomial[i-1][j];
      }
   }
   vector<long long> up_to_K(n+1);
   for(int i = 1; i <= n; i++) {
      for(int j = 1; j <= K; j++) {
         up_to_K[i] += binomial[i][j];
      }
   }
   const int B = 18;
   vector<int> freq(1 << B);
   long long ans = 0;
   int new_mask = S ^ T;
