      for(int x : a) {
         ++freq[x & mask];
      }
      long long ways = 0;
      for(int x : a) {
         ways += up_to_K[freq[x & mask]];
         freq[x & mask] = 0;
      }
      if(__builtin_popcount(mask) & 1) {
         ans -= ways;
      } 
      else {
         ans += ways;
      }
      if(mask == 0) {
         break;
      }
   }

   cout << ans << "\n";
}















