LL R(){
    LL ans=0,f=1;char c=getchar();
    for(;c<'0'||c>'9';c=getchar()) if (c=='-') f=-1;
    for(;c>='0'&&c<='9';c=getchar()) ans=ans*10+c-'0';
    return ans*f;
}
int nn,n,K,S,T;
LL a[N];
int q[N];
int cnt[N];
LL C[55][55];
void FWT(){
	for(int mid=1;mid<N;mid<<=1)
		for(int l=0;l<N;l+=mid+mid)
			for(int k=l;k<l+mid;++k)
				a[k+mid]+=a[k];
}
LL Sol(int st){
	memset(a,0,sizeof(a));
	F(i,st+1,n)
		a[q[i]^q[st]]++;
	FWT();
	LL an=0;
	int uT=T-(T&S);
	for(int i=uT;i;i=uT&(i-1)){
		int fg=((cnt[uT]-cnt[i])&1)?-1:1;
		an+=fg*C[a[i]][K-1];
	}
	int i=0;
	int fg=((cnt[uT]-cnt[i])&1)?-1:1;
	an+=fg*C[a[i]][K-1];
	return an;
}
