	F(i,1,M-1)F(j,1,i)C[i][j]=C[i-1][j-1]+C[i-1][j];
	F(i,0,M-1)F(j,1,M-1)C[i][j]+=C[i][j-1];

	nn=R();K=R();S=R();T=R();
	F(i,1,nn){
		int x=R();
		if((x&S)!=S)continue;
		if((x&T)!=x)continue;
		q[++n]=x;
	}
