int n,k,s,t,m,a[N];
ll C[N][N];

void No() {
	cout<<0;exit(0);
}

int main() {
	cin>>n>>k>>s>>t;
	if((s&t)!=s) No();
	for(int i=0;i<N;i++) {
		C[i][0]=1;
		for(int j=1;j<=i;j++) C[i][j]=C[i-1][j-1]+C[i-1][j];
	}
	for(int i=0;i<N;i++) {
		C[i][0]=0;
		for(int j=1;j<=i;j++) C[i][j]+=C[i][j-1];
	}
	for(int i=1;i<=n;i++) {
		cin>>a[i];
		if((a[i]&s)!=s||(a[i]&t)!=a[i]) --i,--n;
	}
	int key=0;
	for(int i=0;i<18;i++)
		if((s>>i&1)!=(t>>i&1)) key|=1<<i;
	m=__builtin_popcount(key);
	for(int i=1;i<=n;i++) {
		int now=0,val=0;
		for(int j=0;j<18;j++)
			if(key>>j&1) {
				if(a[i]>>j&1) val|=1<<now;
				++now;
			}
		a[i]=val;
		//cerr<<a[i]<<'\n';
	}
	ll ans=0;
	for(int i=0;i<(1<<m);i++) {
		int sgn=__builtin_parity(i)?-1:1;
		unordered_map<int,int> cnt;
		for(int j=1;j<=n;j++) ++cnt[a[j]&i];
		for(auto t:cnt) ans+=C[t.se][min(t.se,k)]*sgn;
	}
	cout<<ans;
	return 0;
}

