    return true;
}


ll make(int x, ll mask) {
    for (int j=0; j<18; j++) {
	if (x>>j&1) {
	    mask |= (1ll<<j);
	} else {
	    mask |= (1ll<<(18+j));
	}
    }

    return mask;
}


