			if (t == 0 && u == 1) {if (c[j] > 0&&hou>=0) { hou++; }}
			if (t == 0 && u == 0) { if (c[j] != 2) { hou = -1; } }
			if (t == 1 && u == 1) { if (c[j] != 1) { hou = -1; } }
			if (t == 1 && u == 0) { cout << 0 << endl; return 0; }
		}

		if (hou == -1) { continue; }
		hou %= 2;

		ll pop = 0;
		rep(j, N) {
			if ((y.second >> j) & 1) { pop++; }
		}

		ll cnt = 0;
		repn(j, min(K, pop)) {
			cnt += com[pop][j];
		}

		//cout << hou << " " << cnt << endl << endl;

		if (hou % 2 == 0) { ans += cnt; }
		else { ans -= cnt; }
	}

	cout << ans << endl;
}

