const int MAX_N = 53, L = 18;
bool isSubmask(int submsk, int msk)
{
    return (msk&submsk) == submsk;
}
ll C[MAX_N][MAX_N];
void genComb()
{
    C[0][0] = 1;
    for (int r = 1; r < MAX_N; ++r)
    {
        C[r][0] = 1;
        C[r][r] = 1;
        for (int j = 1; j < r; ++j)
        {
            C[r][j] = C[r-1][j] + C[r-1][j-1];
        }
    }

    for (int r = 0; r < MAX_N; ++r)
    {
        C[r][0] = 0;
        for (int j = 1; j < MAX_N; ++j)
            C[r][j] += C[r][j - 1];
    }
}

ll F[(1<<L) + 1];

int countZeros(int msk)
{
    return 31 - __builtin_popcount(msk);
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
#ifdef LOCAL
    freopen("input.txt", "r", stdin);
//    freopen("AC.txt", "w", stdout);
#endif
    genComb();
    int n, k, A, O;
    cin >> n >> k >> A >> O;
    vector<int> a(n);
    rep(i,0,n)
        cin >> a[i];
    if (!isSubmask(A, O))
    {
        cout << 0 << '\n';
        return 0;
    }
    vector<int> v;
    rep(i,0,n)
    {
        if (isSubmask(a[i], O) && isSubmask(A, a[i]))
            v.push_back(a[i]);
    }

    n = sz(v);
    int M = A^O;
    if (!M)
    {
        cout << C[n][k] << '\n';
        return 0;
    }


    ll ans = 0;
    for (int first = 0; first < n; ++first)
    {
        vector<int> vTemp(all(v));
        clr(F, 0);
        for (int i = first + 1; i < n; ++i)
        {
            vTemp[i] = v[i] ^ v[first];
            F[vTemp[i]]++;
        }
        for (int i = 0; i < L; ++i)
            for (int msk = 0; msk < (1<<L); ++msk)
                if (msk & (1<<i))
                    F[msk] += F[msk^(1<<i)];

        ans += C[n - first - 1][k - 1];
        for (int msk = 0; msk < (1<<L); ++msk)
        {
            if (!isSubmask(msk, M) || msk == M)
                continue;
            ll temp = C[F[msk]][k - 1];
            int z = countZeros(msk) - countZeros(M);
            if (z&1)
                ans -= temp;
            else
                ans += temp;
        }
    }


    cout << ans << '\n';
}

