long long getC(int n,int m){
	if(m>n || m<0) return 0;
	else return c[n][m];
}

void preWork(int n){
	c[0][0] = 1;
	for(int i = 1; i <= n; i++){
		c[i][0] = 1;
		for(int j = 1; j <= i; j++){
			c[i][j] = c[i-1][j]+c[i-1][j-1];
		}
	}
	for(int i = 0; i < (1<<18); i++){
		sign[i] = 1;
		int mask = i;
		for(int j = 0; j < 18; j++){
			if(mask%2) sign[i] *= -1;
			mask /= 2;
		}
	}
	for(int i = 0; i <= n; i++){
		sum[i][0] = 0;
		for(int j = 1; j <= n; j++){
			sum[i][j] = sum[i][j-1]+getC(i,j);
		}
	}
}

int translate(int n){
	int count = 0;
	for(int i = 1; i <= n; i++){
		int u = a[i], size = -1;
		int ok = 1;
		for(int j = 0; j < 18; j++){
			if(andBit[j]){
				if(u%2==0){ 
					ok = 0; 
					break;
				}
			}
			else if(orBit[j]==0){
				if(u%2!=0){
					ok = 0;
					break;
				}
			}
			else curBit[++size] = u%2;
			u /= 2;
		}
		if(ok){
			int add = 0;
			for(int j = size; j >= 0; j--) add = add*2+curBit[j];
			b[++count] = add;
		}
	}
	return count;
}

void calCount(int n,int bitCnt){
	for(int i = 0; i < (1<<bitCnt); i++){
		count0[i] = count1[i] = 0;
		for(int j = 1; j <= n; j++){
			count0[i] *= 2, count1[i] *= 2;
			if((b[j]&i)==0) count0[i]++;
			if((b[j]&i)==i) count1[i]++;
		}
	}
}

int popCount(long long u){
	return __builtin_popcountll(u);
}

