int A[60];
ll dp[60][60], sum[60][60];

int main() {
	int N, K, S, T;
	cin >> N >> K >> S >> T;
	for(int i=0; i<N; ++i) cin >> A[i];
	vector<int> g;
	for(int d=0; d<18; ++d){
		if((S&(1<<d)) && !(T&(1<<d))){
			cout << 0 << endl;
			return 0;
		}
		if(!(S&(1<<d)) && (T&(1<<d))){
			g.emplace_back(d);
		}
	}
	vector<int> v;
	for(int i=0; i<N; ++i){
		if(((A[i])&S)==S && ((A[i])|T)==T) v.emplace_back(A[i]);
	}
	dp[0][0]=sum[0][0]=1;
	for(int i=1; i<=v.size(); ++i){
		dp[i][0]=dp[i][i]=sum[i][0]=1;
		for(int j=1; j<i; ++j){
			dp[i][j]=dp[i-1][j-1]+dp[i-1][j];
			sum[i][j]=sum[i][j-1]+dp[i][j];
		}
		sum[i][i]=sum[i][i-1]+1;
	}
	int vs=v.size();
	ll ans=sum[vs][min(vs, K)];
	for(int h=1; h<(1<<(g.size())); ++h){
		vector<int> w;
		for(int d=0; d<g.size(); ++d){
			if(h&(1<<d)) w.emplace_back(d);
		}
		map<int, int> mp;
		for(int i=0; i<v.size(); ++i){
			ll now=0;
			for(int d=0; d<w.size(); ++d){
				now += (v[i])&(1<<(g[w[d]]));
			}
			++mp[now];
		}
		ll sp=0;
		for(auto itr=mp.begin(); itr!=mp.end(); ++itr){
			sp += sum[itr->second][min(itr->second, K)];
		}
		if((w.size())&1) ans -= sp;
		else ans += sp;
	}
	cout << ans << endl;
	return 0;
}

