int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n, k, s, t;
    std::cin >> n >> k >> s >> t;
    std::vector<std::vector<long long>> C(n + 1, std::vector<long long>(n + 1));
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
    }
    for (int i = 0; i <= n; ++i)
        for (int j = 2; j <= n; ++j)
            C[i][j] += C[i][j - 1];
    std::vector<int> a;
    for (int i = 0; i < n; ++i) {
        int x;
        std::cin >> x;
        if ((x & s) == s && (x | t) == t)
            a.push_back(x);
    }
    n = a.size();
    long long ans = 0;
    int c[1 << 18] = {};
    for (int v = 0; v < (1 << 18); ++v) {
        if ((v & s) != s || (v | t) != t)
            continue;
        long long res = 0;
        for (int i = 0; i < n; ++i)
            ++c[a[i] & v];
        for (int i = 0; i < n; ++i) {
            if (c[a[i] & v]) {
                res += C[c[a[i] & v]][k];
                c[a[i] & v] = 0;
            }
        }
        ans += (__builtin_parity(v ^ s) ? -1 : 1) * res;
    }
