char *getbits(_LL a)
{
        char *ans = new char[18];
        for( _LL bit = 0; bit < 18; bit++ )
        {
            ans[bit] = (a & ( (_LL)1 << bit )) ? 1 : 0;
        }    
        return  ans;
}

_LL countpattern(vector<char*> groups, int n, int *list, int depth, int num, int k)
{
    if( k < 0 ) return 0;
    if( groups.size() == 0 )
    {
        _LL tmp = 1;
        _LL ans = 1;

        for( int i = 0; i < k; i++ )
        {
            tmp *= (num - depth - i);
            ans += tmp;
        }
        return ans;    
    }


    int count[50];
    for( int i = 0; i < n; i++ ) count[i] = 0;

    for( int g = 0; g < groups.size(); g++)
    {
        for( int i = 0; i < n; i++ ) count[i] += groups[g][i];
    }

    int nexti = 0;
    int maxc = 0;

    for( int i = 0; i < n; i++ ) 
    {
        if( count[i] > maxc ) 
        {
            maxc = count[i];
            nexti = i; 
        } 
    }

    // nexti選択時
    _LL ans;
    {
        vector<char*> nextgroups;
        for( int g = 0; g < groups.size(); g++)
        {
            if( groups[g][nexti] == 0) nextgroups.push_back(groups[g]);
        }
        list[depth] = nexti;
        ans = countpattern(nextgroups, n, list, depth + 1, num, k - 1);
    }

    // nexti未使用
    {
        vector<int> remove;
        bool flag = true;
        for( int g = 0; g < groups.size(); g++)
        {
            if( groups[g][nexti] ) 
            {
                int count2 = 0;
                for( int i = 0; i < n; i++ ) count2 += groups[g][i] ;
                if( count2 == 1 )
                {
                    flag = false;
                    break;
                }
                groups[g][nexti] = 0;
                remove.push_back(g);
            }
        }
        if( flag )
        {
            list[depth] = nexti;
            ans += countpattern(groups, n, list, depth + 1, num, k);
        }
        for( int gi = 0; gi < remove.size(); gi++ ) groups[remove[gi]][nexti] = 1;
    }
    return ans;
}


