		for (int j = 1; j <= 52; j++)rcom[i][j] = rcom[i][j - 1] + com[i][j];
	}
	ll ans = 0;
	for (int p = 0; p < (1 << len); p++)
	{
		for (int i = 0; i < num; i++)zzz[i] = (p&v[i]);
		sort(zzz, zzz+num);
		zzz[num] = -1;
		ll t = 0;
		int c = 0, now = -1;
		for (int i = 0; i <= num; i++)
		{
			if (now != zzz[i])
			{
				t += rcom[c][min(c, gen)];
				now = zzz[i], c = 1;
			}
			else c++;
		}
		bool f = false;
		for (int i = 0; i < len; i++)if (p&(1 << i))f ^= 1;
		if (!f)ans += t;
		else ans -= t;
		//printf("  %d %lld\n", p, t);
	}
	printf("%lld\n", ans);
}

