inline long long dfs(re int p,re int x,re int y,re int cnt){
	re long long hsh=1ll*(1ll<<20)*x+y;
	if(v[p][cnt].find(hsh)!=v[p][cnt].end())return v[p][cnt][hsh];
	if(p==0){
		if(x==s&&y==t)return 1;
		return 0;
	}
	if((y|b[p])&t!=(y|b[p]))return 0;
	if((x&s)!=s)return 0;
	re long long ans=0;
	ans+=dfs(p-1,x,y,cnt);
	if(cnt^k)ans+=dfs(p-1,x&a[p],y|a[p],cnt+1);
	return v[p][cnt][hsh]=ans;
}
