    //いや、分割してくだけか
    //チェックするのは結局N個くらいで済む→O(N×2^L)

    //以下、集合はbitで表現

    //まずは、それぞれのbitで集合を分割
    //全て異なるのでsetで良い
    vector<pair<ll,ll>> bits;
    REP(i,18){
        //未定義にするな
        ll f1=0;ll f2=0;
        REP(j,n){
            if((a[j]>>i)&1){
                f1+=(1<<j);
            }else{
                f2+=(1<<j);
            }
        }
        if(f1 and f2)bits.PB(MP(f1,f2));
        else{cout<<0<endl;return 0;}
    }
    ll bits_len=SIZE(bits);//cout << bits_len << endl;
    #if 0
    REP(i,bits_len){
        for(auto j=bits[i].F.begin();j!=bits[i].F.end();j++){
