using namespace std;

constexpr static int MAXN = 50;
constexpr static int MAXA = (1 << 18);

int n, k, S, T;
int a[MAXN], b[MAXN];
int64_t cnt[MAXN][MAXA];

int64_t calc() {
    if ((S | T) != T)
        return 0;

    int m = 0;
    for (int i = 0; i < n; i++)
        if ((a[i] & S) == S && (a[i] | T) == T)
            b[m++] = a[i];

    int64_t total = 0;
    for (int i = 0; i < m; i++) {
        // DP too slow... this is O(n^3 * |MAXA|)
        for (int num = 0; num < k; num++)
            for (int l = 0; l < MAXA; l++)
                cnt[num][l] = 0;
        cnt[0][0] = 1;
        for (int j = i + 1; j < m; j++) {
            int mask = b[j] ^ b[i];
            // cout << "  mask: " << mask << endl;
            for (int num = min(k - 1, j - i); num > 0; num--) {
                for (int l = 0; l < MAXA; l++)
                    if (cnt[num - 1][l] > 0)
                        cnt[num][l | mask] += cnt[num - 1][l];
            }
        }
        for (int num = 0; num < k; num++) {
            // cout << i << " | " << num << ": " << cnt[num][T ^ S] << endl;
            total += cnt[num][T ^ S];
        }
    }
    return total;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n >> k >> S >> T;
    for (int i = 0; i < n; i++)
        cin >> a[i];

    cout << calc() << endl;
}

