		a.resize(n+1);
		for (int i = 0; i <= n; i++) {
			a[i].resize(i+1, 1);
			for (int j = 1; j < i; j++) a[i][j] = a[i-1][j] + a[i-1][j];
		}
	}
	s64 ncr(int n, int r) {
		assert(n >= 0);
		assert(n <= (int)a.size());
		assert(r >= 0);
		assert(r <= n);
		return a[n][r];
	}
};

