#include <bits/stdc++.h>
#pragma GCC target ("avx2")
#pragma GCC optimization ("O3")
#pragma GCC optimization ("unroll-loops")
using namespace std;

const int N = 55, MX = 1 << 18, LG = 18;

int n, k, s, t, a[N], sos[MX];
long long ans = 0, c[N][N];

void init() {
    for (int i = 0; i < N; i++) {
        c[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
        }
    }
    for (int i = 0; i < N; i++) {
        for (int j = 1; j <= n; j++) {
            c[i][j] += c[i][j - 1];
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k >> s >> t;
    init();
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    if ((s & t) != s) {
        return cout << 0, 0;
    }
    for (int fi = 0; fi < MX; fi++) {
        if (((fi & s) == s) && (fi & t) == fi) {
            long long cur = 0;
            int oth = fi ^ t;
            bool chk = false;
            for (int i = 1; i <= n; i++) {
                if ((a[i] & fi) == fi && (a[i] & t) == a[i]) {
                    sos[a[i] ^ fi] = 1;
                    chk = true;
                }
            }
            if (!chk) {
                continue;
            }
            for (int i = 0; i < LG; i++) {
                if (oth >> i & 1) {
                    for (int se = oth; se > 0; se = (se - 1) & oth) {
                        if (se >> i & 1) {
                            sos[se] += sos[se ^ (1 << i)];
                        }
                    }
                }
            }
            for (int se = oth; se > 0; se = (se - 1) & oth) {
                cur += ((__builtin_popcount(oth ^ se) & 1) ? -1 : 1) * (c[sos[se]][k] - 1);
                sos[se] = 0;
            }
            cur += ((__builtin_popcount(oth) & 1) ? -1 : 1) * (c[sos[0]][k] - 1);
            sos[0] = 0;
            ans += ((__builtin_popcount(fi ^ s) & 1) ? -1 : 1) * cur;
        }
    }
    cout << ans;
}

