int main(){

  // 普通にnCkを計算するとオーバーフローするので、パスカルの三角形を利用
  ll n_limit = 50; //!! nの最大値を設定 !!
  vector<ll> CmbsVec( ( 2 + n_limit ) * ( 1 + n_limit ) / 2 );
  //nCkへのアクセスは .at( ( n + 1 ) * n / 2 + k )
  //n-1まで（1段上）の要素の総数が ( n + 1 ) * n / 2 なので、その次の段のk+1個目を0-indexed (つまり-1)に直すと、この式に

  //nC0, nCnは全て1に
  rep(i, n_limit+1){  //n : 0〜n_limitについて
    CmbsVec.at( ( i + 1 ) * i / 2 + 0 ) = 1;  //nC0
    CmbsVec.at( ( i + 1 ) * i / 2 + i ) = 1; //nCn
  }

  //n C 1〜n-1を前計算 nは2からスタート
  REP(n, 2, n_limit + 1){ //nは2〜n_limitまで全て
    REP(k, 1, n){ //kは1〜n-1
      // nCk = n-1Ck-1 + n-1Ck を利用している
      // n+1Ck = nCk + n-1Ck-1 と考えてもいい
      CmbsVec.at( ( n + 1 ) * n / 2 + k ) = CmbsVec.at( n * ( n - 1) / 2 + k - 1 ) + CmbsVec.at( n * ( n - 1 ) / 2 + k );
    }
  }

  // nCkを返すlambda式 Comb(n, k)で使う
  auto comb = [&] (ll n, ll k) -> ll {
    if (n==0 && k==0) return 1;
    else if (n < k) return 0;
    return CmbsVec.at( ( n + 1 ) * n / 2 + k );
  };


  // ここから本題

  ll max_digit = 18;

  ll N, K, S, T;
  cin >> N >> K >> S >> T;

  vector<ll> As(N);
  rep(i, N){
    As[i] = il();
  }

  // S=Tのコーナーケースを処理
  if (S==T){
    // S=T=Ai となるようなAiがあれば答えは1, なければ0
    if (find(As.begin(), As.end(), S) != As.end()){
      cout << 1 << endl;
      return 0;
    }
    else{
      cout << 0 << endl;
      return 0;
    }
  }

  // 各Ai のうち、使えないやつを弾き出す

  rep(d, max_digit){
    // 0桁目から17桁目まで、右端から18bit分見ていく
    vector<ll> tmp_as;
    if ((S & (1<<d)) && !(T & (1<<d))){
      // これがあったら、そもそも無理
      cout << 0 << endl;
      return 0;
    }
    else if (!(S & (1<<d)) && !(T & (1<<d))){
      // i桁目が1であるようなAiを弾いて、それ以外を使う
      rep(i, As.size()){
        if (!(As[i] & (1<<d))) tmp_as.push_back(As[i]);
      }
    }
    else if ((S & (1<<d)) && (T & (1<<d))){
      // i桁目が0であるようなAiを弾いて、それ以外を使う
      rep(i, As.size()){
        if ((As[i] & (1<<d))) tmp_as.push_back(As[i]);
      }
    }
    else{
      // bss[d] == 1 && bst[d] == 0 ならはじき出さない
      // つまり、Asは変化させない
      continue;
    }
    // Asを更新（はじき出されたものが減る）
    As = tmp_as;
  }

  /* 
    ここまでで、As の整理とコーナーケース（答え:0のパターン）の処理が終わった
    具体的には、
    S,T=1,0 のbitは存在しない（もし1つでも存在すれば答えは0で終了済）
    S,T=0,0 となっている桁のbitは、0 のもの以外残っていない
    S,T=1,1 となっている桁のbitは、1 のもの以外残っていない
  */

  // 上記より、S,T=0,1以外の桁は無視していいことになったので、削除してしまう
  // 上の桁から見ていく
  for (ll d = max_digit-1; d >= 0; --d){
    if ( !( !(S&(1<<d)) && (T&(1<<d)) ) ){
      // ST=01でなければ、その桁を削除
      max_digit--;
      rep(i, As.size()) As[i] = As[i]/(1<<(d+1))*(1<<(d)) + As[i]%(1<<d);
      S = S/(1<<(d+1))*(1<<(d)) + S%(1<<d);
      T = T/(1<<(d+1))*(1<<(d)) + T%(1<<d);
    }
  }

  // あとは、各mask毎にAiをグループ分けする
  // グループ分けとは？
  // --> 各maskのbitが立っている桁（包除原理による場合の数の計算において、Bを「どんな組合せでもいい」、Aを「全部0 もしくは 全部1 となる組合せ」とした場合の、Aとしたい桁）については、同じbitの立ち方をしているAiを組合せないと、Aパターンにならない（Aにしたいある桁について、0と1が混在してしまう）ため、同じbitの立ち方をしているAiの数を数える
  // ＜数え方＞ Vector<map<ll, ll> Eg[mask] := map<key:bitの立ち方, value:その立ち方をしているAiの数>

  ll two_tpo = llpow(2, max_digit); // 2^(残り桁数)

  // Eg[mask:0~2^残り桁数-1] := map<key:Ai&mask, value:数>
  vector<map<ll, ll> > Eg(two_tpo, map<ll, ll>());

  // Eg（maskごとに、各グループに属するAiが何個ずつあるか）の計算
  rep(mask, two_tpo){
    for (ll a : As){
      Eg[mask][a & mask]++;
    }
  }

  // 答えを求める
  ll ans = 0;

  // f[m] = Σ(k:1~K)mCk を m:0~N について前計算
  vector<ll> f(N+1, 0);
  REP(k, 1, K+1){
    rep(m, N+1){
      f[m] += comb(m, k); // mCk
    }
  }


  rep(mask, two_tpo){
    ll popcount = __builtin_popcountll(mask); // mask の立っているbit数
    for (pair<ll, ll> each_keyandvalue : Eg[mask]){
      ll value = each_keyandvalue.second; // mask グループに属するAiの数

      // 包除原理により、popcount奇数の場合は-、popcount偶数の場合は+
      if (popcount%2 == 1){
        ans -= f[value];
      } 
      else{
        ans += f[value];
      }
    }
  }

  cout << ans << endl;

}

