using namespace std;
int n, k, s, t, a[55];
long long C[55][55], ps[55][55];
int main() {
	scanf("%d%d%d%d", &n, &k, &s, &t);
	if ((s & t) != s || (s | t) != t) {
		puts("0");
		return 0;
	}
	for (int i = 1; i <= n; i++) {
		scanf("%d", &a[i]);
		if ((a[i] & s) != s || (a[i] | t) != t) {
			i--;
			n--;
		}
	}
	k = min(k, n);
	for (int i = C[0][0] = 1; i <= n; i++) {
		for (int j = C[i][0] = 1; j <= i; j++)
			C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
		ps[i][1] = C[i][1];
		for (int j = 2; j <= i; j++) {
			ps[i][j] = ps[i][j - 1] + C[i][j];
		}
	}
	int fa = s ^ t;
	long long ans = 0;
	for (int mask = fa; ; mask = (mask - 1) & fa) {
		map<int, int> mp;
		for (int i = 1; i <= n; i++) {
			mp[a[i] & mask]++;
		}
		long long cur = 0;
		for (auto &it : mp) {
			cur += ps[it.second][min(k, it.second)];
		}
		if (__builtin_popcount(mask) & 1) ans -= cur;
		else ans += cur;
		if (!mask) break;
	}
	printf("%lld\n", ans);
	return 0;
}

