int main(){
  unsigned long long int N,K,S,T;
  cin>>N>>K>>S>>T;
  vector<unsigned long long int> vec(0);
  for(unsigned long long int i=0;i<N;i++){
    unsigned long long int a;
    cin>>a;
    unsigned long long int b=a|T;
    unsigned long long int c=a&S;
    if(b==T && c==S){//論理積がSと一致、論理和がTと一致するならvecに放り込む
      vec.push_back(a);
    }
  }
  unsigned long long int ans=0;
  unsigned long long int n=vec.size();
  for(unsigned long long int bit=1;bit<(unsigned long long int)(1<<n);bit++){//bit全探索
    unsigned long long int x,y;//xは論理積、yは論理和
    unsigned long long int count=0;//何個選ぶか
    queue<unsigned long long int> q;
    for(unsigned long long int i=0;i<n;++i){
      if(bit&(unsigned long long int)(1<<i)){
        q.push(i);
      }
    }
    if((unsigned long long int)q.size()>K){continue;}
    while(!q.empty()){
      if(count==0){//一個目はvecの値をそのまま
        x=vec.at(q.front());
        y=vec.at(q.front());
        count++;
      }else{//2個目以降があるなら、それぞれ論理積と論理和を取って更新   
        x=x&vec.at(q.front());
        y=y|vec.at(q.front());
      }
      q.pop();
    }
    if(x==S && y==T){ans++;}//それぞれS,Tと一致してかつ選んだのがK個以下ならans++をする
  }
  cout<<ans<<endl;
}

