struct solver
{
    int bit(int x,int k)
    {
        return (x>>k)&1;
    }

    solver()
    {
        int n,k,S,T; cin>>n>>k>>S>>T;
        vector<int> a(n);
        vector<int> ng(n);
        for(int i=0; i<n; ++i)
        {
            int x; cin>>x;
            a[i]=x;
            for(int j=0; j<18; ++j)
            {
                if(bit(x,j) and !bit(T,j))
                {
                    ng[i]=1;
                }
                if(!bit(x,j) and bit(S,j))
                {
                    ng[i]=1;
                }
            }
        }

        const int allb=(1<<18)-1;
        i64 ans=0;
        for(int i=0; i<n; ++i)
        {
            if(ng[i]) continue;
            vector<i64> f(1<<18);
            for(int s=0; s<=allb; s++)
            {
                int cnt=0;
                for(int j=0; j<i; j++)
                {
                    if((a[i]&s)==(a[j]&s))
                    {
                        cnt++;
                    }
                }
                i64 bino=1;
                for(int i=0; i<=cnt and i<k; i++)
                {
                    f[s]+=bino;
                    bino*=(cnt-i);
                    bino/=(i+1);
                }
            }
            for(int j=0; j<18; j++)
            {
                for(int s=0; s<=allb; s++)
                {
                    if(s>>j&1)
                    {
                        f[s^1<<j]-=f[s];
                    }
                }
            }
            int bset=0;
            for(int j=0; j<18; j++)
            {
                if(bit(S,j)==bit(T,j))
                {
                    bset|=1<<j;
                }
            }
            ans+=f[bset];
        }
        cout << ans << "\n";
    }
};
