constexpr static int MAXN = 50;
constexpr static int MAXA = (1 << 18);

int n, k, S, T;
int a[MAXN], b[MAXN];
int64_t choose[MAXN + 1][MAXN + 1];
int64_t nsubsets[MAXN + 1];

int64_t calc() {
    if ((S | T) != T)
        return 0;

    int m = 0;
    for (int i = 0; i < n; i++)
        if ((a[i] & S) == S && (a[i] | T) == T)
            b[m++] = a[i];

    // for each mask subset, count subsets that have same bits, use PIE
    int64_t total = 0;
    for (int mask = 0; mask < MAXA; mask++) {
        if ((mask | (S ^ T)) != (S ^ T))
            continue;
        map <int, int> cnt;
        for (int i = 0; i < m; i++)
            cnt[b[i] & mask]++;

        int64_t nsame = 0;
        for (auto kv : cnt) {
            // cout << kv.second << " ";
            nsame += nsubsets[kv.second];
        }
        // cout << endl;

        int bits = __builtin_popcount(mask);
        if (bits % 2 == 0)
            total += nsame;
        else
            total -= nsame;
    }
    return total;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n >> k >> S >> T;
    for (int i = 0; i < n; i++)
        cin >> a[i];

    choose[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        choose[i][0] = choose[i][i] = 1;
        for (int j = 1; j < i; j++)
            choose[i][j] = choose[i - 1][j] + choose[i - 1][j - 1];
    }
    for (int i = 1; i <= n; i++) {
        nsubsets[i] = 0;
        for (int j = 1; j <= k && j <= i; j++)
            nsubsets[i] += choose[i][j];
    }

    cout << calc() << endl;
}

