std::unordered_map<u64, u64> dp[51];

signed main() {
	INIT;

	VAR(int, n, k);
	VAR(u64, s, t);
	VEC(u64, a, n);

	{
		V<u64> b;
		for (auto& x : a) {
			if ((x & s) != s) continue;
			if ((~x & ~t) != ~t) continue;
			b.emplace_back(x);
		}
		a = b;
		n = a.size();
		std::sort(ALL(a));
	}

	const int L = 18;
	dp[0][((1ull << L) - 1) << L] = 1;

	REP(j, k + 1) dp[j].reserve(1 << L);
	REP(i, n) RREP(j, k + 1) {
		for (auto& p : dp[j]) {
			u64 bit = p.first;
			u64 sum = p.second;

			if (j + 1 <= k) {
				bit &= (a[i] << L) + (1ull << L) - 1;
				if (((bit >> L) & s) != s) continue;
				bit |= a[i];
				if ((~(bit & ((1ull << L) - 1)) & ~t) != ~t) continue;
				dp[j + 1][bit] += sum;
			}
		}
	}
	u64 ans = 0;
	const u64 bit = (s << L) + t;
	REP(j, k + 1) ans += dp[j][bit];
	OUT(ans)BR;

	return 0;
}

