#include <bits/stdc++.h>
using namespace std;

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	const int N = 55;
	vector<vector<long long>> C(N, vector<long long>(N, 0));
	for (int i = 0; i < N; i++) {
		for (int j = 0; j <= i; j++) {
			if (i == j || j == 0) C[i][j] = 1;
			else C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
		}
	}
	int n, k, S, T; cin >> n >> k >> S >> T;
	vector<int> a;
	for (int i = 0; i < n; i++) {
		int b; cin >> b;
		if ((b & S) != S) continue;
		if ((b | T) != T) continue;
		a.push_back(b);
	}
	n = a.size();
	vector<int> bts;
	for (int i = 0; i < 18; i++) {
		if ((~S >> i & 1) && (T >> i & 1)) {
			bts.push_back(i);
		}
	}
	int m = bts.size();
	vector<int> nums(m, 0);
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (a[i] >> bts[j] & 1) nums[j] |= 1 << i;
		}
	}
	long long ans = 0;
	for (int c = 1; c <= min(n, k); c++) {
		long long tot = C[n][c];
		vector<vector<int>> st(1 << m);
		st[0].push_back((1 << n) - 1);
		for (int i = 1; i < (1 << m); i++) {
			int bc = __builtin_popcount(i);
			for (int j = 0; j < m; j++) {
				if (i >> j & 1) {
					for (auto val : st[i ^ (1 << j)]) {
						if (val & nums[j]) st[i].push_back(val & nums[j]);
						if (val & (~nums[j])) st[i].push_back(val & (~nums[j]));
					}
					break;
				}
			}
			long long sgn = 1;
			if (bc & 1) sgn = -1;
			for (auto val : st[i]) {
				bc = __builtin_popcount(val);
				tot += sgn * C[bc][c];
			}
		}
		ans += tot;
	}
	cout << ans << endl;
	return 0;
}

