const int maxn = 1<<18, mod = 1e9 + 7;
ll C[60][60];
void precalc() {
	for(int i = 0; i < 55; i++)
		for(int j = 0; j <= i; j++) {
			if(!j) C[i][j] = 1;
			else C[i][j] = C[i-1][j] + C[i-1][j-1];
		}
}
int nck(int n, int k) {
	if(n < k || k < 0) return 0;
	return C[n][k];
}

int n, k, s, t;
ll ans = 0;
ll a[maxn], A[maxn];
void transform() {
	for(int j = 0; j < 18; j++)//relax i-th bit
		for(int i = 0; i < maxn; i++) {
			if(i&(1<<j)) a[i] += a[i ^ (1<<j)];
		}
	for(int i = 0; i < maxn; i++)
		for(int j = 0; j < k; j++)
			A[i] += nck(a[i], j);
	for(int j = 0; j < 18; j++)//fix i-th bit
		for(int i = 0; i < maxn; i++)
			if(i&(1<<j)) A[i] -= A[i ^ (1<<j)];
}

int main() {
	cin.tie(0)->sync_with_stdio(0);
	precalc();
	cin >> n >> k >> s >> t;
	if((s&t) != s) return cout << 0, 0;
	int M = s^t;
	vector<int> v;
	for(int x, i = 0; i < n; i++) {
		cin >> x;
		if((x&s) == s && (x&t) == x) v.pb(x&M);
	}
	n = v.size();
	for(int i = 0; i < n; i++) {
		memset(a, 0, sizeof a);
		memset(A, 0, sizeof A);
		for(int j = i+1; j < n; j++) {
			a[v[j]^v[i]]++;
		}
		transform();
		ans += A[M];
	}
	cout << ans;
	return 0;
}

