using pii = pair<int, int>;
map<pii, ll> dp[50][50];

int main(void){
	int n, k, s, t;
	cin >> n >> k >> s >> t;
	vector<int> a;

	rep(i, n) {
		int elem;
		cin >> elem;
		if((s & elem) != s) continue;
		if((t | elem) != t) continue;
		a.push_back(elem);
	}

	n = a.size();
	const int all = 1 << 18;

	dp[0][0][pii(all - 1, 0)] = 1LL;

	rep(i, n)rep(j, k + 1) {
		for(auto &elem: dp[i][j]) {
			const pii mask = elem.first;
			const ll val = elem.second;
			dp[i + 1][j][mask] += val;

			pii nmask = mask;
			nmask.first &= a[i];
			nmask.second |= a[i];
			dp[i + 1][j + 1][nmask] += val;
		}
	}

	ll ans = 0LL;
	rep(j, 1, k + 1) ans += dp[n][j][pii(s, t)];
	cout << ans << endl;

	return 0;
}

