ll dp[50][50][1 << 18];

int main(void){
	int n, k, s, t;
	cin >> n >> k >> s >> t;
	vector<int> a;

	rep(i, n) {
		int elem;
		cin >> elem;
		if((s & elem) != s) continue;
		if((t | elem) != t) continue;
		a.push_back(elem);
	}

	int fmask = 0;
	rep(i, 18) {
		const int sbit = (s >> i) & 1;
		const int tbit = (t >> i) & 1;
		if(sbit == 0 and tbit == 1) fmask |= (1 << i);
	}

	n = a.size();
	const int all = 1 << 18;

	ll ans = 0LL;
	rep(f, n) {
		rep(i, n + 1) rep(j, k + 1) rep(mask, all) {
			dp[i][j][mask] = 0LL;
		}
		dp[f + 1][1][0] = 1LL;
		rep(i, f + 1, n) rep(j, k + 1) rep(mask, all) {
			if(dp[i][j][mask] == 0) continue;
			dp[i + 1][j][mask] += dp[i][j][mask];
			const int nmask = mask | (a[f] ^ a[i]);
			dp[i + 1][j + 1][nmask] += dp[i][j][mask];
		}
		rep(j, 1, k + 1) ans += dp[n][j][fmask];
	}

	cout << ans << endl;

	return 0;
}

