ll C[55][55],ways[55];
ll cnt[maxn];
void solve()
{
	for(int i=0;i<m;i++)
	{
		for(int msk=0;msk<(1<<m);msk++)
		{
			if(!(msk>>i&1))
			{
				cnt[msk^(1<<i)]+=cnt[msk];
			}
		}
	}
}
int main()
{
	scanf("%d%d%d%d",&n,&k,&s,&t);
	for(int i=0;i<n;i++)
	{
		int x;
		scanf("%d",&x);
		if(((x&s)==s)&&((x|t)==t))a.push_back(x);
	}
	if(a.empty())
	{
		printf("0\n");
		return 0;
	}
	n=a.size();
	C[0][0]=1;
	for(int i=1;i<55;i++)
	{
		C[i][0]=C[i][i]=1;
		for(int j=1;j<i;j++)C[i][j]=C[i-1][j]+C[i-1][j-1];
	}
	for(int i=0;i<55;i++)
	{
		for(int j=0;j<=i&&j<k;j++)ways[i]+=C[i][j];
	//	if(i<=n)cout<<i<<" "<<ways[i]<<endl;
	}
	int free=(s^t);
	vector<int> bts;
	bts.clear();
	for(int i=0;i<18;i++)if(free>>i&1)bts.push_back(i);
	m=bts.size();
	for(int i=0;i<n;i++)
	{
		int tmp=a[i];
		a[i]=0;
		for(int j=0;j<m;j++)if(tmp>>bts[j]&1)a[i]|=(1<<j);
	//	cout<<a[i]<<endl;
	}
	ll ans=0;
	for(int i=0;i<n;i++)
	{
		memset(cnt,0,sizeof(cnt));
		for(int j=i+1;j<n;j++)
		{
			cnt[a[i]^a[j]]++;
		}
	//	for(int j=0;j<(1<<m);j++)cout<<cnt[j]<<endl;system("pause");
		solve();
		for(int j=0;j<(1<<m);j++)
		{
			int sz=__builtin_popcount(j);
			if(sz&1)ans-=ways[cnt[j]];
			else ans+=ways[cnt[j]];
		}
	}
	if(ans<0)ans=-ans;
	printf("%lld\n",ans);
	return 0;
}

