        std::unordered_map<Int, Int> mp;
        for (Int x : b) mp[x & S]++;
        Int cnt = 0;
        for (auto& p : mp) cnt += calc(p.second, K);
        ans += cnt * (__builtin_popcount(S) % 2 ? -1 : 1);
    }
