    t = read_bits(t, t);
    int x = t + 1;
    assert((x & (x - 1)) == 0);
    ll ans = 0;

    vector<vll> cnk(60, vector<ll>(60));
    for (int i = 0; i < 60; i++)
    {
        cnk[i][0] = cnk[i][i] = 1;
        for (int j = 1; j < i; j++) cnk[i][j] = cnk[i - 1][j] + cnk[i - 1][j - 1];
    }
    for (int u = 0; u < x; u++)
    {
        map<int, int> A;
        for (int i = 0; i < n; i++)
        {
            A[a[i] & u]++;
        }
        int s = popcount(u) % 2 ? -1 : 1;
        ll f = 0;
        for (auto x : A)
        {
            for (int j = 1; j <= min(k, x.second); j++)
                f += cnk[x.second][j];
        }
        ans = ans + s * f;
    }
    cout << ans;
}

