				mask += p3[u] * d;
			}
			if (ile.find(mask) == ile.end()) ile[mask] = 1;
			else ile[mask]++;

			dwojki[mask] = dw;
		}
		//debug() << imie(ile);
	}	
	//debug() << ile ;
	FOR(i,0,n+1) bin2[i] -= 1;
	lint ans = bin2[n];
	FORE(it, ile) {
		int mask = it->st;
		if (mask == p3[h] -1) continue;
		int u = h - dwojki[mask];
		if (u%2 == 1) {
			ans -= bin2[it->nd];
		} else {
			ans += bin2[it->nd];
		}
	}
	printf("%lld\n", ans);
}

