		vector<LL> b;
		RF(e, a) {
			bool f = true;
			inc(d, 18) {
				f &= ! (bit(t, d) == 0 && bit(e, d) == 1);
				f &= ! (bit(s, d) == 1 && bit(e, d) == 0);
			}
			if(f) { b.PB(e); }
		}
		a = b;
	}
	n = SI(a);
	setmin(k, n);
	s ^= t;

	vector<LL> f(n + 1);
	incII(i, 0, n) {
		LL v = 1;
		inc1(j, k) {
			if(j > i) { break; }
			v *= i - (j - 1);
			v /= j;
			f[i] += v;
		}
	}

	LL ans = f[n];
	incID(b, 1, 1LL << 18) {
		if((s & b) != b) { continue; }

		map<LL, LL> mp;
		RF(e, a) { mp[e & b]++; }
		RF(e, mp) { ans -= (PC(b) % 2 == 0 ? -1 : +1) * (f[e.SE]); }
	}

	OUT(ans);
}

