	nb = 0;
	REP(i, MAXBITS) {
		int x = (wantand >> i) & 1;
		int y = (wantor >> i) & 1;
		if (x == 1) { if (y == 0) return 0; else continue; }
		if (y == 0) { if (x == 1) return 0; else continue; }
		b[nb++] = i;
	}
	REP(mask, 1 << MAXBITS) cnt[mask] = 0;
	REP(i, n) valid[i] = true;
	REP(i, n) if ((a[i] & wantand) != wantand) valid[i] = false;
	REP(i, n) if ((a[i] | wantor) != wantor) valid[i] = false;
	REPE(i, n) { choose[i][0] = choose[i][i] = 1; FOR(j, 1, i) choose[i][j] = choose[i - 1][j - 1] + choose[i - 1][j]; }
	REPE(i, n) { ways[i] = 0; FORE(j, 1, min(i, mxchoose)) ways[i] += choose[i][j]; }
	ll ret = 0; 
	REP(subset, 1 << nb) {
		int mask = 0, bitcount = 0; REP(i, nb) if (subset&(1 << i)) mask |= 1 << b[i], ++bitcount;
		nseen = 0;
		REP(i, n) if (valid[i]) {
			int idx = a[i] & mask;
			if (cnt[idx] == 0) seen[nseen++] = idx;
			++cnt[idx];
		}
		ll cur = 0;
		REP(i, nseen) {
			int idx = seen[i];
			//printf("\t%x:%d\n", idx, cnt[idx]);
			cur += ways[cnt[idx]];
		}
		//printf("%x: %lld\n", mask, cur);
		if (bitcount % 2 == 0) ret += cur; else ret -= cur;
		REP(i, nseen) cnt[seen[i]] = 0;
	}
	return ret;
}

void run() {
	scanf("%d%d%d%d", &n, &mxchoose, &wantand, &wantor);
	REP(i, n) scanf("%d", &a[i]);
	printf("%lld\n", solve());
}

int main() {
	run();
	return 0;
}

