constexpr bool parity32(std::uint_fast32_t c) noexcept {
  c ^= c >> 1;
  c ^= c >> 2;
  return ((c & 0x11111111) * 0x11111111 >> 28 & 0x1) != 0;
}

namespace n91 {

constexpr bool get(const usize x, const usize i) { return x >> i & 1; }

#include <vector>

void superset_zeta_transform(std::vector<usize> &a) {
  const usize n = a.size();
  for (usize i = 1; i < n; i *= 2) {
    for (usize j = 0; j != n; j += 1) {
      if ((j & i) != 0)
        a[j & ~i] += a[j];
    }
  }
}

static constexpr usize bitlen = 28;

void solve(const std::vector<usize> a, const usize k, const usize bitlent) {
  const usize n = a.size();

  u64 ans = 0;

  auto comb = md_vec(n + 1, k, u64(0));
  std::vector<u64> sel(n + 1, 0);
  for (const usize i : rep(0, n + 1)) {
    for (const usize j : rep(0, k)) {
      if (i < j) {
        comb[i][j] = 0;
      } else if (j == 0 || i == j) {
        comb[i][j] = 1;
      } else {
        comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
      }
    }
    for (const usize j : rep(0, k)) {
      sel[i] += comb[i][j];
    }
  }

  std::vector<int> par(1 << bitlent);
  for (const usize i : rep(0, 1 << bitlent)) {
    par[i] = parity32(i);
  }

  for (const usize i : rep(0, n)) {
    std::vector<usize> s(1 << bitlent, 0);
    const usize mask = (1 << bitlent) - 1;
    for (const usize j : rep(i + 1, n)) {
      s[mask ^ a[i] ^ a[j]] += 1;
    }
    superset_zeta_transform(s);
    for (const usize k : rep(0, 1 << bitlent)) {
      const u64 c = sel[s[k]];
      if (par[k]) {
        ans -= c;
      } else {
        ans += c;
      }
    }
  }

  std::cout << ans << eoln;
}

void main_() {
  /*
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  //*/
  const usize n = scan<usize>();
  const usize k = scan<usize>();
  const usize s = scan<usize>();
  const usize t = scan<usize>();
  if ((s & ~t) != 0) {
    std::cout << 0 << eoln;
    return;
  }
  std::vector<usize> a(n);
  for (auto &e : a) {
    std::cin >> e;
  }
  std::vector<usize> b;
  usize count = 0;
  for (const auto e : a) {
    bool f = true;
    usize c = 0;
    usize r = 0;
    for (const usize i : rep(0, bitlen)) {
      if (get(s, i) && !get(e, i)) {
        f = false;
      }
      if (!get(t, i) && get(e, i)) {
        f = false;
      }
      if (get(s, i) || !get(t, i)) {
        continue;
      }
      if (get(e, i)) {
        r |= 1 << c;
      }
      c += 1;
    }
    count = c;
    if (f) {
      b.push_back(r);
    }
  }
  solve(b, k, count);
}

