                    z = false;
                    break;
                }
            }
            if (!(s & (1 << j)) && !(t & (1 << j)))
            {
                if ((a[i] & (1 << j)))
                {
                    z = false;
                    break;
                }
            }
        }
        if (z)
            v.push_back(a[i]);
    }
    n = v.size();
    for (int i = 0; i < n; ++i)
        a[i] = v[i];
    v.clear();
    for (int i = 0; i < m; ++i)
    {
        if (!(s & (1 << i)) && (t & (1 << i)))
            v.push_back(i);
    }
    vector<pair<int, int> > mp;
    for (int i = 0; i < n; ++i)
    {
        for (int x = 0; x < (1 << v.size()); ++x)
        {
            pair<int, int> u = m_p(0, 0);
            for (int j = 0; j < v.size(); ++j)
            {
                if ((x & (1 << j)))
                {
                    ++u.se;
                    if ((a[i] & (1 << v[j])))
                        u.fi += (ast[v[j]] * 1);
                    else
                        u.fi += (ast[v[j]] * 2);
                }
            }
            mp.push_back(u);
        }
    }
    for (int u = 1; u <= 50; ++u)
    {
        for (int i = 1; i <= k; ++i)
            p[u] += C[u][i];
    }
    ll ans = 0;
    sort(all(mp));
    int q = 1;
    for (int i = 1; i < mp.size(); ++i)
    {
        if (mp[i] == mp[i - 1])
        {
            ++q;
        }
        else
        {
            if (mp[i - 1].se % 2 == 0)
                ans += p[q];
            else
                ans -= p[q];
            q = 1;
        }
    }
    if (mp.back().se % 2 == 0)
        ans += p[q];
    else
        ans -= p[q];
    /*for (auto it = mp.begin(); it != mp.end(); ++it)
    {
        if (it->fi.se % 2 == 0)
        {
            ans += p[it->se];
        }
        else
        {
            ans -= p[it->se];
        }
    }*/
    printf("%lld\n", ans);
}

