std::map<u64, u64> dp[2][51];

signed main() {
	INIT;

	VAR(int, n, k);
	VAR(u64, s, t);
	VEC(u64, a, n);

	{
		V<u64> b;
		for (auto& x : a) {
			if ((x & s) != s) continue;
			if ((~x & ~t) != ~t) continue;
			b.emplace_back(x);
		}
		a = b;
		n = a.size();
	}

	const int L = 18;
	dp[0][0][((1ull << L) - 1) << L] = 1;

	REP(i, n) {
		int cur = i & 1, nex = 1 - cur;
		REP(j, k + 1) {
			for (auto& p : dp[cur][j]) {
				u64 bit = p.first;
				u64 sum = p.second;
				if (sum == 0) continue;

				dp[nex][j][bit] += sum;
				if (j + 1 <= k) {
					bit &= (a[i] << L) + (1ull << L) - 1;
					bit |= a[i];
					if (((bit >> L) & s) != s) continue;
					if ((~(bit & ((1ull << L) - 1)) & ~t) != ~t) continue;
					dp[nex][j + 1][bit] += sum;
				}
			}
		}
		REP(j, k + 1) dp[cur][j].clear();
	}
	u64 ans = 0;
	const u64 bit = (s << L) + t;
	REP(j, k + 1) {
		ans += dp[n & 1][j][bit];
	}
	OUT(ans)BR;

	return 0;
}

