int n, m, k;
ll C[N][N];
int a[N];
int dp[(1<<18)];
const int L = 18;

int main () {
	SpeedForce;
	setIO();

	int s, t;
	cin >> n >> k >> s >> t;
	for(int i = 1; i <= n; ++i) {
		cin >> a[i];
		if((s&a[i]) == s && (t|a[i]) == t) {
			continue;
		}
		--i, --n;
	}

	C[0][0] = 1;
	For (i, 1, n) {
		C[i][0] = 1;
		For (j, 1, i) {
			C[i][j] = C[i-1][j-1] + C[i-1][j];
		}
	}

	int goal = (~s)&t;
	ll ans = 0;
	For (i, 1, n) {
		memset(dp, 0, sizeof dp);
		For (j, i+1, n) {
			int msk = ((a[i] ^ a[j])&goal);
			dp[msk] ++;
		}
		for (int bit = 0; bit < L; ++bit) {
			for(int msk = 0; msk < (1<<L); ++msk) if(!(msk&(1<<bit))) {
				dp[msk^(1<<bit)] += dp[msk];

			}
		}

		for (int msk = goal; ; msk = (msk-1)&goal) {
			int tot = dp[msk];
			ll sum = 0; 
			for(int i = 0; i < k; ++i)
				sum += C[tot][i];

			if (__builtin_popcount(msk^goal)%2 == 0) ans += sum;
			else ans -= sum;

			if(!msk) break;
		}
	}

	cout << ans << endl;

	return Accepted;
}

