typedef long long ll;

int n, k, AND, OR, bit, bitMax;
int arr[52];
vector<int> avaliableBits;

ll DP[52][1<<18];
ll ans;
ll table[52][52];

void checkAble(){
    int asd1 = INT_MAX, asd2 = 0;
    for(int i=1; i<=n; i++){
        asd1 &= arr[i], asd2 |= arr[i];
    }
    if(AND != asd1 || OR != asd2){
        printf("0");
        exit(0);
    }
}

int cnt;
ll ret, tmpOR;

ll getAns(int tmp){
    cnt = ret = tmpOR = 0;

    for(int i=1; i<=n; i++){
        if((tmp | arr[i]) == arr[i]) tmpOR |= arr[i];
    }
    if(tmpOR != bitMax) return 0;

    for(int j=0; j<=k; j++){
        for(int x=(bitMax^tmp); x>0; x=(x-1)&(bitMax^tmp)){
            DP[j][x^bitMax] = 0;
        }
        DP[j][bitMax] = 0;
    }
    DP[0][tmp] = 1;

    for(int i=1; i<=n; i++){
        if((tmp | arr[i]) != arr[i]) continue;
        cnt++;
        for(int j=min(cnt, k)-1; j>=0; j--){
            for(int x=(bitMax^tmp); x>0; x = (x-1) & (bitMax^tmp)){
                DP[j+1][(x^bitMax)|arr[i]] += DP[j][x^bitMax];
            }
            DP[j+1][bitMax|arr[i]] += DP[j][bitMax];
        }
    }

    for(int i=1; i<=k; i++){
        ret += DP[i][bitMax];
    }
//    printf("%d -> %lld\n", tmp, ret);
    return ret;
}

int main(){
    scanf("%d %d %d %d", &n, &k, &AND, &OR);

    for(int i=1; i<=n; i++){
        scanf("%d", &arr[i]);
        if(((arr[i] & AND) != AND) || ((arr[i] | OR) != OR)) i--, n--;
    }
    checkAble();

    for(int d=0; d<18; d++){
        if((OR & (1<<d)) && !(AND & (1<<d))){
            avaliableBits.push_back(d);
        }
    }
    bit = (int)avaliableBits.size();
    bitMax = 1<<bit;
    bitMax--;
    for(int i=1; i<=n; i++){
        int tmp = 0;
        for(int j=0; j<bit; j++){
            tmp += (!!(arr[i] & (1<<avaliableBits[j]))) << j;
        }
        arr[i] = tmp;
    }

    if(bitMax == 0){
        table[0][0] = 1;
        for(int i=1; i<=50; i++){
            table[i][0] = 1;
            for(int j=1; j<=i; j++){
                table[i][j] = table[i-1][j-1] + table[i][j];
            }
        }
        for(int i=0; i<=k; i++){
            ans += table[n][i];
        }
        printf("%lld", ans);
        return 0;
    }

    for(int i=0; i<=bitMax; i++){
        if(__builtin_popcount(i) % 2 == 0){
            ans += getAns(i);
        }
        else ans -= getAns(i);
    }

    printf("%lld", ans);
}

