const int MaxN = 55, MaxW = 1 << 18;

ll C[MaxN][MaxN], F[MaxN];

void init_binom(int n, int k) {
	for (int i = 0; i <= n; ++i) {
		C[i][0] = 1; F[i] = 0;
		for (int j = 1; j <= i && j <= k; ++j) {
			F[i] += C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
		}
	}
}

int buk[MaxW];

int main() {
	int n, k; uint S, T;
	scanf("%d%d%u%u", &n, &k, &S, &T);
	init_binom(n, k);
	std::vector<uint> arr;
	for (int i = 0; i < n; ++i) {
		uint x; scanf("%u", &x);
		if (S == (S & x) && T == (T | x)) arr.push_back(x);
	}
	uint M = ~S & T;
	ll ans = F[arr.size()];
	for (uint S = M; S; --S &= M) {
		for (uint x: arr) ++buk[x & S];
		ll sum = 0;
		for (uint x: arr) {
			int &t = buk[x & S];
			sum += F[t];
			t = 0;
		}
		ans += __builtin_popcount(S) & 1 ? -sum : sum;
	}
	printf("%lld\n", ans);
	return 0;
}

