          arr[j] = (A[j] >> i) & 1;
        }
        stock.emplace_back(arr);
        tap.emplace_back(1);
      } else if(x == 0) { // すべて1だとダメ
        vector< int > arr(N);
        for(int j = 0; j < N; j++) {
          if((A[j] >> i) & 1) arr[j] = 0; // すべて1だとまずい
          else arr[j] = 1;
        }
        stock.emplace_back(arr);
        tap.emplace_back(0);
      } else if(y == 1) { // すべて0だとダメ
        vector< int > arr(N);
        for(int j = 0; j < N; j++) {
          if((A[j] >> i) & 1) arr[j] = 1;
          else arr[j] = 0;
        }
        stock.emplace_back(arr);
        tap.emplace_back(0);
      }
    }
  }
  int64 ret = 0;
  for(int i = 0; i < (1 << stock.size()); i++) {
    vector< int > build(stock.size());
    for(int j = 0; j < stock.size(); j++) {
      if((i >> j) & 1) {
        build[j] = (1LL << N) - 1;
      } else {
        for(int k = 0; k < N; k++) {
          if(stock[j][k] == 0) build[j] |= 1LL << k;
        }
      }
    }
    int64 choose = 0;
    auto rec = MFP([&](auto rec, int bit, int64 val) -> void {
      if(val == 0) return;
      if(bit == stock.size()) {
        choose += C[__builtin_popcount(val)][K];
        return;
      }
      if((i >> bit) & 1) {
        rec(bit + 1, val);
        return;
      }
      if(tap[bit] == 0) {
        rec(bit + 1, val & build[bit]);
      } else {
        rec(bit + 1, val & build[bit]);
        rec(bit + 1, val & (((1LL << N) - 1) ^ build[bit]));
      }
    });
    rec(0, (1LL << N) - 1);
    if(__builtin_parity(i)) ret += choose;
    else ret -= choose;
  }
  cout << llabs(ret) << "\n";
}

