long long comb[55][55], choose[55];

int N, K, S, T, SP, A[55], C[1 << 18], P[1 << 18];

void dnc(int l, int r, int b)
{
	if (l + 1 == r) return;

	int m = (l + r) / 2;
	dnc(l, m, b / 2);
	dnc(m, r, b / 2);

	if ((T & b) && (SP & b) == 0) for (int i = l, j = m; i < m; i++, j++) C[j] += C[i];
}

int main()
{
	scanf ("%d %d %d %d", &N, &K, &S, &T);

	if ((S & T) != S){
		puts("0");
		return 0;
	}

	for (int i = 0; i < 55; i++){
		comb[i][0] = comb[i][i] = 1;
		for (int j = 1; j < i; j++) comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
		for (int j = 1; j <= K; j++) choose[i] += comb[i][j];
	}

	for (int i = 0; i < N; i++) scanf ("%d", &A[i]);
	for (int j = 1; j < (1 << 18); j++) P[j] = P[j - (j & (-j))] + 1;

	long long ans = 0;
	SP = S;
	for (int b = -1; b < 18; b++){
		if (b >= 0){
			if (S & (1 << b)) continue;
			if (~T & (1 << b)) continue;
			SP ^= (1 << b);
		}

		for (int j = 0; j < (1 << 18); j++) C[j] = 0;
		for (int i = 0; i < N; i++) if ((SP & A[i]) == SP && (T & A[i]) == A[i]) C[A[i]]++;

		dnc(0, (1 << 18), (1 << 17));

		for (int j = 0; j < (1 << 18); j++) if ((SP & j) == SP && (T & j) == j){
			int s = (b >= 0 ? -1 : 1);
			if ((P[T] - P[j]) % 2) s = -s;
			ans += s * choose[C[j]];
		}
	}

	printf ("%lld\n", ans);

	return 0;
}

