void init() {
    for (int i = 0; i < N; i++) {
        c[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
        }
    }
    for (int i = 0; i < N; i++) {
        for (int j = 1; j <= n; j++) {
            c[i][j] += c[i][j - 1];
        }
    }
}

