vector<ll> moebius(vector<ll> f) { //inverse of the first zeta
	int n = sz(f);
	for(int i = 0; (1 << i) < n; i++) {
		rep(j, 0, n) if(!(j & (1 << i))) f[j] -= f[j | (1 << i)];
	}
	return f;
}

