        cin >> a[i];
    if (!isSubmask(A, O))
    {
        cout << 0 << '\n';
        return 0;
    }
    vector<int> v;
    rep(i,0,n)
    {
        if (isSubmask(a[i], O) && isSubmask(A, a[i]))
            v.push_back(a[i]);
    }

    n = sz(v);
    int M = A^O;
    if (!M)
    {
        cout << C[n][k] << '\n';
        return 0;
    }


    ll ans = 0;
    for (int first = 0; first < n; ++first)
    {
        vector<int> vTemp(all(v));
        clr(F, 0);
        for (int i = first + 1; i < n; ++i)
        {
            vTemp[i] = v[i] ^ v[first];
            F[vTemp[i]]++;
        }
        for (int i = 0; i < L; ++i)
            for (int msk = 0; msk < (1<<L); ++msk)
                if (msk & (1<<i))
                    F[msk] += F[msk^(1<<i)];

        ans += C[n - first - 1][k - 1];
        for (int msk = (M-1)&M; msk > 0; msk = (msk - 1)&M)
        {
            ll temp = C[F[msk]][k - 1];
            int z = countZeros(msk) - countZeros(M);
            if (z&1)
                ans -= temp;
            else
                ans += temp;
        }
    }


