LL comb[100][100];
LL sumC[100][100];

inline LL calcC(int n, int k) {
    if (n == 0 && k >= 0) return 1;
    if (n < 0 || k < 0) return 0;
    return sumC[n][k];
}

void init() {
    comb[0][0] = 1;
    for (int i : range(60)) {
        for (int j : range(i + 1)) {
            comb[i + 1][j] += comb[i][j];
            comb[i + 1][j + 1] += comb[i][j];
        }
        sumC[i][0] = comb[i][0];
        for (int j : range(1, 60)) {
            sumC[i][j] = sumC[i][j - 1] + comb[i][j];
        }
    }
}

// U(S) = g となるサイズc-1個の集合S \in bを数える
LL solveSubProblem(vector<int> b, int c, int g) {
    int sz = b.size();
    LL ret = 0;
    for (int bit : range(g + 1)) {
        int on = 0;
        for (auto e : b) {
            if (((~e) & bit) == bit) on++;
        }
        // cnt := bitで立っているビットが全て0になるような組み合わせの個数
        LL cnt  = calcC(on, c);
        int sgn = ((__builtin_popcountll(bit)) & 1) ? -1 : 1;
        // cerr << bitset<18>(bit).to_string().substr(16) << " " << on << " "
        //      << sgn << " " << cnt << endl;
        ret += sgn * cnt;
    }
    return ret;
}


int n, k;
int s, t;
vector<int> a;


void solve() {
    init();
    LL ret = 0;
    for (int i : range(n)) {
        vector<int> b;
        for (int j : range(i + 1, n)) {
            b.push_back(a[j] ^ a[i]);
        }
        auto c = solveSubProblem(b, k - 1, t);
        assert(c >= 0);
        ret += c;
    }
    cout << ret << endl;
}


int main() {
    /* write here */
    cin >> n >> k >> s >> t;
    if ((s & t) != s) {
        cout << 0 << endl;
        return 0;
    }
    map<int, int> to;
    {
        int p = 1;
        for (int i : range(18)) {
            if (((s ^ t) >> i) & 1) {
                to[i] = p;
                p <<= 1;
            }
        }
    }
    for (int i : range(n)) {
        int x;
        cin >> x;
        if ((s & x) != s) continue;
        if ((t & x) != x) continue;
        int y = 0;
        for (int i : range(18)) {
            if (((x >> i) & 1) && to.count(i)) {
                y += to[i];
            }
        }
        a.push_back(y);
    }
    n = a.size();
    s = 0;
    t = to.rbegin()->second * 2 - 1;
    if (t == 0 && a.size() == 1) {
        cout << 1 << endl;
        return 0;
    }
    cerr << s << " " << t << endl;
    cerr << join(a, "\n") << endl;
    solve();
    return 0;
}

