int main() {
  ios_base::sync_with_stdio(0); cin.tie(0);

  int n, mxCar, s, t; cin >> n >> mxCar >> s >> t;
  vec<int, 1> a(n);
  for (auto& i : a) {
    cin >> i;
  }

  vec<bool, 1> del(18);
  for (int i = 0; i < 18; ++i) {
    del[i] = (s >> i & 1) || !(t >> i & 1);
  }
  int const mxBit = static_cast<int>(count(all(del), false));

  vec<int, 1> b;
  for (auto& i : a) {
    int ret = 0;
    for (int k = 0, j = 0; k < 18; ++k) {
      if (del[k]) {
        if (((s >> k & 1) && !(i >> k & 1)) || (!(t >> k & 1) && (i >> k & 1))) {
          ret = -1;
          break ;
        }
      } else {
        if (i >> k & 1) {
          ret |= 1 << j;
        }
        ++j;
      }
    }
    if (~ret) {
      b.emplace_back(ret);
    }
  }
  a = b;
  s = 0;
  t = (1 << mxBit) - 1;

  vec<LL, 2> binom(sz(a) + 1), pref(sz(a) + 1);
  for (int i = 0; i < sz(binom); ++i) {
    binom[i] = pref[i] = vec<LL, 1>(i + 1);
    binom[i][0] = binom[i][i] = 1;
    for (int j = 1; j < i; ++j) {
      binom[i][j] = binom[i - 1][j - 1] + binom[i - 1][j];
    }
    for (int j = 1; j <= i; ++j) {
      pref[i][j] = pref[i][j - 1] + binom[i][j];
    }
  }

  LL ans = 0;

  vec<int, 1> cnt(1 << mxBit), vis(1 << mxBit);
  for (int mask = 0; mask < 1 << mxBit; ++mask) {
    LL ret = 0;
    for (auto& i : a) {
      ++cnt[i & mask];
    }
    for (auto& i : a) {
      if (!vis[i & mask]) {
        int tmp = cnt[i & mask];
        ret += (tmp < mxCar ? pref[tmp][tmp] : pref[tmp][mxCar]);
        vis[i & mask] = true;
      }
    }
    for (auto& i : a) {
      --cnt[i & mask];
      vis[i & mask] = false;
    }

    ans += (__builtin_popcount(mask) & 1 ? -ret : ret);
  }

  cout << ans << '\n';

  return 0;
}

