ll del(ll x, int z) {
  return
    (x & ((1ll << z) - 1)) |
    ((x >> (z + 1)) << z);
}

bool getbit(ll x, int z) {
  return !!(x & (1ll << z));
}

auto rekkyo(vector<ll> a) {
  int n = a.size();
  vector<vector<pair<ll, ll>>> res(a.size() + 1);
  for(int i = 0; i < (1 << n); i++) {
    int cnt = 0;
    ll vAND = (1ll << D) - 1;
    ll vOR = 0;
    for(int j = 0; j < n; j++) {
      if((i >> j) & 1) {
        cnt++;
        vAND &= a[j];
        vOR |= a[j];
      }
    }
    res[cnt].emplace_back(vAND, vOR);
  }
  return res;
