//-------------------------------------------------------

int N,K,S,T;
int A[51],B[51],C[51];

ll from[51][1<<18];
ll to[51][1<<18];

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N>>K>>S>>T;

	FOR(i,N) {
		cin>>A[i];
		if(A[i]&~T) {
			i--;
			N--;
			continue;
		}
		if((A[i]&S)!=S) {
			i--;
			N--;
			continue;
		}
		B[i]=A[i]^((1<<18)-1);
	}

	ll ret=0;

	int mask,tomask;
	FOR(i,N) {
		int add=0;
		int del=0;
		FOR(j,18) {
			if((S&(1<<j))==0 &&(T&(1<<j))) {
				if(A[i]&(1<<j)) del |= 1<<j;
				else add |= 1<<j;
			}
		}
		tomask=add | del;
		ZERO(from);
		from[0][0]=1;
		for(j=i+1;j<N;j++) {
			for(x=j-i-1;x>=0;x--) {
				for(int mask=tomask; mask>=0; mask--) {
					mask&=tomask;
					if(from[x][mask]) {
						int tar=mask;
						tar |= B[j]&del;
						tar |= A[j]&add;
						from[x+1][tar]+=from[x][mask];
					}
				}
			}
		}
		for(j=1;j<=K-1;j++) ret+=from[j][tomask];

	}
	cout<<ret<<endl;

}


