void Gen(int lvl, int mask)
{
    if (lvl >= dif.size()) {
        ll cur = 0;
        for (int i = 0; i < n; i++) {
            int oth = 0;
            for (int j = i + 1; j < n; j++)
                if ((a[i] & mask) == (a[j] & mask)) oth++;
            cur += ways[oth];
        }
        if (__builtin_popcount(mask) % 2) res -= cur;
        else res += cur;
    } else {
        Gen(lvl + 1, mask);
        Gen(lvl + 1, mask | 1 << dif[lvl]);
    }
}

