int main() {
    setIO();

    const int MAXN = 50;

    vvll ncr(MAXN+1, vll(MAXN+1));
    ncr[0][0] = 1;

    FOR (n, 1, MAXN + 1) {
        F0R (r, n + 1) {
            ncr[n][r] = ncr[n-1][r];
            if (r) ncr[n][r] += ncr[n-1][r-1];
        }
    }

    const int B = 18;
    const int M = 1 << B;

    int N, K, S, T; re(N, K, S, T);

    vll pick(MAXN + 1);
    FOR (v, 1, MAXN + 1)
        FOR (c, 1, min(K, v) + 1)
            pick[v] += ncr[v][c];

    vi a;
    F0R (i, N) {
        int v; re(v);
        if ((S & v) != S) continue;
        if ((T | v) != T) continue;
        a.pb(v);
    }

    vi table(M);

    ll ans = 0;

    int must_fix = S ^ T ^ (M - 1);

    for (int fix = must_fix; fix < M; fix = (fix + 1) | must_fix) {
        trav (e, a) {
            table[fix & e]++;
        }

        trav (e, a)
            if (int &ct = table[fix & e]) {
                //cerr << fix << " " << (fix & e) << " " << ct << endl;
                if (__builtin_popcount(fix ^ must_fix)&1)
                    ans -= pick[ct];
                else
                    ans += pick[ct];
                ct = 0;
            }
    }

    ps(ans);

    return 0;
}

