int binomialCoefficients(int n, int k) {
	vector<int> C(70, 0);
	C[0] = 1;
	for (int i = 1; i <= n; i++) {
		for (int j = min(i, k); j > 0; j--)
			C[j] = C[j] + C[j - 1];
	}
	return C[k];
}

int calc_ways(vector<int>& nums, vector<int>& cnts, int mask)
{
	map<int, int> mm;
	for (int x : nums)
	{
		mm[x & mask]++;
	}
	int ret = 0;
	for (auto& x : mm)
	{
		ret += cnts[x.second];
	}
	return ret;
}

