void solve() {
	int n, k, s, t; cin >> n >> k >> s >> t;
    vector<int> a(n);
    rep(i, n) {
        cin >> a[i];
    }
    vector<bool> ok(n, 1);
    vector<int> v;
    for(int bit = 0; bit < 18; ++ bit) {
        int mask = (1<<bit);
        if(!(s & mask) && !(t & mask)) {
            rep(i, n) {
                if(a[i] & mask) ok[i] = 0;
            }
        } else if(!(s & mask) && (t & mask)) {
            v.push_back(bit);
        } else if((s & mask) && !(t & mask)) {
            cout << 0 << endl;
            return;
        } else {
            rep(i, n) {
                if(!(a[i] & mask)) ok[i] = 0;
            }
        }
    }
    vector<vector<int>> c(n + 1, vector<int>(n + 1));
    for(int i = 0; i <= n; ++ i) {
        c[i][0] = 1;
        for(int j = 1; j <= i; ++ j) {
            c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
        }
    }
    vector<int> ways(n + 1, 0);
    rep(i, n + 1) {
        for(int j = 1; j <= min(k, i); ++ j) {
            ways[i] += c[i][j];
        }
    }
    int ans = 0;
    int sz = (int)v.size();
    for(int bit = 0; bit < (1<<sz); ++ bit) {
        int sign = (__builtin_popcount(bit) % 2 == 0 ? 1 : -1);
        map<int, int> mp;
        rep(i, n) {
            int now = 0;
            if(ok[i]) {
                rep(j, sz) {
                    if((1<< j) & bit) {
                        int mask = (1<<v[j]);
                        if(mask & a[i]) {
                            now ^= mask;
                        }
                    }
                }
            }
            mp[now] ++;
        }
        for(auto p: mp) {
            ans += sign * ways[p.sc];
        }
    }
    cout << ans << endl;
}

