        if (((t >> i) & 1) == 1) {
            cond.push_back({ i, 1 });
        }
    }
    vector<unordered_map<long long, long long>> dp(k + 1);
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        long long mask = 0;
        for (int j = 0; j < (int)cond.size(); ++j) {
