                mask ^= 1LL << j;
            }
        }
        vector<unordered_map<long long, long long>> nex(k + 1);
        for (int j = 0; j <= k; ++j) {
            for (auto& l : dp[j]) {
                nex[j][l.first] += l.second;
                if (j < k)
                    nex[j + 1][l.first | mask] += l.second;
            }
        }
        dp = nex;
    }
    long long ans = 0;
    for (auto& i : dp) {
