{
    int N, K, S, T; cin >> N >> K >> S >> T;
    vector<int> A(N); cin >> A;

    vector<int> B;
    int NOT_T = ~T;
    rep(i, N) {
        if ((A[i] & S) == S && (A[i] & NOT_T) == 0) {
            B.push_back(A[i]);
        }
    }

    map<pair<int, pii>, int> dp; // first個 andしたらsecond.firstになり、orしたらsecond.secondになった個数
    dp[make_pair(0, make_pair((1<<18)-1, 0))] = 1;
    for (int i = 0; i < B.size(); i++) {
        map<pair<int, pii>, int> t = dp;
        for (const auto& p : t) {
            const int& ck = p.first.first;
            const int& sand = p.first.second.first;
            const int& sor = p.first.second.second;
            const int& cnt = p.second;
            if (ck < K) {
                dp[make_pair(ck+1, make_pair(sand & B[i], sor | B[i]))] += cnt;
            }
        }
    }

    ll ans = 0;
    for (int k = 1; k <= K; k++) {
        // D2(k, dp[make_pair(k, make_pair(S, T))]);
        ans += dp[make_pair(k, make_pair(S, T))];
    }

