int D = 18;

void output(ll ans) {
  cout << ans << endl;
  exit(0);
}

// x includes y
// y is in x
bool includes(ll x, ll y) {
  return ((x & y) == y) != 0;
}

ll del(ll x, int z) {
  return
    (x & ((1ll << z) - 1)) |
    ((x >> (z + 1)) << z);
}

bool getbit(ll x, int z) {
  return !!(x & (1ll << z));
}

int logmsb(int x) {
  int h = 0;
  x = x & 0xFFFF0000 ? (h += 16, x) & 0xFFFF0000 : x;
  x = x & 0xFF00FF00 ? (h += 8, x) & 0xFF00FF00 : x;
  x = x & 0xF0F0F0F0 ? (h += 4, x) & 0xF0F0F0F0 : x;
  x = x & 0xCCCCCCCC ? (h += 2, x) & 0xCCCCCCCC : x;
  x = x & 0xAAAAAAAA ? (h += 1, x) & 0xAAAAAAAA : x;
  return h;
}

int popcountll(ll x) {
  x = (x & 0x5555555555555555) + ((x & 0xAAAAAAAAAAAAAAAA) >> 1);
  x = (x & 0x3333333333333333) + ((x & 0xCCCCCCCCCCCCCCCC) >> 2);
  x = (x & 0x0F0F0F0F0F0F0F0F) + ((x & 0xF0F0F0F0F0F0F0F0) >> 4);
  x = (x & 0x00FF00FF00FF00FF) + ((x & 0xFF00FF00FF00FF00) >> 8);
  x = (x & 0x0000FFFF0000FFFF) + ((x & 0xFFFF0000FFFF0000) >> 16);
  x = (x & 0x00000000FFFFFFFF) + ((x & 0xFFFFFFFF00000000) >> 32);
  return x;
}

auto rekkyo(vector<ll> a) {
  int n = a.size();
  vector<vector<pair<ll, ll>>> res(a.size() + 1);
  vector<pair<ll, ll>> dp(1 << n);
  dp[0] = pair<ll, ll>((1ll << D) - 1, 0);
  res[0].emplace_back((1ll << D) - 1, 0);

  for(int i = 1; i < (1 << n); i++) {
    int cnt;
    int rmb = logmsb(i);
    auto [vAND, vOR] = dp[i ^ (1 << rmb)];
    cnt = popcountll(i);
    vAND &= a[rmb];
    vOR |= a[rmb];
    res[cnt].emplace_back(vAND, vOR);
    dp[i] = pair<ll, ll>(vAND, vOR);
  }
  return res;
}

using P = pair<int, ll>;
vector<P> mrg(vector<P> a, vector<P> b) {
  vector<P> r;
  int ai = 0, bi = 0;
  while(ai < a.size() || bi < b.size()) {
    bool chooseA = 0;
    if(ai == a.size()) chooseA = 0;
    else if(bi == b.size()) chooseA = 1;
    else if(a[ai] < b[bi]) chooseA = 1;
    else chooseA = 0;
    if(chooseA) {
      r.push_back(a[ai]);
      ai++;
    } else {
      r.push_back(b[bi]);
      bi++;
    }
  }
  return r;
}

// fzt {{{
// n is power of 2
vector<vector<P>> fzt(vector<vector<P>> a) {
  int n = a.size();
  for(int i = 1; i < n; i <<= 1)
    for(int j = 0; j < n; j++)
      if((j & i) == 0) {
        // a[j] += a[j | i];
        a[j] = mrg(a[j], a[j | i]);
      }
  return a;
}
