int main(int argc, char** argv) {
  cin.tie(NULL);
  cout.tie(NULL);
  ios_base::sync_with_stdio(false);
  //cout << setprecision(10) << fixed;

  ll n,k,s,t;
  cin >> n >> k >> s >> t;
  vector<ll> a(n);
  rep(i,n) {
    cin >> a[i];
  }

  // Check t,s
  if ((t&s) != s) {
    cout << 0 << endl;
    return 0;
  }

  // Pre-calculation of Combination
  vector<vector<ll>> comb(n+1, vector<ll>(n+1));
  rep(i,n+1) {
    comb[i][0] = 1;
    for (int j = 1; j <= i; ++j) {
      comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
    }
  }
  // ways[i] .. sum of comb[i][j] where j <= k
  vector<ll> ways(n+1);
  rep(i,n+1) {
    for (int j = 1; j <= min(i,k); ++j) {
      ways[i] += comb[i][j];
    }
  }

  ll ans = 0;
  rep(mask,1ll<<18) {
    // Check mask. mask must be in t^s.
    if ((mask&(t^s)) != mask) {
      continue;
    }

    int sign = (__builtin_popcount(mask)%2 == 0 ? 1 : -1);
    map<ll,ll> cnts;
    rep(i,n) {
      // First, check the validness of a[i]. a[i] must include s. a[i] must not exceed t.
      if ((a[i]&s) != s) {
        continue;
      }
      if ((a[i]|t) != t) {
        continue;
      }
      ++cnts[a[i]&mask];
    }

    for (auto& p : cnts) {
      ans += sign * ways[p.second];
    }
  }
  cout << ans << endl;
}

