inline long long dfs(re int p,re int x,re int y,re int cnt){
	re long long hsh=1ll*(1ll<<18)*x+y+1ll*(1ll<<40)*cnt+1ll*(1ll<<50)*p;
	if(v.find(hsh)!=v.end())return v[hsh];
	if(p==0){
		if(x==s&&y==t)return 1;
		return 0;
	}
	if((y|b[p])&t!=(y|b[p]))return 0;
	if((x&s)!=s)return 0;
	re long long ans=0;
	ans+=dfs(p-1,x,y,cnt);
	if(cnt^k)ans+=dfs(p-1,x&a[p],y|a[p],cnt+1);
	return v[hsh]=ans;
}
