        }

        for (int cnt = 0; cnt <= h2; ++cnt) {

            for (int i = 0; i < (1 << len); ++i)
                F[cnt][i] = dp2[cnt][i];
            for (int i = 0; i < len; ++i)
                for (int mask = 0; mask < (1 << len); ++mask)
                    if (mask & (1 << i)) F[cnt][mask] += F[cnt][mask ^ (1 << i)];

        }


        for (int cnt = 1; cnt <= h2; ++cnt) {
            for (int mask = 0; mask < (1 << len); ++mask) {
                F[cnt][mask] += F[cnt - 1][mask];
            }
        }

        fori (mask, 1 << h) {
            int cnt = 0;
            int cmask = (1 << len) - 1;
            fori (i, h) {
                if ((mask >> i) & 1) {
                    cnt++;
                    cmask &= b[i];
                }
            }
            cmask = ((1 << len) - 1) ^ cmask;
            int kek = k - 1 - cnt;
            inmin(kek, h2);
            if (kek >= 0)
                ans += F[kek][cmask];
        }

        for (int i = 0; i <= h2; ++i) {
            fori (mask, (1 << len)) {
                F[i][mask] = dp2[i][mask] = 0;
            }
        }
    }

    cout << ans;

}

