template <typename T>
T digitsum(T n){
    string s=to_string(n);
    T sum=0;
    T d=1;
    for(T e=0;e<s.length();e++){
        sum+=(n/d)%10;d*=10;
    }
    return sum;
}
template <typename T>
bool isPrime(T n){
    if(n<=1)return false;
    if(n==2)return true;
    if(n%2==0)return false;
    for(T q=3;q*q<=n;q+=2){
        if(n%q==0)return false;
    }
    return true;
}
template <typename T>
vector<pair<T, T>> prime_factor(T n) {
    vector<pair<T, T>> ret;
    if(n%2==0){
        T tmp = 0;
        while (n % 2 == 0) {
            tmp++;
            n /= 2;
        }
        ret.push_back(make_pair(2, tmp));
    }
    for (T i = 3; i*i <= n; i+=2) {
        if(n%i==0){
            T tmp = 0;
            while (n % i == 0) {
                tmp++;
                n /= i;
            }
            ret.push_back(make_pair( i, tmp));
        }
    }
    if (n != 1) ret.push_back(make_pair(n, 1));
    return ret;
}
long long int intpow(long long int x,long long int n){
    long long int ans=1;
    for(int i=0;i<n;i++){
        ans*=x;
    }
    return ans;
}
template <typename T>T intlog(T x){
    string a=to_string(x);
    return a.length()-1;
}
long long int combination(long long int a,long long int b){
    queue<long long int> bunsi,bunbo;
    long long int ans=1;
    b=min(b,a-b);
    for(int i=0;i<b;i++){
        bunsi.push(a-i);
        if(b-i>=2)bunbo.push(b-i);
    }
    while(bunsi.size()!=0||bunbo.size()!=0){
        ans*=bunsi.front();
        bunsi.pop();
        if(ans%bunbo.front()==0){
            ans/=bunbo.front();
            bunbo.pop();
        }
    }
    return ans;
}

#include <bits/stdc++.h>

using i64 = int64_t;
template <class T> using Vec = std::vector<T>;

using namespace std;

struct Builder {
    int s, t, k;
    const Vec<int> &as;

    using Res = Vec<map<pair<int, int>, i64>>;

    Res build(int l, int r) {
        if (r - l == 1) {
            return {
                {{{t, s}, 1}},
                {{{as[l], as[l]}, 1}},
            };
        }

        int m = (l + r) / 2;
        auto lhs = build(l, m), rhs = build(m, r);

        Res res(min<int>(lhs.size() + rhs.size() - 1, k + 1));
        int a1, o1, a2, o2;
        for (int i = 0; i < lhs.size(); ++i) for (int j = 0; j < rhs.size(); ++j) {
            if (i + j > k) break;

            for (auto [k1, v1] : lhs[i]) for (auto [k2, v2] : rhs[j]) {
                tie(a1, o1) = k1, tie(a2, o2) = k2;
                res[i + j][{a1 & a2, o1 | o2}] += v1 * v2;
            }
        }

        return res;
    }

};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, k, s, t;
    cin >> n >> k >> s >> t;

    Vec<int> as(n);
    for (auto &a : as) cin >> a;

    if ((s & t) != s || (s | t) != t) {
        cout << 0;
        return 0;
    }

    auto invalid = [&](int a) {
        return s != (s & a) || t != (t | a);
    };
    as.erase(remove_if(as.begin(), as.end(), invalid), as.end());

    n = as.size();

    auto by_andor = Builder{s, t, k, as}.build(0, as.size());
    i64 ans = 0;

    for (int i = 0; i < min<int>(k + 1, by_andor.size()); ++i) ans += by_andor[i][{s, t}];
    cout << ans << '\n';

    return 0;
}

