int main() {
    //freopen("in.txt","r",stdin);
    ios_base::sync_with_stdio(0); cin.tie(0);

    cin>>n>>k>>s>>t;
    for (int i=1;i<=n;i++) cin>>a[i];

    for (int j=0;j<maxn;j++) {
        c[0][j] = 1;
        for (int i=1;i<=j;i++) c[i][j] = c[i-1][j-1] + c[i][j-1];
    }

    for (int i=1;i<=n;i++)
        for (int j=1;j<=min(i,k);j++) sum[i]+=1ll*c[j][i];

    int spec = (s^t);

    int spec0 = spec,tmp=spec,num=0;
    while (tmp>0) {
        int bit = (tmp>>1) & 1;
        spec0 += (bit==0?1:-1) * (1<<num);
        num++;
        tmp>>=1;

    }

    ll ans = 0;
    for (int tt=0;tt<(1<<18);tt++)
        if ((tt&spec) == tt) {
            //cout<<tt<<endl;
            int obit = 0;
            for (int i=0;i<18;i++) obit += (tt>>i)&1;

            vector<int> q;
            for (int i=1;i<=n;i++)
                if ((a[i]&spec0)==(s&t)) q.push_back(a[i]&tt);
            //cout<<q.size()<<endl;
            sort(q.begin(),q.end());
            int b=0,e=0;
            while (b<(int)q.size()) {
                e = b;
                while (e+1<(int)q.size() && q[e]==q[e+1]) e++;
                ans += 1ll * (obit%2==0 ? 1 : -1) * sum[e-b+1];
                b = e+1;
            }
        }
    cout<<ans<<endl;
