                if ((next.first & s) != s) continue;
                if ((next.second | t) != t) continue;
                dp[q + 1][next] += x.second;
            }
        }
        dp[1][mp(inputs[i], inputs[i])]++;
    }
    ll ans = 0;
    for (int i = 1; i <= k; ++i) {
