    for (int i = 1; i < MAX_C; ++i) {
        Com[i][0] = 1;
        for (int j = 1; j < MAX_C; ++j) {
            Com[i][j] = (Com[i-1][j-1] + Com[i-1][j]);
        }
    }
}

void solve(long long N, long long K, long long S, long long T, std::vector<long long> A){
    i64 L = 0;
    vector<i64> rule(18);
    calc_com();
    rep(i, 18){
        i64 s = (S & (1<<i)) != 0, t = ((T & (1<<i))) != 0;
        if(s == 1 && t == 1) rule[i] = 1;
        else if(s == 0 && t == 0) rule[i] = 0;
        else if(s == 0 && t == 1){rule[i] = 2; L++;}
        else{
            cout << 0 << endl;
            return;
        }
    }
    vector<i64> B;
    rep(i, N){
        i64 flag = true;
        i64 nw = 0;
        for(int j = 17; j >= 0; --j){
            i64 bit = (A[i] & (1<<j)) != 0;
            if(rule[j] == 1 && bit == 0) flag = false;
            if(rule[j] == 0 && bit == 1) flag = false;
            if(rule[j] == 2) nw = nw * 2 + bit;
        }
        if(flag) B.emplace_back(nw);
    }
    N = B.size();
    i64 bar = 0;
    rep(i, N){
        rep(j, 1, 1<<L){
            i64 a = B[i] & j, b = (~B[i]) & j, cnt = 0;
            rep(k, i + 1, N) if(((a & B[k]) == a) && ((b & (~B[k])) == b)) ++cnt;
            if(__builtin_popcount(j) % 2 == 1) rep(k, min(cnt + 1, K)) bar += Com[cnt][k];
            else rep(k, min(cnt + 1, K)) bar -= Com[cnt][k];
        }
    }
    i64 ans = 0;
    rep(i, 1, min(N, K) + 1) ans += Com[N][i];
    cout << ans - bar << endl;
}

