    vector< T > _fact;

    Combination(int sz) : _fact(sz + 1){
        _fact[0] = 1;
        for(int i = 1; i <= sz; i++) _fact[i] = _fact[i - 1] * i;
    }

    inline T fact(int k) const { return _fact[k]; }

    T P(int n, int r) const {
        if(r < 0 || n < r) return 0;
        return fact(n)/fact(r);
    }

    T C(int p, int q) const {
        if(q < 0 || p < q) return 0;
        return fact(p)/fact(q)/fact(p - q);
    }

