#define finish(x) return cout << x << endl, 0
#define ll long long

int n, k, s, t;
vector <int> a;
unordered_map <int, ll> dp[51];

int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    for(int i = 1 ; i <= 50 ; i++){
        dp[i].max_load_factor(0.31);
    }
    srand(time(0));
    cin >> n >> k >> s >> t;
    if((s & t) != s) finish(0);
    for(int i = 0 ; i < n ; i++){
        int x;
        cin >> x;
        if((x & s) != s) continue;
        if((x | t) != t) continue;
        a.push_back(x);
    }
    n = a.size();
    vector <int> bs;
    for(int i = 0 ; i < 18 ; i++){
        if(((t >> i) & 1) && (((s >> i) & 1) == 0)) bs.push_back(i);
    }
    int all = 0;
    for(auto &i : bs) all |= (1 << i);
    ll ans = 0;
    random_shuffle(a.begin(), a.end());
    for(int i = 0 ; i < n ; i++){
        dp[1][0] = 1;
        for(int j = i + 1 ; j < n ; j++){
            for(int sz = k - 1 ; sz >= 0 ; sz--){
                for(auto &h : dp[sz]){
                    dp[sz + 1][h.first | (a[j] ^ a[i])] += h.second;
                }
            }
        }
        for(int sz = 1 ; sz <= k ; sz++){
            ans += dp[sz][all];
            dp[sz].clear();
        }
    }
    cout << ans << endl;
}

