ll solve(V<int> a,int K,int M){
	int N = si(a);
	show(a);show(K);show(M);
	V<ll> f(N+1);
	{
		ll C[60][60]={};
		rep(i,60){
			C[i][0] = C[i][i] = 1;
			rep1(j,i-1) C[i][j] = C[i-1][j-1] + C[i-1][j];
		}
		rep(i,N+1) rep(j,K) f[i] += C[i][j];
	}
	show(f);
	ll ans = 0;
	rep(l,N){
		rep(s,1<<M){
			int match = 0;
			for(int i=l+1;i<N;i++){
				if((a[l]&s) == (a[i]&s)) match++;
			}
			if(__builtin_popcount(s)%2 == 0) ans += f[match];
			else ans -= f[match];
		}
	}
	return ans;
}

