		rep(i,18){
			if(!(S&1<<i) && (T&1<<i)){
				if(v&1<<i) u |= 1<<I;
				I++;
			}
		}
		us.pb(u);
		M = I;
	}
	cout << solve(us,K,M) << endl;
}

