int cnt_bit(long long x)
{
	int cnt = 0;
	while (x) {
		if (x & 1) cnt++;
		x = x >> 1;
	}
	return cnt;
}

void fun(int cur, int sign, long long res, int v)
{
	if (cur == 18) {
		int tmp = cnt_bit(res);
		//cout << sign * F[tmp][k - 1] << E;
		ans += sign * F[tmp][k - 1];
	}
	else {
		if (((t >> cur) & 1) ^ ((s >> cur) & 1)) {
			if ((v >> cur) & 1) {
				fun(cur + 1, sign, res, v);
				fun(cur + 1, -sign, res & candi[1][cur], v);
			}
			else {
				fun(cur + 1, sign, res, v);
				fun(cur + 1, -sign, res & candi[0][cur], v);
			}
		}
		else fun(cur + 1, sign, res, v);
	}
}

