	if((S & T) != T){
		printf("0\n");
		return 0;
	}
	for(int i = 0;i < n;i++){
		int x; scanf("%d", &x);
		v.PB(x);
	}
	n = (int)v.size();
	ll sol = 0;
	for(int i = 0;i < N;i++){
		if((i & T) != T) continue;
		if(__builtin_popcount(i ^ T) % 2 == 0)
			sol += dinamika(i);
		else
			sol -= dinamika(i);
	}
	printf("%lld\n", sol);
	return 0;
}

