int main() {
	vvll com(60, vll(60, 0));
	com[0][0] = 1;
	rep(i, 60)rep(j, 60) {
		if (i > 0)com[i][j] += com[i - 1][j];
		if (i > 0 && j > 0) { com[i][j] += com[i - 1][j - 1]; }
	}

	ll N, K, S, T;
	cin >> N >> K >> S >> T;
	vll A(N, 0);
	rep(i, N) cin >> A[i];

	ll M = 18;
	vll b(M+1, 0);

	rep(i, N)repn(j, M) {
		if ((A[i] >> (j-1)) & 1) { b[j] += 1 << i; }
	}

	//repn(j, M)cout << b[j] << endl;

	vvll dp(M + 1);
	dp[0].assign(1, (1 << N) - 1);

	ll p = 1;
	repn(i, M) {

		p *= 3;
		dp[i].assign(p, 0);

		rep(j, p / 3) {
			dp[i][3 * j] = dp[i - 1][j];
			dp[i][3 * j + 1] = dp[i - 1][j] & b[i];
			dp[i][3 * j + 2] = dp[i - 1][j] & ~b[i];
		}
	}

	//repn(i, M)rep(j, dp[i].size()) { cout << i << " " << j << " " << dp[i][j] << endl; }

	ll ans = 0;

	rep(i, p) {
		if (dp[M][i] == 0) { continue; }

		//cout << i << " " << dp[M][i] << endl;

		vll c(M + 1);
		ll x = i;
		repn(j, M) {
			c[M + 1 - j] = x % 3;
			x /= 3;
		}

		ll hou = 0;
		repn(j, M) {
			ll x = (S >> (j - 1)) & 1;
			ll y = (T >> (j - 1)) & 1;
			if (x == 0 && y == 1) {if (c[j] > 0&&hou>=0) { hou++; }}
			if (x == 0 && y == 0) { if (c[j] != 2) { hou = -1; } }
			if (x == 1 && y == 1) { if (c[j] != 1) { hou = -1; } }
			if (x == 1 && y == 0) { cout << 0 << endl; return 0; }
		}

		if (hou == -1) { continue; }
		hou %= 2;

		ll pop = 0;
		rep(j, N) {
			if ((dp[M][i] >> j) & 1) { pop++; }
		}

		ll cnt = 0;
		rep(j, min(K, pop) + 1) {
			cnt += com[pop][j];
		}

		//cout << hou << " " << cnt << endl << endl;

		if (hou % 2 == 0) { ans += cnt; }
		else { ans -= cnt; }
	}

	cout << ans << endl;
}

