int main() {
	vvll com(60, vll(60, 0));
	com[0][0] = 1;
	rep(i, 60)rep(j, 60) {
		if (i > 0)com[i][j] += com[i - 1][j];
		if (i > 0 && j > 0) { com[i][j] += com[i - 1][j - 1]; }
	}

	ll N, K, S, T;
	cin >> N >> K >> S >> T;
	vll A(N, 0);
	rep(i, N) cin >> A[i];

	ll M = 18;
	vll b(M+1, 0);

	rep(i, N)repn(j, M) {
		if ((A[i] >> (j-1)) & 1) { b[j] += 1 << i; }
	}

	//repn(j, M)cout << b[j] << endl;

	vector <vector<pair<ll, ll>>> dpp(M + 1);
	dpp[0].push_back({ 0,(1 << N) - 1 });


	repn(i, M) {

		for (auto x : dpp[i - 1]) {
			ll j = x.first;
			ll y = x.second;

			if (y > 0)dpp[i].push_back({ 3 * j, y });
			if ((y & b[i]) > 0)dpp[i].push_back({ 3 * j + 1,y & b[i] });
			if ((y & ~b[i]) > 0)dpp[i].push_back({ 3 * j + 2,y & ~b[i] });
		}

	}

	//repn(i, M)for(auto x:dp[i]) { cout << i << " " << x.first << " " << x.second << endl; }

	ll ans = 0;

	for(auto y:dpp[M]) {
		ll i = y.first;

		//cout << i << " " << dp[M][i] << endl;

		vll c(M + 1);
		ll x = i;
		repn(j, M) {
			c[M + 1 - j] = x % 3;
			x /= 3;
		}

		ll hou = 0;
		repn(j, M) {
			ll x = (S >> (j - 1)) & 1;
			ll y = (T >> (j - 1)) & 1;
			if (x == 0 && y == 1) {if (c[j] > 0&&hou>=0) { hou++; }}
			if (x == 0 && y == 0) { if (c[j] != 2) { hou = -1; } }
			if (x == 1 && y == 1) { if (c[j] != 1) { hou = -1; } }
			if (x == 1 && y == 0) { cout << 0 << endl; return 0; }
		}

		if (hou == -1) { continue; }
		hou %= 2;

		ll pop = 0;
		rep(j, N) {
			if ((y.second >> j) & 1) { pop++; }
		}

		ll cnt = 0;
		rep(j, min(K, pop) + 1) {
			cnt += com[pop][j];
		}

		//cout << hou << " " << cnt << endl << endl;

		if (hou % 2 == 0) { ans += cnt; }
		else { ans -= cnt; }
	}

	cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 55, MX = 1 << 18, LG = 18;

int n, k, s, t, a[N], sos[MX];
long long ans = 0, c[N][N];

void init() {
    for (int i = 0; i < N; i++) {
        c[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
        }
    }
    for (int i = 0; i < N; i++) {
        for (int j = 1; j <= n; j++) {
            c[i][j] += c[i][j - 1];
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k >> s >> t;
    init();
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    if ((s & t) != s) {
        return cout << 0, 0;
    }
    for (int fi = 0; fi < MX; fi++) {
        if (((fi & s) == s) && (fi & t) == fi) {
            long long cur = 0;
            int oth = fi ^ t;
            for (int i = 1; i <= n; i++) {
                if ((a[i] & fi) == fi && (a[i] & t) == a[i]) {
                    sos[a[i] ^ fi] = 1;
                }
            }
            for (int i = 0; i < LG; i++) {
                if (oth >> i & 1) {
                    for (int se = oth; se > 0; se = (se - 1) & oth) {
                        if (se >> i & 1) {
                            sos[se] += sos[se ^ (1 << i)];
                        }
                    }
                }
            }
            for (int se = oth; se > 0; se = (se - 1) & oth) {
                cur += ((__builtin_popcount(oth ^ se) & 1) ? -1 : 1) * (c[sos[se]][k] - 1);
                sos[se] = 0;
            }
            cur += ((__builtin_popcount(oth) & 1) ? -1 : 1) * (c[sos[0]][k] - 1);
            sos[0] = 0;
            ans += ((__builtin_popcount(fi ^ s) & 1) ? -1 : 1) * cur;
        }
    }
    cout << ans;
}

