inline ll cmb(int n, int k) {
  if(k < 0 || n < k) return 0;
  return CMB[n][k];
}

// 1以上k以下のsum
inline ll cmbsum(int n, int k) {
  if(k <= 0) return 0;
  return CMBSUM[n][min(k, n)];
}

ll mypow(ll x, int n) {
  if(n == 0) return 1;
  if(x % 2 == 0) return mypow(x*x, n/2);
  return x * mypow(x*x, n/2);
}

vector<int> vs;
int vs2[100];
int n2;
ll solve(int N, int K, int S, int T) {
  if((S & T) != S || (S | T) != T) {
    return 0;
  }
  ll cur = 0;
  int ST = T^S;
  for(int pat1 = ST; ; pat1 = (pat1-1) & ST) {
    n2 = 0;
    REP(i, N) {
      if((vs[i] & pat1) == 0) {
        vs2[n2++] = vs[i];
      }
    }
    int stpat1 = ST^pat1;
    for(int pat2 = stpat1; ; pat2 = (pat2-1) & stpat1) {
      int pat = pat1 | pat2;
      if(pat == 0) {
        break;
      }
      int parity = 0;
      REP(i, 18) {
        if(pat & (1 << i)) {
          parity ^= 1;
        }
      }
      int cnt = 0;
      REP(i, n2) {
        if((vs2[i] & pat2) == pat2) {
          ++cnt;
        }
      }
      ll hoge = cmbsum(cnt, K);
      if(parity) {
        cur += hoge;
      } else {
        cur -= hoge;
      }
      if(pat2 == 0) {
        break;
      }
    }
    if(pat1 == 0) {
      break;
    }
  }
  ll res = cmbsum(N, K) - cur;
  return res;
}

