  REP(i, 51) {
    CMB[i][0] = 1;
    for(int j = 1; j <= i; ++j) {
      CMB[i][j] = CMB[i-1][j-1] + CMB[i-1][j];
      CMBSUM[i][j] = CMBSUM[i][j-1] + CMB[i][j];
    }
  }

  int N, K, S, T;
  scanf("%d%d%d%d", &N, &K, &S, &T);
  REP(i, N) {
    int v;
    scanf("%d", &v);
    if((v & S) == S && (v | T) == T) { // Sが必須かつ、Tの中に収まる必要がある
      vs.push_back(v);
    }
  }
  N = vs.size();

  ll res = 0;
  res = solve(N, K, S, T);
  cout << res << endl;

  return 0;
}

