    vector<ll> a;
    //i bit目を見て、s_i=1,t_i=0の時はi bit目は全ての数が1,0でなければならないので
    REP(i,n){
        bool f=true;
        REP(j,18){
            if((s>>j)&1 and (t>>j)&1){
                if(!((b[i]>>j)&1)){
