            continue;
        if ((a | t) != t)
            continue;
        as.push_back(a);
    }
    for (int i = 0; i <= t; i++) {
        if ((i & s) != s)
            continue;
        if ((i | t) != t)
            continue;
        unordered_map<int, Int> cnt;
        for (auto a : as) {
            cnt[a & i]++;
        }
        Int tmp = 0;
        for (auto p : cnt) {
            tmp += table_sum[p.second];
        }
        if (pop_count[i ^ s] % 2 == 0)
            ans += tmp;
        else
            ans -= tmp;
    }
    cout << ans << endl;
