unordered_map<ll, ll> dp[51][51];

int n, k, s, t;
int a[N + 5];

ll solve(int idx, int pk, ll btand, ll btsisa) {
	if(pk > k) return 0;
	if(idx == n + 1) {
		if(btand != s || (btand | btsisa) != t) return 0;
		return 1;
	}
	if(dp[idx][pk].find((btand << 18) + btsisa) != dp[idx][pk].end()) return dp[idx][pk][(btand << 18) + btsisa];
	ll res = 0;
	//pick
	if(pk == 0) res += solve(idx + 1, pk + 1, a[idx], a[idx]);
	else {
		int bvalsisa = (btsisa | btand | a[idx]);
		int bvaland = (btand & a[idx]);
		res += solve(idx + 1, pk + 1, bvaland, (bvaland ^ bvalsisa));
	}
	//not pick
	res += solve(idx + 1, pk, btand, btsisa);
//	cout<<"AT "<<idx<<" "<<pk<<" "<<btand<<" "<<btsisa<<" "<<res<<endl;
	return dp[idx][pk][(btand << 18) + btsisa] = res;
}

