void precalc() {
    for (int i = 0; i < N; i++) {
        binom[i][0] = binom[i][i] = 1;
        for (int j = 1; j < i; j++) {
            binom[i][j] = binom[i - 1][j - 1] + binom[i - 1][j];
        }
    }
    for (int i = 0; i < N; i++)
        for (int j = 1; j < N; j++)
            binom[i][j] += binom[i][j - 1];
}

bool le(int l, int r) {
    return (l & r) == l;
}

