        if (!le(S, I))
            continue;
        for (int J = I; J <= T; J = (J + 1) | I) {
            if (!le(J, T))
                continue;
            int tmp = cnt_bit[I ^ S] + cnt_bit[J ^ T];
            int cnt = subs[J] - subs[I] + cn[I];
            if (!cnt)
                continue;
            int lc = 1;
            int rc = min(cnt, k);
            ll tot = binom[cnt][rc] - binom[cnt][lc - 1];
            if (tmp % 2 == 0)
                res += tot;
            else
                res -= tot;
        }
    }

    for (int I = S; I <= T && I <= 0; I++) {
        if (!le(S, I))
            continue;
        for (int J = I; J <= T; J = (J + 1) | I) {
            if (!le(J, T))
                continue;
            int tmp = cnt_bit[I ^ S] + cnt_bit[J ^ T];
            int cnt = subs[J] - subs[I] + cn[I];
            int rc = min(cnt, k);
            ll tot = binom[cnt][rc];
            if (tmp % 2 == 0)
                res += tot;
            else
                res -= tot;
        }
    }

    cout << res << "\n";

    return 0;
}

