        for(int j=1; j<=i; j++) comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
    }

    uint64_t sub[51] = {0};
    for(int i=0; i<=N; i++) for(int j=1; j<=K; j++) sub[i] += comb[i][j];

    uint64_t ans = 0;
    for(int b=T; ; b=(b-1)&T){
        uint64_t res = 0;
        for(int d=b; ; d=(d-1)&b){
            int c = b-d;
            int cnt = 0;
            for(int a : A) if((a&c) == 0 && (a&d) == d) cnt++;
            res += sub[cnt];
            if(d == 0) break;
        }
        if(pop_count(b)%2) res *= -1;
        ans += res;
        if(b == 0) break;
    }

    cout << ans << endl;
    return 0;
}

