long long ans;
void dfs(int x)
{
	if(cnt == k || x == top + 1)
	{
		int tt = 0;
		int ts = (1 << 18) - 1;
		for(int i = 1; i <= top; ++i)
		{
			if(flag[i])
			{
				ts &= sta[i];
				tt |= sta[i];
			}
		}
		if(ts == s && tt == t)
			++ans;
		return ;
	}
	flag[x] = 1;
	++cnt;
	dfs(x + 1);
	flag[x] = 0;
	--cnt;
	dfs(x + 1);
	return ;
}

