    while (now > 0) {
        s2[idx++] = now & 1;
        now >>= 1;
    }
    now = t;
    idx = 0;
    while (now > 0) {
        t2[idx++] = now & 1;
        now >>= 1;
    }
    vint kind(18, 0);
    int numkind1 = 0, numkind0 = 0, numkind2 = 0;
    REP(i, 18) {
        if (s2[i] == 1 && t2[i] == 0) {
            cout << 0 << endl;
            return 0;
        } else if (s2[i] == 0 && t2[i] == 0) {
            kind[i] = 0;
            ++numkind0;
        } else if (s2[i] == 1 && t2[i] == 1) {
            kind[i] = 1;
            ++numkind1;
        } else {
            kind[i] = 2;
            ++numkind2;
        }
    }
    unordered_map<int, int> idxs0, idxs1;
    REP(i, 18) {
        REP(j, n) {
            if (kind[i] == 0) {
                if (a2[j][i] == 0) {
                    idxs0[j]++;
                }
            } else if (kind[i] == 1) {
                if (a2[j][i] == 1) {
                    idxs1[j]++;
                }
            }
        }
    }
    vint idxs;
    REP(i, n) {
        if (!(idxs0[i] == 0 && idxs1[i] == 0)) {
            if (numkind0 == idxs0[i] && numkind1 == idxs1[i]) {
                idxs.push_back(i);
            }
        }
    }
    if (numkind2 == 0){
        cout << pow(2, idxs.size()) - 1 << endl;
        return 0;
    }
    int sz = idxs.size(), ans = 0;
    for (int i = 0; i < (1 << sz); ++i){
        bool flag = true;
        REP(j, 18) {
