                int zeronum = 0, onenum = 0;
                REP(k, sz) {
                    if (i & (1 << k)){
                        if (a2[idxs[k]][j] == 1){
                            ++onenum;
                        }else{
                            ++zeronum;
                        }
                    }
                }
                if (onenum == 0 || zeronum == 0) {
                    flag = false;
                }
            }
        }
        //cout << i << " " << flag << endl;
        if (flag) {
            ++ans;
        }
    }
    cout << ans << endl;
