//int N, M, K, H, W, L, R;
long long int N, M, K, H, W, L, R;


int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> K;
	cin >> L >> R;
	if ((R&L) != L) {
		cout << 0 << endl;
		return 0;
	}
	vector<int>v;
	for (int i = 0; i < N; i++) {
		cin >> M;
		if ((L&M) != L)continue;
		if ((R | M) != R)continue;
		v.push_back(M);
	}
	R -= L;
	L = 0;
	for (auto &i : v)i -= L;
	vector<vector<int>>binom(N + 1, vector<int>(N + 1, 0));
	for (int i = 1; i <= N; i++) {
		binom[i][1] = i;
	}
	for (int i = 2; i <= N; i++) {
		for (int j = 2; j <= i; j++) {
			binom[i][j] += binom[i - 1][j] + binom[i - 1][j - 1];
			binom[i][j] %= MOD;
		}
	}
	for (int i = 1; i <= N; i++) {
		for (int j = 2; j <= K; j++) {
			binom[i][j] += binom[i][j - 1];
			binom[i][j] %= MOD;
		}
	}
	int ans = 0;
	ans+=binom[v.size()][K];
	for (int i = 1; i < (1 << 18); i++) {
		if ((i&R) != i)continue;
		map<int, int>mp;
		for (auto j : v) {
			mp[j&i]++;
		}
		int box = i;
		int num = 0;
		while (box) {
			num += box & 1;
			box >>= 1;
		}
		for (auto j : mp) {
		//	cout << i << " " << j.first << " " << j.second << endl;
			if (num & 1) {
				ans += MOD - binom[j.second][K];
				ans %= MOD;
			}
			else {
				ans += binom[j.second][K];
				ans %= MOD;
			}
		}
	}
	cout << ans << endl;
}

