constexpr int C{18};

ll comb(ll n, ll k)
{
  ll ans{1};
  for (auto i{0LL}; i < k; ++i)
  {
    ans *= n - i;
    ans /= i + 1;
  }
  return ans;
}

class Solve
{
  int N, S, T;
  int M;
  ll K;
  vector<int> A;

public:
  Solve(int N) : N{N}, A(N)
  {
    cin >> K >> S >> T;
    for (auto i{0}; i < N; ++i)
    {
      cin >> A[i];
    }
#if DEBUG == 1
    cerr << "N = " << N << endl;
    for (auto i{0}; i < N; ++i)
    {
      cerr << "A[" << i << "] = " << A[i] << endl;
    }
#endif
    normalize();
#if DEBUG == 1
    cerr << "N = " << N << endl;
    for (auto i{0}; i < N; ++i)
    {
      cerr << "A[" << i << "] = " << A[i] << endl;
    }
    cerr << "M = " << M << endl;
#endif
  }

  void flush()
  {
    ll ans{0};
    for (auto mask{0}; mask < 1 << M; ++mask)
    {
      if (popcount(mask) & 1)
      {
        ans -= calc(mask);
      }
      else
      {
        ans += calc(mask);
      }
    }
    cout << ans << endl;
  }

private:
  ll calc(int mask)
  {
    map<int, ll> X;
    for (auto i{0}; i < N; ++i)
    {
      int tmp{A[i] & mask};
      X[tmp];
      X[tmp]++;
    }
    ll ans{1};
    for (auto [mask, cnt] : X)
    {
      for (auto i{1}; i <= min(K, cnt); ++i)
      {
        ans += comb(cnt, i);
      }
    }
    return ans;
  }

  void normalize()
  {
    vector<bool> ok(N, true);
    for (auto i{0}; i < C; ++i)
    {
      auto s{static_cast<bool>(S >> i & 1)};
      auto t{static_cast<bool>(T >> i & 1)};
      if (s && !t)
      {
        No();
      }
      if (s ^ !t)
      {
        for (auto j{0}; j < N; ++j)
        {
          if ((A[j] >> i & 1) != static_cast<int>(s))
          {
            ok[j] = false;
          }
        }
      }
    }
    vector<int> B;
#if DEBUG == 1
    cerr << "B.size() = " << B.size() << endl;
#endif
    for (auto i{0}; i < N; ++i)
    {
      if (ok[i])
      {
        B.push_back(A[i]);
      }
    }
#if DEBUG == 1
    cerr << "B.size() = " << B.size() << endl;
#endif
    swap(A, B);
    N = static_cast<int>(A.size());
    int k{0};
    B = vector<int>(N, 0);
    for (auto i{0}; i < C; ++i)
    {
      auto s{static_cast<bool>(S >> i & 1)};
      auto t{static_cast<bool>(T >> i & 1)};
      if (!(!s && t))
      {
        continue;
      }
      for (auto j{0}; j < N; ++j)
      {
        B[j] |= (A[j] >> i & 1) << k;
      }
      ++k;
    }
    swap(A, B);
    M = k;
  }
};

