			rep(j, k + 1) rep(mask, all) {
				if(dp[i % 2][j][mask] == 0) continue;
				dp[(i + 1) % 2][j][mask] += dp[i % 2][j][mask];
				const int nmask = mask | (a[f] ^ a[i]);
				dp[(i + 1) % 2][j + 1][nmask] += dp[i % 2][j][mask];
			}
		}
		rep(j, 1, k + 1) ans += dp[n % 2][j][fmask];
	}

	cout << ans << endl;

	return 0;
}

