const int N = 55;
const int LOG = 18;
const int X = 1 << LOG;

int n, k;
int a[N], b[N], sz;
int S, T;
ll dp[N][X];
ll binom[N][N];
int subs[X], cn[X];
int cnt_bit[X];

void precalc() {
    for (int i = 0; i < N; i++) {
        binom[i][0] = binom[i][i] = 1;
        for (int j = 1; j < i; j++) {
            binom[i][j] = binom[i - 1][j - 1] + binom[i - 1][j];
        }
    }
    for (int i = 0; i < N; i++)
        for (int j = 1; j < N; j++)
            binom[i][j] += binom[i][j - 1];

    for (int mask = 0; mask < X; mask++) {
        cnt_bit[mask] = __builtin_popcount(mask);
    }
}

bool le(int l, int r) {
    return (l & r) == l;
}

int main() {

    precalc();

#ifdef DEBUG
    freopen("input.txt", "r", stdin);
#endif

    ios_base::sync_with_stdio(0);
    cin.tie(0);

    cin >> n >> k >> S >> T;

    for (int i = 0; i < n; i++) {
        cin >> a[i];
        cn[a[i]]++;
    }

    for (int sub = 0; sub <= T; sub++) {
        for (int mask = sub; mask <= T; mask = (mask + 1) | sub) {
            subs[mask] += cn[sub];
        }
    }

    ll res = 0;

    for (int I = 0; I <= T; I++) {
        if (!le(S, I))
            continue;
        for (int J = I; J <= T; J = (J + 1) | I) {
            if (!le(J, T))
                continue;
            int tmp = cnt_bit[I ^ S] + cnt_bit[J ^ T];
            int cnt = subs[J] - subs[I] + cn[I];
            int lc = I == 0 ? 0 : 1;
            int rc = min(cnt, k);
            ll tot = 0;
            if (lc <= rc)
                tot = binom[cnt][rc] - (lc ? binom[cnt][lc - 1] : 0);
            if (tmp % 2 == 0)
                res += tot;
            else
                res -= tot;
        }
    }


    cout << res << "\n";

    return 0;
}

