inline ll cmb(int n, int k) {
  if(k < 0 || n < k) return 0;
  return CMB[n][k];
}

// 1以上k以下のsum
inline ll cmbsum(int n, int k) {
  if(k <= 0) return 0;
  return CMBSUM[n][min(k, n)];
}

ll mypow(ll x, int n) {
  if(n == 0) return 1;
  if(x % 2 == 0) return mypow(x*x, n/2);
  return x * mypow(x*x, n/2);
}

vector<int> vs;
ll solve(int N, int K, int S, int T) {
  if((S & T) != S || (S | T) != T) {
    return 0;
  }
  ll cur = 0;
  int ST = T^S;
  for(int pat1 = ST; ; pat1 = (pat1-1) & ST) {
    vector<int> vs2;
    REP(i, N) {
      if((vs[i] & pat1) == 0) {
        vs2.push_back(vs[i]);
      }
    }
    int stpat1 = ST^pat1;
    for(int pat2 = stpat1; ; pat2 = (pat2-1) & stpat1) {
      int pat = pat1 | pat2;
      if(pat == 0) {
        break;
      }
      int parity = 0;
      REP(i, 18) {
        if(pat & (1 << i)) {
          parity ^= 1;
        }
      }
      int cnt = 0;
      REP(i, vs2.size()) {
        if((vs2[i] & pat2) == pat2) {
          ++cnt;
        }
      }
      ll hoge = cmbsum(cnt, K);
      if(parity) {
        cur += hoge;
      } else {
        cur -= hoge;
      }
      if(pat2 == 0) {
        break;
      }
    }
    if(pat1 == 0) {
      break;
    }
  }
  ll res = cmbsum(N, K) - cur;
  return res;
}

int main(void) {
  REP(i, 51) {
    CMB[i][0] = 1;
    for(int j = 1; j <= i; ++j) {
      CMB[i][j] = CMB[i-1][j-1] + CMB[i-1][j];
      CMBSUM[i][j] = CMBSUM[i][j-1] + CMB[i][j];
    }
  }

  int N, K, S, T;
  scanf("%d%d%d%d", &N, &K, &S, &T);
  REP(i, N) {
    int v;
    scanf("%d", &v);
    if((v & S) == S && (v | T) == T) { // Sが必須かつ、Tの中に収まる必要がある
      vs.push_back(v);
    }
  }
  N = vs.size();
  ll res = 0;
  res = solve(N, K, S, T);
  cout << res << endl;

  return 0;
}

