    ll bits_len=SIZE(bits);

    //集合分割したのでさらに分割を行う(部分集合全列挙したいのでbit全探索)
    //余事象が何通りあるかをans_subに格納
    ll ans_sub=0;

    //ここで答えでの組み合わせの前計算しておく
    //prior_calc[i][j]：iC1+iC2+…+iCjの答え(i:1~n,j:1~k)
    //0-indexed
    vector<vector<ll>> pcalc(n+1,vector<ll>(k+1,0));
    pcalc[0][0]=1;
    FOR(i,1,n){
        pcalc[i][0]=1;
        FOR(j,1,k){
            pcalc[i][j]=pcalc[i-1][j-1]+pcalc[i-1][j];
        }
    }
    REP(i,n+1){
        pcalc[i][0]=0;
        REP(j,k){
            pcalc[i][j+1]+=pcalc[i][j];
        }
    }

    //bit全探索でありうる積集合のパターンを全て考える
    //2^L
    //all_setsにはそこまでで分けられた集合を集合ごとに保存(bitでどの要素が含まれるか表す)
    deque<ll> all_sets;
    FOR(i,1,(1<<bits_len)-1){
        //まず全ての要素が同じ集合に含まれているものとする
        all_sets.PB((1<<n)-1);
        //L
        //包除原理において、積集合で考える集合の個数の偶奇が知りたいので
        ll odd_even=0;
        REP(j,bits_len){
            //そのbitを積集合を考えるbitとして考慮に入れる時
            if((i>>j)&1){
                odd_even+=1;
                ll s=SIZE(all_sets);
                //n
                //今分けられている集合それぞれをさらに(そのbitが0か1かで)分割する
                REP(_,s){
                    //積集合をとりたい集合を書き出す
                    ll ins=*(all_sets.begin());
                    all_sets.pop_front();
                    //insはf1とf2へと分割される
                    ll f1=ins&(bits[j].F);ll f2=ins&(bits[j].S);
                    //f1,f2が0の時は空集合なので0通りより無視
                    if(f1){all_sets.PB(f1);}
                    if(f2){all_sets.PB(f2);}
                }
            }
        }
        //積集合のパターンを決めた下で完全に集合を分割できた
        //それぞれの集合に対して1以上K以下の数を選ぶ(pcalcを使う)
        ll s=SIZE(all_sets);
        //n
        REP(_,s){
            ll now=*(all_sets.begin());
            all_sets.pop_front();
            //立ってるbit数を数える(注目する集合の要素数を数える)
            ll s_sub=__builtin_popcountll(now);
            //前計算で求めたpcalcから求める
            //ここで、包除原理より+-が決まる
            if(odd_even%2){
                ans_sub+=pcalc[s_sub][min(k,s_sub)];
            }else{
                ans_sub-=pcalc[s_sub][min(k,s_sub)];
            }
        }
    }
    //ans_subは余事象のパターン数で、全体のパターン数からその余事象のパターン数を引く
    cout<< pcalc[n][k]-ans_sub <<endl;
}

#include <bits/stdc++.h>

using namespace std;

long long mod = 998244353;
int MAX = 60;

long long binary_expo (long long a, long long p) {
  long long res = 1;
  while (p) {
    if (p & 1) (res *= a) %= mod;
    (a *= a) %= mod;
    p >>= 1;
  }
  return res;
}

long long inv (long long a) {
  return binary_expo(a, mod - 2);
}

vector<long long> fc(MAX), infc(MAX);

void init () {
  fc[0] = infc[0] = 1;
  for (int i = 1; i < MAX; i++) {
    fc[i] = (fc[i - 1] * i) % mod;
    infc[i] = inv(fc[i]);
  }
}

inline long long nck (int n, int k) {
  if (n < k) return 0;
  long long res = (fc[n] * infc[n - k]) % mod;
  (res *= infc[k]) %= mod;
  return res;
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
  init();
  int n, k, s, t;
  cin >> n >> k >> s >> t;
  vector<int> old_a(n);
  for (int i = 0; i < n; i++) {
    cin >> old_a[i];
  }
  vector<int> a;
  for (int i = 0; i < n; i++) {
    if ((old_a[i] & s) != s || (old_a[i] & t) != old_a[i]) continue;
    a.push_back(old_a[i]);
  }
  n = a.size();
  for (int i = 0; i < n; i++) {
    int num = 0;
    for (int j = 17; j >= 0; j--) {
      if ((s & (1 << j)) || !(t & (1 << j))) continue;
      num <<= 1;
      if (a[i] & (1 << j)) num += 1;
    }
    a[i] = num;
  }
  int mbit = 0;
  for (int i = 0; i < 18; i++) {
    if ((s & (1 << i)) || !(t & (1 << i))) continue;
    mbit++;
  }
  int sz = 1;
  for (int i = 0; i < mbit; i++) sz *= 3;
  vector<int> classes(sz, 0);
  for (int i = 0; i < (1 << mbit); i++) {
    for (int j = 0; j < n; j++) {
      int eval = 0;
      int count = 0;
      for (int k = 0; k < mbit; k++) {
        eval *= 3;
        if (i & (1 << k)) {
          if (a[j] & (1 << k)) eval += 1;
        } else {
          eval += 2;
          count++;
        }
      }
      if (count & 1)
        classes[eval]--;
      else classes[eval]++;
    }
  }
  vector<int> app(n + 1, 0);
  long long ans = 0;
  for (int j = 1; j <= k; j++) {
    (ans += nck(n, j)) %= mod;
  }
  for (int i = 0; i < sz - 1; i++) {
    if (classes[i] < 0) app[-classes[i]]--;
    else app[classes[i]]++;
  }
  for (int i = 1; i <= n; i++) {
    long long cur = 0;
    for (int j = 1; j <= k; j++) {
      cur += nck(i, j);
      if (cur >= mod) cur -= mod;
    }
    (cur *= app[i]) %= mod;
    if (cur < 0) cur += mod;
    ans += cur;
    if (ans >= mod) ans -= mod;
  }
  cout << ans << '\n';
  return 0;
}

