long long comb(long long n, long long r) {
    static vector<vector<ll>> memo(51, vector<ll>(51, -1));
    long long r_new = (r <= n/2) ? r : n-r;
    if (r_new < 0) return 0;
    if (r_new == 0) return 1;
    if (memo.at(n).at(r) != -1) return memo.at(n).at(r);
    else return memo.at(n).at(r) = (n-r_new+1) * comb(n, r_new-1) / r_new;
}

void solve() {
    int n, k, s, t;
    cin >> n >> k >> s >> t;
    vector<int> a(n);
    for (int i=0; i<n; ++i) cin >> a.at(i);

    vector<int> free;
    for (int i=0; i<18; ++i) {
        int ss = s & (1<<i), tt = t & (1<<i);
        if (ss && !tt) {
            cout << 0 << '\n';
            return;
        }
        if (!ss && tt) {
            free.push_back(i);
            continue;
        }
        for (int j=0; j<n; ++j) {
            if ((a.at(j) & (1<<i)) != ss) {
                a.erase(a.begin()+j);
                --j;
                --n;
            }
        }
    }

    int d = (int)free.size();
    for (int i=0; i<n; ++i) {
        int tmp = 0;
        for (int j=0; j<d; ++j) if (a.at(i) & (1<<free.at(j))) tmp += (1<<j);
        a.at(i) = tmp;
    }

    ll res = 0;
    for (int bits=0; bits<(1<<d); ++bits) {
        int cnt = 0;
        for (int i=0; i<d; ++i) if (bits & (1<<i)) ++cnt;
        map<int, int> mp;
        for (int i=0; i<n; ++i) ++mp[bits & a.at(i)];
        ll sum = 0;
        for (auto p : mp) for (int i=1; i<=min(k, p.second); ++i) sum += comb(p.second, i);
        if (cnt%2 == 0) res += sum;
        else res -= sum;
    }
    cout << res << '\n';
}

