// x includes y
// y is in x
bool includes(ll x, ll y) {
  return ((x & y) == y) != 0;
}

ll del(ll x, int z) {
  return
    (x & ((1ll << z) - 1)) |
    ((x >> (z + 1)) << z);
}

bool getbit(ll x, int z) {
  return !!(x & (1ll << z));
}

auto rekkyo(vector<ll> a) {
  int n = a.size();
  vector<vector<pair<ll, ll>>> res(a.size() + 1);
  for(int i = 0; i < (1 << n); i++) {
    int cnt = 0;
    ll vAND = (1ll << D) - 1;
    ll vOR = 0;
    for(int j = 0; j < n; j++) {
      if((i >> j) & 1) {
        cnt++;
        vAND &= a[j];
        vOR |= a[j];
      }
    }
    res[cnt].emplace_back(vAND, vOR);
  }
  return res;
}

using P = pair<int, ll>;
vector<P> mrg(vector<P> a, vector<P> b) {
  vector<P> r;
  int ai = 0, bi = 0;
  while(ai < a.size() || bi < b.size()) {
    bool chooseA = 0;
    if(ai == a.size()) chooseA = 0;
    else if(bi == b.size()) chooseA = 1;
    else if(a[ai] < b[bi]) chooseA = 1;
    else chooseA = 0;
    if(chooseA) {
      r.push_back(a[ai]);
      ai++;
    } else {
      r.push_back(b[bi]);
      bi++;
    }
  }
  return r;
}

// fzt {{{
// n is power of 2
vector<vector<P>> fzt(vector<vector<P>> a) {
  int n = a.size();
  for(int i = 1; i < n; i <<= 1)
    for(int j = 0; j < n; j++)
      if((j & i) == 0) {
        // a[j] += a[j | i];
        a[j] = mrg(a[j], a[j | i]);
      }
  return a;
}
