int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  ll n, k, sOR, sAND;
  cin >> n >> k >> sAND >> sOR;
  dump(sAND, sOR);
  vector<ll> a0(n);
  for(int i = 0; i < n; i++) cin >> a0[i];
  vector<ll> a;
  if(!includes(sOR, sAND)) output(0);
  for(int i = 0; i < n; i++) {
    ll t = a0[i];
    dump(t, i);
    dump(includes(sOR, t), includes(t, sAND));
    if(includes(sOR, t) && includes(t, sAND)) {
      int j2 = 0;
      for(int j = 0; j < 18; j++) {
        if(getbit(sOR, j) == 0 || getbit(sAND, j) == 1) {
          t = del(t, j2);
        } else j2++;
      }
      a.push_back(t);
    }
  }
  {
    int j2 = 0;
    for(int j = 0; j < 18; j++) {
      if(getbit(sOR, j2) == 0 || getbit(sAND, j2) == 1) {
        sOR = del(sOR, j2);
        sAND = del(sAND, j2);
        D--;
      } else j2++;
    }
  }
  n = a.size();
  if(n == 0) output(0);
  dump(n, a);

  vector<ll> b;
  for(int i = 0; i < n / 2; i++) {
    b.push_back(a.back());
    a.pop_back();
  }
  dump(D, a, b);
  // (and, or)
  auto ra = rekkyo(a);
  auto rb = rekkyo(b);

  vector<vector<P>> f(1 << D);
  for(int i = 0; i < k; i++) {
    for(auto rbx: rb[i]) {
      auto &it = f[rbx.second];
      P p(i, rbx.first);
      it.insert(lower_bound(it.begin(), it.end(), p), p);
    }
  }

  auto t = fzt(f);
  dump(ra);
  dump(rb);
  dump(t);
  dump(sAND, sOR);

  ll ans = 0;
  for(int i = 0; i <= k; i++) {
    for(auto&rax: ra[i]) {
      auto [tAND, tOR] = rax;
      auto tORrev = tOR ^ ((1ll << D) - 1);
      dump(tORrev);
      auto & it = t[tORrev];
      for(int j = 0; j < it.size() && it[j].first <= k - i; j++) {
        dump(it[j].second, tAND);
        if((it[j].second & tAND) == sAND) {
          ans++;
        }
      }
    }
  }

  output(ans);
  return 0;
}

