int A[maxN], vis[maxN], as[maxB];
ll C[maxN][maxN], ans;
map<int, int> M;

void init(){
	int i, j;
	for(i = 0; i < maxN; ++i){
		C[i][0] = C[i][i] = 1;
		for(j = 1; j < i; ++j)
			C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
	}
	for(i = 0; i < maxN; ++i){
		for(j = 1; j < maxN; ++j)
			C[i][j] += C[i][j - 1];
	}
}

int main (){
	int n, k, S, T, i, j, c = 0, b;
	scanf("%d%d%d%d", &n, &k, &S, &T);
	for(init(), i = 0; i < n; ++i) scanf("%d", A + i);
	for(i = 0; i < maxB; ++i){
		b = 1 << i;
		if(S & b){
			if(T & b) { for(j = 0; j < n; ++j) if(!(A[j] & b)) vis[j] = 1; }
			else { puts("0"); return 0; }
		}
		else{
			if(T & b) as[c++] = i;
			else { for(j = 0; j < n; ++j) if(A[j] & b) vis[j] = 1; }
		}
	}
	for(i = j = 0; i < n; ++i) if(!vis[i]) A[j++] = A[i]; n = j;
	for(b = 0; b < (1 << c); ++b){
		int sgn = __builtin_popcount(b) & 1, s = 0;
		for(i = 0; i < c; ++i) if(b & (1 << i)) s |= (1 << as[i]);
