const int MAXN = 52;
LL binom[MAXN][MAXN];
LL pref_bin[MAXN];
int Z;
vector<ULL> splittings;
vector<ULL> antisplittings;

LL res = 0;

void dfs(ULL curr, int pos, bool parity) {
    if (curr == 0) return;
    if (pos == Z) {
        if (parity) res -= pref_bin[__builtin_popcountll(curr)];
        else res += pref_bin[__builtin_popcountll(curr)];
        return;
    }
    dfs(curr, pos+1, parity);
    dfs(curr&splittings[pos], pos+1, !parity);
    dfs(curr&antisplittings[pos], pos+1, !parity);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0); // Remove in problems with online queries!

    for (int n = 0; n < MAXN; n++) {
        binom[n][0] = 1;
        for (int m = 1; m <= n; m++) binom[n][m] = binom[n-1][m-1] + binom[n-1][m];
    }


    int N, K, S, T;
