        ULL bb = 0;
        for (int j = 0; j < N; j++) if (A[j]&pot) bb ^= 1ll<<j;
        splittings.push_back(bb);
        antisplittings.push_back(~bb);
    }

    for (int n = 0; n <= N; n++) {
        for (int i = 1; i <= K; i++) pref_bin[n] += binom[n][i];
    }

