    long long ans = 0;
    for (int mask = 0; mask < (1<<K); mask++) {
        if ((S&mask) != S || (T&mask) != mask)  continue;

        vector<int> vv;
        for (int i=0; i<n; i++)
            if ((S&mask) == S && (T&mask) == mask) {
                int z = v[i] & (~mask);
