{
    constexpr int B         = 18;
    const auto [N, K, S, T] = in.tup<int, int, uint, uint>();
    const auto as           = in.vec<uint>(N);
    if ((S & T) != S) { return out.ln(0); }
    std::vector<uint> bs;
    for (int i = 0; i < N; i++) {
        if (((as[i] & T) == as[i]) and ((as[i] & S) == S)) { bs.push_back(as[i]); }
    }
    SHOW(bs);
    const int M = bs.size();

    auto prec  = make_v<ll>({M + 1, K + 1}, 0);
    prec[0][0] = 1;
    for (int i = 0; i < M; i++) {
        for (int k = 0; k < K; k++) { prec[i + 1][k + 1] += prec[i][k]; }
        for (int k = 0; k <= K; k++) { prec[i + 1][k] += prec[i][k]; }
    }
    for (int i = 0; i <= M; i++) {
        for (int k = 1; k <= K; k++) { prec[i][k] += prec[i][k - 1]; }
    }
    auto xors = make_v<ll>({M, 1 << B}, 0);
    for (int i = 0; i < M; i++) {
        for (int j = i + 1; j < M; j++) { xors[i][bs[i] ^ bs[j]]++; }
        bfft<ll>::fzt(xors[i], false);
    }
    auto dp = std::vector<ll>(1 << B, 0);
    for (uint m = 0; m < (1 << B); m++) {  // 違反集合
        bool ng = false;
        for (int b = 0; b < B; b++) {
            if (btest(m, b)) {
                if (btest(S, b) == 1 or btest(T, b) == 0) { ng = true; }
            }
        }
        if (ng) { continue; }
        const uint cm = ((1 << B) - 1) - m;
        for (int i = 0; i < M; i++) {
            const int num = xors[i][cm];
            dp[m] += prec[num][K - 1];
        }
    }
    //    SHOW(dp);
    ll ans = 0;
    for (int m = 0; m < (1 << B); m++) { ans += (popcount(m) % 2 == 0 ? 1LL : -1LL) * dp[m]; }
    out.ln(ans);
    return 0;
}

