typedef uint32_t u32;
typedef int64_t s64;

struct Comb {
	std::vector<std::vector<s64> > a;
	Comb(int n) { // O(n^2)
		a.resize(n+1);
		for (int i = 0; i <= n; i++) {
			a[i].resize(i+1, 1);
			for (int j = 1; j < i; j++) a[i][j] = a[i-1][j] + a[i-1][j - 1];
		}
	}
	s64 ncr(int n, int r) {
		assert(n >= 0);
		assert(n <= (int)a.size());
		assert(r >= 0);
		assert(r <= n);
		return a[n][r];
	}
};

int64_t fast(int m, int k, const std::vector<int> &revised) {
	int n = revised.size();
	assert(n);
	Comb com(n + 1);
	int64_t ncrsum[n + 1][n + 1];
	for (int i = 0; i <= n; i++) {
		ncrsum[i][0] = com.ncr(i, 0);
		for (int j = 1; j <= i; j++) ncrsum[i][j] = ncrsum[i][j - 1] + com.ncr(i, j);
		for (int j = i; j < n; j++) ncrsum[i][j + 1] = ncrsum[i][j];
	}
	int64_t res = 0;
	for (int i = 0; i < 1 << m; i++) {
		std::map<int, int> ma;
		for (auto j : revised) ma[j & i]++;
		int64_t cur = 0;
		for (auto j : ma) cur += ncrsum[j.second][k] - 1;
		if (__builtin_popcount(i) & 1) res -= cur;
		else res += cur;
	}
	return res;
}
