using i64 = long long;

namespace _buff {

const size_t BUFF = 1 << 19;
char ibuf[BUFF], *ib = ibuf, *ie = ibuf;
char getc() {
    if (ib == ie) {
        ib = ibuf;
        ie = ibuf + fread(ibuf, 1, BUFF, stdin);
    }
    return ib == ie ? -1 : *ib++;
}

}

i64 read() {
    using namespace _buff;
    i64 ret = 0;
    bool pos = true;
    char c = getc();
    for (; (c < '0' || c > '9') && c != '-'; c = getc()) {
        assert(~c);
    }
    if (c == '-') {
        pos = false;
        c = getc();
    }
    for (; c >= '0' && c <= '9'; c = getc()) {
        ret = (ret << 3) + (ret << 1) + (c ^ 48);
    }
    return pos ? ret : -ret;
}

int main() {
    int n = read(), k = read();
    vector<vector<int>> c(n + 1, vector<int>(n + 1));
    for (int i = 0; i <= n; ++i) {
        c[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            c[i][j] = c[i - 1][j - 1] + c[i - 1][j];
        }
    }
    vector<int> coef(n + 1);
    for (int i = 0; i <= n; ++i) {
        coef[i] = accumulate(begin(c[i]) + 1, begin(c[i]) + k + 1, 0LL);
    }


    int s = read(), t = read();
    if ((s & t) != s) {
        return puts("0"), 0;
    }
    vector<int> dig, pw;
    for (int x = s ^ t, y = 1, i = 0; x; ++i, x >>= 1) {
        pw.emplace_back(y); y *= 3;
        if (x & 1) dig.emplace_back(i);
    }
    unordered_map<int, int> mp;
    mp.reserve(8192); mp.max_load_factor(0.25f);
    while (n--) {
        int x = read();
        if ((x & s) == s && (x | t) == t) {
            vector<int> sum(1 << dig.size());
            int cur = 0;
            for (int i = 0; i < (int) dig.size(); ++i) {
                int d = dig[i];
                cur += (x >> d & 1) * pw[i];
                sum[1 << i] = (2 - (x >> d & 1)) * pw[i];
            }
            for (int i = 0, _ = 1 << dig.size(); i <_; ++i) {
                sum[i] = sum[i & -i] + sum[i ^ (i & -i)];
                ++mp[sum[i] + cur];
            }
        }
    }

    i64 ans = 0;
    for (auto &pr : mp) {
        int i = pr.first, c = pr.second;
        int cnt = dig.size();
        for (int j = i; j; j /= 3) {
            cnt -= j % 3 == 2;
        }
        ans += coef[c] * (cnt & 1 ? -1 : 1);
    }
    cout << ans;
    return 0;
}

