        C[i][0] = 1;
        for (int j = 1; j <= i; j++) C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
    }
    for (int i = 1; i <= 50; i++)
        for (int j = 1; j <= i; j++) C[i][j] += C[i][j - 1];

