            if (s == t && x != s) {
                swap(a[i], a[n]);
                n--;
            }
        }
    }
    int bc = 0;
    for (int bit = 0; bit < 18; bit++) {
        int s = (S >> bit & 1), t = (T >> bit & 1);
        if (s == 0 && t == 1) {
            for (int i = 1; i <= n; i++) b[i] |= (a[i] >> bit & 1) * (1 << bc);
            bc++;
        }
    }
    ll ans = 0;
    vector<int>vec;
    for (int s = 0; s < (1 << bc); s++) {
        vec.clear();
        for (int i = 1; i <= n; i++) {
            if (!cnt[s & b[i]]) vec.push_back(s & b[i]);
            cnt[s & b[i]]++;
        }
        for (int x : vec) {
            dp[s] += C[cnt[x]][min(cnt[x], k)] - 1;
            cnt[x] = 0;
        }
        __builtin_popcount(s) & 1 ? ans -= dp[s] : ans += dp[s];
    }
    printf("%lld\n", ans);
    return 0;
}

