typedef uint32_t u32;
typedef int64_t s64;

struct Comb {
	std::vector<std::vector<s64> > a;
	Comb(int n) { // O(n^2)
		a.resize(n+1);
		for (int i = 0; i <= n; i++) {
			a[i].resize(i+1, 1);
			for (int j = 1; j < i; j++) a[i][j] = a[i-1][j] + a[i-1][j];
		}
	}
	s64 ncr(int n, int r) {
		assert(n >= 0);
		assert(n <= (int)a.size());
		assert(r >= 0);
		assert(r <= n);
		return a[n][r];
	}
};

int main() {
	int n = ri(), k = ri();
	Comb com(n + 1);
	int ncrsum[n + 1][n + 1];
	for (int i = 0; i <= n; i++) {
		ncrsum[i][0] = com.ncr(i, 0);
		for (int j = 1; j <= i; j++) ncrsum[i][j] = ncrsum[i][j - 1] + com.ncr(i, j);
		for (int j = i; j < n; j++) ncrsum[i][j + 1] = ncrsum[i][j];
	}

	u32 s = ri(); // and
	u32 t = ri(); // or
	if ((s & t) != s) {
		puts("0");
		return 0;
	}
	u32 a[n];
	for (auto &i : a) i = ri();

	u32 mask = ~s & t;
	std::vector<int> all;

	std::vector<int> revised;
	for (int i = 0; i < 18; i++) if (mask >> i & 1) all.push_back(i);
	int m = all.size();
	for (auto i : a) {
		if ((i & s) != s) continue;
		if (~t & i) continue;
		int cur = 0;
		for (int j = 0; j < (int) all.size(); j++) if (i >> all[j] & 1) cur |= 1 << j;
		revised.push_back(cur);
	}
	n = revised.size();
	int64_t res = 0;
	for (int i = 0; i < 1 << m; i++) {
		std::map<int, int> ma;
		for (auto j : revised) ma[j & i]++;
		int64_t cur = 0;
		for (auto j : ma) cur += ncrsum[j.second][k];
		if (__builtin_popcount(i) & 1) res -= cur;
		else res += cur;
	}
	printf("%" PRId64 "\n", res);
	return 0;
}

