                rep(j, K) each(k, DP[j]) {
                    DP[j + 1][{k.fi.fi | ~A[i], k.fi.se | A[i]}] += k.se;
                }
            }
            rep(i, K + 1) res += DP[i][{S, T}];
            cout << res << rt;
        }
    } else {
        if (__builtin_popcount(T) >= 9) {
            T = ~T;
            DP[0][{mx, mx}] = 1;
            rep(i, N) {
                if ((A[i] | S) != A[i]) continue;
                if ((~A[i] | T) != T) continue;
                rep(j, K) each(k, DP[j]) {
                    DP[j + 1][{k.fi.fi & A[i], k.fi.se & ~A[i]}] += k.se;
                }
            }
            rep(i, K + 1) res += DP[i][{S, T}];
            cout << res << rt;
        } else {
            DP[0][{mx, 0}] = 1;
            rep(i, N) {
                if ((A[i] | S) != A[i]) continue;
                if ((T | A[i]) != T) continue;
                dec(j, K - 1, 0) each(k, DP[j]) {
                    DP[j + 1][{k.fi.fi & A[i], k.fi.se | A[i]}] += k.se;
                }
            }
            rep(i, K + 1) res += DP[i][{S, T}];
            cout << res << rt;
        }
    }
}

