int kek[M], fbit[M], C[N][N], a[N], b[N], cur[N], calc[N];

signed main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  C[0][0] = 1;
  for (int i = 1; i <= 50; i++) {
    C[i][0] = 1;
    for (int j = 1; j <= i; j++) {
      C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
    }
  }
  int n, k, s, t;
  cin >> n >> k >> s >> t;
  if (!sub(s, t)) {
    cout << -1 << '\n';
