      b[tn++] = a[i];
    }
  }
  n = tn;
  vector<int> bts;
  for (int i = 0; i < 18; i++) {
    if (((s ^ t) >> i) & 1) {
      bts.pb(i);
    }
  }
  for (int i = 0; i < n; i++) {
    int vl = 0;
    for (int j = 0; j < SZ(bts); j++) {
      if ((b[i] >> bts[j]) & 1) {
        vl |= 1 << j;
      }
    }
    b[i] = vl;
  }
  int L = SZ(bts);
  int ans = 0;
  for (int mask = 1; mask < (1 << L); mask++) {
    for (int i = 0; i < L; i++) {
      if ((mask >> i) & 1) {
        fbit[mask] = i;
        break;
      }
    }
  }
  //0..k - 1
  for (int i = 0; i <= n; i++) {
    for (int j = 1; j < k; j++) {
      calc[i] += C[i][j];
    }
  }
  if (L == 0) {
    cout << calc[n] + C[n][k] << '\n';
    exit(0);  
  }
  kek[0] = (1ll << n) - 1;
  for (int fpos = 0; fpos < n; fpos++) {
    for (int j = 1; j < (1 << L); j++) {
      kek[j] = 0;
    }
    for (int i = fpos + 1; i < n; i++) {
      cur[i] = b[fpos] ^ b[i];
      for (int j = 0; j < L; j++) {
        if (!((cur[i] >> j) & 1)) {
          kek[1 << j] |= 1ll << i;
        } 
      }
    }
    int add = calc[n - fpos - 1];
    for (int mask = 1; mask < (1 << L); mask++) {
      kek[mask] = kek[mask ^ (1 << fbit[mask])] & kek[1 << fbit[mask]];
      if (__builtin_popcount(mask) & 1) {
        add -= calc[__builtin_popcountll(kek[mask])];
      } 
      else {
        add += calc[__builtin_popcountll(kek[mask])];
      }
    }
    ans += add;
  }
  cout << ans << '\n';
}

