				}
			}
			return true;
		};
		if (check() == true)b.push_back(a[i]);
	}
	Array ans(3, 0);
	REP(i, 1LL << c.size()) {
		ll mask = 0;
		REP(j, c.size())if (i & (1LL << j))mask ^= (1LL << c[j]);
		map<ll, ll> cnt;
		REP(j, b.size()) cnt[b[j] & mask]++;
		ll co = popcount3(i) % 2;
		for (auto [key, v] : cnt) {
			rep(j, 1, min(k, v) + 1)(ans[0] += MOD + comb.nCr(v, j) * (co == 0 ? 1 : -1)) %= MOD;
			rep(j, 1, min(k, v) + 1)(ans[1]+= mod + comb2.nCr(v, j) * (co == 0 ? 1 : -1)) %= mod;
		}
	}
	Array m = { MOD,mod,9007199254740997LL };
	cout << garner( ans,m) << "\n";


