ll dfs(const vi &a,const vi &lim,const vi& v,const int &k,int now = 0) {
    if(now == lim.size()) {
        if(v.size() <= k) return (1LL<<v.size())-1;
        else return comb[v.size()][k]-1;
    }
    ll ret = 0;
    vi l,r;
    for(int i : v) {
        if(a[i]>>lim[now]&1) l.pb(i);
        else r.pb(i);
    }
    ret += dfs(a,lim,l,k,now+1);
    ret += dfs(a,lim,r,k,now+1);
    return ret;
}

