void dfs(int v,int ss,int tt,int cc){
	if(tt>t || cc>k){
		return;
	}
	if(v==n/2){
		if(ss==s && tt==t){
			ans++;
		}
		if(cc>0)vec[k-cc].push_back(P(ss,tt));
		return;
	}
	dfs(v+1,ss,tt,cc);
	if(cc==0){
		dfs(v+1,c[v],c[v],cc+1);
	}else{
		dfs(v+1,ss&c[v],tt|c[v],cc+1);
	}
}

void dfs2(int v,int ss,int tt,int cc){
	if(tt>t || cc>k){
		return;
	}
	if(v==n){
		if(ss==s && tt==t){
			ans++;
		}
		if(cc==0)return;
		for(int i=cc;i<=k;i++){
			for(int j=0;j<vec[i].size();j++){
				if((ss&vec[i][j].first)==s && (tt|vec[i][j].second)==t){
					ans++;
				}
			}
		}
		return;
	}
	dfs2(v+1,ss,tt,cc);
	if(cc==0){
		dfs2(v+1,c[v],c[v],cc+1);
	}else{
		dfs2(v+1,ss&c[v],tt|c[v],cc+1);
	}
}

