int N, K, S, T, A[MN], part[MV];

int main() {
	scanf("%d%d%d%d", &N, &K, &S, &T);
	for (int i = 1; i <= N; ++i) {
		scanf("%d", &A[i]);
		if ((A[i] & S) != S || (A[i] | T) != T) {
			--i, --N;
			continue;
		}
	}
	for (int i = 0; i <= N; ++i) {
		Binom[i][0] = 1;
		for (int j = 1; j <= i; ++j)
			Binom[i][j] = Binom[i - 1][j - 1] + Binom[i - 1][j];
	}
	for (int i = 0; i <= N; ++i)
		for (int j = 2; j <= K; ++j)
			Binom[i][j] += Binom[i][j - 1];
	for (int X = 0; X < MV; ++X) {
		if ((X & S) != S || (X | T) != T) continue;
		LL Sum = 0;
		for (int i = 1; i <= N; ++i) ++part[A[i] & X];
