using namespace std;

const int N = 55, L = 18;

int n, k, len, s, t, a[N], popcount[1 << L], cnt = 0;
map<pair<int, int>, int> mp;
unsigned long long coef[N], c[N][N], ans = 0ull;

int lowbit (int x) {
	return x & -x;
}

int main () {
	scanf("%d%d%d%d", &n, &k, &s, &t);
	len = 0;
	if ((s & t) != s) {
		puts("0");
		return 0;
	}
	for (int i = (t ^ s); i; i ^= lowbit(i)) len++;

	for (int i = 1; i <= n; i++) {
		int x;
		scanf("%d", &x);
		if ((x & s) != s) continue;
		if ((x & t) != x) continue;
		a[cnt] = 0;
		for (int j = (t ^ s), k = 0; j; j ^= lowbit(j), k++) {
			if (x & lowbit(j)) a[cnt] |= (1 << k);
		}
		cnt++;
	}

	for (int i = 0; i < cnt; i++) debug(i), debug(a[i]);
	int U = (1 << len) - 1;
	popcount[0] = 0;
	for (int i = 1; i <= U; i++) popcount[i] = popcount[i >> 1] + (i & 1);
	for (int i = 0; i < cnt; i++) {
		int b = U ^ a[i];
		for (int j = a[i]; ; j = (j - 1) & a[i]) {
			for (int k = b; ; k = (k - 1) & b) {
				mp[make_pair(j, a[i] | k)]++;
				if (!k) break;
			}
			if (!j) break;
		}
	}
	for (int i = 0; i <= n; i++) coef[i] = 0ull, c[i][0] = c[i][i] = 1ull;
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j < i; j++) c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
	}
	for (map<pair<int, int>, int> :: iterator it = mp.begin(); it != mp.end(); it++) {
		int s1 = it -> first.first, s2 = it -> first.second;
		if ((popcount[s1] + popcount[s2] + len) & 1) coef[it -> second]--;
		else coef[it -> second]++;
	}

	for (int i = 1; i <= k; i++) {
		for (int j = i; j <= n; j++) ans += coef[j] * c[j][i];
	}
	printf("%llu\n", ans);
	return 0;
}

