	//積集合で条件が与えられたとき、和集合の条件を返す
	dp[0]=0;
	rep(k,0,N)rep(j,0,1<<N)if(bit(j,k))dp[j]-=dp[j^(1<<k)];
	rep(j,0,1<<N)if(!__builtin_parity(j))dp[j]*=-1;
