import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.*

fun main() {
    val jin = BufferedReader(InputStreamReader(System.`in`))
    val (n, k, s, t) = jin.readLine().split(" ").map { it.toInt() }
    val choose = Array(n + 1) { LongArray(n + 1) }
    choose[0][0] = 1L
    for (a in 1..n) {
        choose[a][0] = 1L
        choose[a][a] = 1L
        for (b in 1 until a) {
            choose[a][b] = choose[a - 1][b] + choose[a - 1][b - 1]
        }
    }
    val chooseSums = LongArray(n + 1)
    for (a in 0..n) {
        for (b in 1..k) {
            chooseSums[a] += choose[a][b]
        }
    }
    val tokenizer = StringTokenizer(jin.readLine())
    val array = IntArray(n) { tokenizer.nextToken().toInt() }
    val addends = mutableListOf<Pair<Int, Long>>()
    for (mask in 0 until (1 shl 18)) {
        if ((mask and s) == s && (mask or t) == t) {
            val groups = mutableMapOf<Int, Int>()
            for (a in array) {
                if ((a and s) == s && (a or t) == t) {
                    groups[a and mask] = (groups[a and mask] ?: 0) + 1
                }
            }
            var local = 0L
            for (amt in groups.values) {
                local += chooseSums[amt]
            }
            addends.add(Pair(Integer.bitCount(mask xor s), local))
        }
    }
    var answer = 0L
    addends.sortBy { it.first }
    for (addend in addends) {
        if (addend.first % 2 == 0) {
            answer += addend.second
        } else {
            answer -= addend.second
        }
    }
    println(answer)
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class Main {
    long[][] c = new long[51][51];

    void solve(Scanner sc, PrintWriter pw) {
        int N = sc.nextInt();
        int K = sc.nextInt();
        long S = sc.nextLong();
        long T = sc.nextLong();
        long[] data = new long[N];
        for (int i = 0; i < N; i++) {
            data[i] = sc.nextLong();
        }
        for (int i = 0; i <= N; i++) {
            c[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
            }
        }
        long[] sum = new long[(N + 1)];
        for (int i = 1; i <= N; i++) {
            for (int j = 1; j <= Math.min(i, K); j++) {
                sum[i] += c[i][j];
            }
        }
        long result = 0;
        List<Long> nums = new ArrayList<>();
        for (long mask = 0; mask < (1L << 18); mask++) {
            if (((T ^ S) & mask) != mask) {
                continue;
            }
            boolean isAdd = (Long.bitCount(mask) % 2) == 0;
            nums.clear();
            for (int i = 0; i < N; i++) {
                if ((data[i] & S) != S) {
                    continue;
                }
                if ((data[i] | T) != T) {
                    continue;
                }
                nums.add(data[i] & mask);
            }
            Collections.sort(nums);
            int begin = 0;
            int nextBegin;
            while (begin < nums.size()) {
                nextBegin = begin + 1;
                while (nextBegin< nums.size() && nums.get(nextBegin).equals(nums.get(nextBegin - 1))) {
                    nextBegin++;
                }
                result += (isAdd ? 1L : -1L) * (sum[nextBegin - begin]);
                begin = nextBegin;
            }
        }
        pw.println(String.format("%d", result));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        new Main().solve(sc, pw);
        pw.flush();
        pw.close();
        sc.close();
    }
}

