import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni(), K = ni(), S = ni(), T = ni();
		int[] a = na(n);
		if((S&T) != S){
			out.println(0);
			return;
		}
		int m = Integer.bitCount(T) - Integer.bitCount(S);

		int p = 0;
		for(int i = 0;i < n;i++){
			if((a[i]&S) == S && (a[i]&~T) == 0){
				int v = 0;
				int q = 0;
				for(int j = 0;j < 18;j++){
					if(S<<~j>=0 && T<<~j<0){
						v |= (a[i]>>>j&1)<<q;
						q++;
					}
				}
				a[p++] = v;
			}
		}
		a = Arrays.copyOf(a, p);

		// 0,1,2:3
		// 00
		// 01
		// 10


		long[][] C = new long[51 + 1][51 + 1];
		for (int i = 0; i <= 51; i++) {
			C[i][0] = 1;
			for (int j = 1; j <= i; j++) {
				C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
			}
		}

		long[] hs = new long[m+1];
		long ans = 0;
		for(int i = 0;i < 1<<m;i++){
			int[] f = new int[p];
			for(int j = 0;j < p;j++){
				f[j] = a[j]&i;
			}
			Arrays.sort(f);

			long flip = 0;
			for(int j = 0;j < p;){
				int k = j;
				while(k < p && f[j] == f[k])k++;

				for(int o = 2;o <= K;o++){
					flip += C[k-j][o];
				}

				j = k;
			}

			int bc = Integer.bitCount(i);
			if(bc % 2 == 0){
				ans += flip;
			}else{
				ans -= flip;
			}
			hs[bc] += flip;
		}
		out.println(ans);
	}

	public static int lowerBound(int[] a, int v){ return lowerBound(a, 0, a.length, v); }
	public static int lowerBound(int[] a, int l, int r, int v)
	{
		if(l > r || l < 0 || r > a.length)throw new IllegalArgumentException();
		int low = l-1, high = r;
		while(high-low > 1){
			int h = high+low>>>1;
			if(a[h] >= v){
				high = h;
			}else{
				low = h;
			}
		}
		return high;
	}


