public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        EOrand solver = new EOrand();
        solver.solve(1, in, out);
        out.close();
    }

    static class EOrand {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int n, max, m = 0;
            int[] a;
            {
                int n0 = in.ints();
                max = in.ints();
                int s = in.ints(), t = in.ints();
                int[] a0 = in.ints(n0);
                a = new int[n0];
                n = 0;
                for (int i = 0; i < 18; i++) {
                    if (((s >> i) & 1) == 1 || ((t >> i) & 1) == 0) continue;
                    m++;
                }
                for (int i = 0; i < n0; i++) {
                    if ((a0[i] & s) != s || (a0[i] | t) != t) continue;
                    int tmp = 0, bit = 1;
                    for (int j = 0; j < 18; j++) {
                        if (((s >> j) & 1) == 1 || ((t >> j) & 1) == 0) continue;
                        if (((a0[i] >> j) & 1) == 1) tmp |= bit;
                        bit <<= 1;
                        if (bit > 1 << 12) break;
                    }
                    a[n++] = tmp;
                }
                if (n == 0) {
                    out.ans(0).ln();
                    return;
                }
            }

            long[][] comb = new long[51][51];
            long[] coeff = new long[51];
            for (int i = 0; i <= 50; i++) comb[i][0] = 1;
            for (int i = 1; i <= 50; i++) comb[i][i] = 1;
            for (int i = 1; i <= 50; i++) {
                for (int j = 1; j < i; j++) {
                    comb[i][j] = comb[i - 1][j] + comb[i - 1][j - 1];
                }
            }
            for (int i = 0; i <= 50; i++) {
                for (int j = 0; j <= max && j <= i; j++) {
                    coeff[i] += comb[i][j];
                }
            }


            //System.out.println(Arrays.toString(coeff));
            long ans = coeff[n] - 1;
            int all = 1 << m;
            for (int i = 0; i < n; i++) {
                long d = 0;
                for (int j = 1; j < all; j++) {
                    int count = 0;
                    for (int k = i + 1; k < n; k++) {
                        if ((j & (a[i] ^ a[k])) == 0) count++;
                    }
                    //System.out.println(i + "," + Integer.toBinaryString(j) + "," + count);
                    if ((Integer.bitCount(j) & 1) == 1) d += coeff[count];
                    else d -= coeff[count];
                }
                //System.out.println("= " + i + "," + d);
                ans -= d;
            }
            out.ans(ans).ln();
        }

    }

