                result += (isAdd ? 1L : -1L) * (sum[nextBegin - begin]);
                begin = nextBegin;
            }
        }
        pw.println(String.format("%d", result));
    }

    private int countBit(long mask) {
        int result = 0;
        while (mask > 0) {
            result += (mask & 1);
            mask >>= 1;
        }
        return result;
    }

