    static class EOrand {
        Debug debug = new Debug(false);
        int k;
        long[][] comb = new long[100][100];
        int[] a;

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            k = in.readInt();
            int s = in.readInt();
            int t = in.readInt();
            IntegerList list = new IntegerList(n);
            for (int i = 0; i < n; i++) {
                int x = in.readInt();
                if ((x & s) != s || (x | t) != t) {
                    continue;
                }
                list.add(x);
            }

            a = list.toArray();
            n = a.length;

            SequenceUtils.deepFill(comb, -1L);

            int[] clone = a.clone();
            int mask = (1 << 18) - 1;

            long ans = 0;
            for (int i = 0; i < n; i++) {
                int reqOne = t - clone[i];
                int reqZero = (clone[i]) & (mask ^ s);
                int req = reqOne | reqZero;

                a = Arrays.copyOfRange(clone, i + 1, clone.length);
                for (int j = 0; j < a.length; j++) {
                    a[j] = (a[j] & reqOne) | (~a[j] & reqZero);
                }

                long local = 0;
                SubsetGenerator sg = new SubsetGenerator();
                sg.reset(req);

                while (sg.hasNext()) {
                    int next = sg.next();
                    local += ie(next);
                }

                ans += local;
                debug.debug("local", local);
            }

            out.println(ans);
        }

        public long ie(int set) {
            int cnt = 0;
            for (int x : a) {
                if ((x & set) == 0) {
                    cnt++;
                }
            }
            long ans = 0;
            for (int j = 0, min = Math.min(k - 1, cnt); j <= min; j++) {
                ans += comb(cnt, j);
            }
            if (Integer.bitCount(set) % 2 == 1) {
                ans = -ans;
            }
            return ans;
        }

        public long comb(int n, int m) {
            if (comb[n][m] == -1) {
                if (m > n) {
                    return comb[n][m] = 0;
                }
                if (m == 0) {
                    return comb[n][m] = 1;
                }
                comb[n][m] = comb(n - 1, m) + comb(n - 1, m - 1);
            }
            return comb[n][m];
        }

    }

    static class IntegerList implements Cloneable {
        private int size;
        private int cap;
        private int[] data;
        private static final int[] EMPTY = new int[0];

        public IntegerList(int cap) {
            this.cap = cap;
            if (cap == 0) {
                data = EMPTY;
            } else {
                data = new int[cap];
            }
        }

        public IntegerList(IntegerList list) {
            this.size = list.size;
            this.cap = list.cap;
            this.data = Arrays.copyOf(list.data, size);
        }

        public IntegerList() {
            this(0);
        }

        public void ensureSpace(int req) {
            if (req > cap) {
                while (cap < req) {
                    cap = Math.max(cap + 10, 2 * cap);
                }
                data = Arrays.copyOf(data, cap);
            }
        }

        public void add(int x) {
            ensureSpace(size + 1);
            data[size++] = x;
        }

        public void addAll(int[] x, int offset, int len) {
            ensureSpace(size + len);
            System.arraycopy(x, offset, data, size, len);
            size += len;
        }

        public void addAll(IntegerList list) {
            addAll(list.data, 0, list.size);
        }

        public int[] toArray() {
            return Arrays.copyOf(data, size);
        }

        public String toString() {
            return Arrays.toString(toArray());
        }

        public boolean equals(Object obj) {
            if (!(obj instanceof IntegerList)) {
                return false;
            }
            IntegerList other = (IntegerList) obj;
            return SequenceUtils.equal(data, 0, size - 1, other.data, 0, other.size - 1);
        }

        public int hashCode() {
            int h = 1;
            for (int i = 0; i < size; i++) {
                h = h * 31 + Integer.hashCode(data[i]);
            }
            return h;
        }

        public IntegerList clone() {
            IntegerList ans = new IntegerList();
            ans.addAll(this);
            return ans;
        }

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput append(CharSequence csq) {
            cache.append(csq);
            return this;
        }

        public FastOutput append(CharSequence csq, int start, int end) {
