        long res = 0;
        for (int m = 0; m < dp.Length; m++)
        {
            if ((PopCount(m) & 1) == 1)
                res -= dp[m];
            else
                res += dp[m];
        }
        return res;
    }
    int blen;
    int bx;
    int[] Compress(int[] A)
