{
    public static string Result(double d) => d.ToString("0.####################", System.Globalization.CultureInfo.InvariantCulture);
    #endregion
    public static string Result(bool b) => b ? "Yes" : "No";
    private object Calc()
    {
        N = cr;
        K = cr;
        S = cr;
        T = cr;
        A = cr.Repeat(N).Int.Where(num => (num & S) == S && (num | T) == T).ToArray();
        N = A.Length;
        K.UpdateMin(N);
        if (N == 0) return 0;
        try
        {
            A = Compress(A).Sort(rcmp);
        }
        catch (Exception)
        {
            return 0;
        }
        blen = MSB(A[0]) + 1;
        bx = (1 << blen);
        var cx = new long[bx];
        var dx = new Dictionary<int, int>[bx];
        foreach (var (_, c) in (dx[^1] = A.GroupCount()))
            for (int k = 1; k <= K; k++)
                cx[^1] += Combination(c, k);
        for (int m = cx.Length - 2; m >= 0; m--)
        {
            var prv = dx[1 << LSB(~m) | m];
            var dic = dx[m] = new Dictionary<int, int>();
            foreach (var (k, c) in prv)
                dic[k & m] = dic.Get(k & m) + c;

            foreach (var (_, c) in dic)
                for (int k = 1; k <= K; k++)
                    cx[m] += Combination(c, k);
        }
        long res = 0;
        for (int m = 0; m < cx.Length; m++)
        {
            if ((PopCount(m) & 1) == 1)
                res -= cx[m];
            else
                res += cx[m];
        }
        return res;
    }
    int blen;
    int bx;
    int[] Compress(int[] A)
    {
        var ix = 1;
        var res = new int[A.Length];
        for (int x = 0; x < 18; x++)
            if (!S.On(x) && T.On(x))
            {
                for (int i = 0; i < A.Length; i++)
                    if (A[i].On(x))
                        res[i] |= ix;
                ix <<= 1;
            }
            else if (S.On(x) && !T.On(x))
                throw new Exception();
        return res;
    }
    static IComparer<int> rcmp = ReverseComparer<int>.Default;
    int N;
    int K;
    int S;
    int T;
    int[] A;
    long[][] cache = new long[51][];
    long Combination(int n, int k)
    {
        if (k > n)
            return 0;
        if (k == 0 || k == n)
            return 1;
        if (cache[n] == null)
            cache[n] = new long[n + 1];
        if (cache[n][k] == 0)
            cache[n][k] = Combination(n - 1, k) + Combination(n - 1, k - 1);
        return cache[n][k];
    }

}

