using static System.Math;
public static class P
{
    public static void Main()
    {
        var nkst = Console.ReadLine().Split().Select(int.Parse).ToArray();
        var n = nkst[0];
        var K = nkst[1];
        var s = nkst[2];
        var t = nkst[3];
        var a = Console.ReadLine().Split().Select(int.Parse).ToArray();
        //全部が混血→なにかが純血なものの余事象
        //18bitのうち、純血のbitを定める→だめ
        //ある場所始点とすると、

        List<int> needInd = Enumerable.Range(0, 18).ToList();
        for (int i = 0; i < 18; i++)
        {
            var and = (s >> i & 1);
            var or = (t >> i & 1);
            if (and == or)
            {
                var bit = and;
                a = a.Where(x => (x >> i & 1) == bit).ToArray();
                needInd.Remove(i);
            }
        }

        a = a.Select(x =>
        {
            var binstr = Convert.ToString(x, 2);
            var removedbinstr = string.Join("", binstr.Reverse().Where((_, ind) => needInd.Contains(ind)).Reverse());
            return removedbinstr.Length == 0 ? 0 : Convert.ToInt32(removedbinstr, 2);
        }).ToArray();

        return;

        var max = 1 << needInd.Count;
        long res = 0;
        for (int i = 0; i < a.Length; i++)
        {
            var bits = Max(K, needInd.Count);
            var begin = a[i];
            long[][] dp = Enumerable.Repeat(0, max).Select(_ => new long[bits]).ToArray();
            dp[0][0] = 1;
            for (int j = i + 1; j < a.Length; j++)
            {
                //同じだったらアレできない 違ったらいける
                var mask = begin ^ a[j];
                for (int k = dp.Length - 1; k >= 0; k--)
                {
                    for (int l = dp[k].Length - 2; l >= 0; l--)
                    {
                        dp[k | mask][l + 1] += dp[k][l];
                    }
                }
            }
            res += dp.Last().Sum();
        }
        Console.WriteLine(res);
    }
}

