					if ((S >> j & 1) == 0 && (a[i] >> j & 1) == 1) needZ |= 1 << j;
					if ((T >> j & 1) == 1 && (a[i] >> j & 1) == 0) needO |= 1 << j;
				}
				dp[1][0] = 1;
				// Debug.WriteLine($"{i} {needZ} {needO}");
				for (int j = i + 1; j < n; j++) {
					var addmask = (a[j] & needO) | ((~a[j]) & needZ);
					for (int l = k - 1; l >= 0; l--)
						for (int mask = (1 << M) - 1; mask >= 0; mask--) if (dp[l][mask] != 0) {
								dp[l + 1][mask | addmask] += dp[l][mask];
							}
				}
				for (int l = 1; l <= k; l++)
					ans += dp[l][needO | needZ];
			}
			Console.WriteLine(ans);
		}
