    private object Calc()
    {
        N = cr;
        K = cr;
        S = cr;
        T = cr;
        A = cr.Repeat(N).Int.Where(num => (num & S) == S && (num | T) == T).ToArray();
        N = A.Length;
        K.UpdateMin(N);
        if (N == 0) return 0;
        try
        {
            A = Compress(A).Sort(rcmp);
        }
        catch (Exception)
        {
            return 0;
        }
        blen = MSB(A[0]) + 1;
        bx = (1 << blen);
        var cx = new long[bx];
        var dx = new Dictionary<int, int>[bx];
        foreach (var (_, c) in (dx[^1] = A.GroupCount()))
            cx[^1] += SumComb(c);
        for (int m = cx.Length - 2; m >= 0; m--)
        {
            var prv = dx[1 << LSB(~m) | m];
            var dic = dx[m] = new Dictionary<int, int>();
            foreach (var (k, c) in prv)
                dic[k & m] = dic.Get(k & m) + c;

            foreach (var (_, c) in dic)
                cx[m] += SumComb(c);
        }
        long res = 0;
        for (int m = 0; m < cx.Length; m++)
        {
            if ((PopCount(m) & 1) == 1)
                res -= cx[m];
            else
                res += cx[m];
        }
        return res;
    }
    int blen;
    int bx;
    int[] Compress(int[] A)
    {
        var ix = 1;
        var res = new int[A.Length];
        for (int x = 0; x < 18; x++)
            if (!S.On(x) && T.On(x))
            {
                for (int i = 0; i < A.Length; i++)
                    if (A[i].On(x))
                        res[i] |= ix;
                ix <<= 1;
            }
            else if (S.On(x) && !T.On(x))
                throw new Exception();
        return res;
    }
