    long SumComb(int n)
    {
        if (scache[n] == 0)
            for (int k = 1; k <= K; k++)
                scache[n] += Combination(n, k);
        return scache[n];
    }
    long Combination(int n, int k)
    {
        if (k > n)
            return 0;
        if (k == 0 || k == n)
            return 1;
        if (cache[n] == null)
            cache[n] = new long[n + 1];
        if (cache[n][k] == 0)
            cache[n][k] = Combination(n - 1, k) + Combination(n - 1, k - 1);
