const MAX: usize = (1<<18)-1;
//const MASK: usize = (1<<2)-1;

fn main() {
    input! {
        n: usize, K: usize, s: usize, t: usize,
        a: [usize; n]
    };
    if s & t != s {
        println!("0");
        return;
    }
    let mut mask = 0;
    for i in 0..18 {
        if s & (1<<i) == 0 && t & (1<<i) >= 1 {
            mask |= 1<<i;
        }
    }

    let a = a.into_iter().filter(|a| a & s == s && a | t == t).collect::<Vec<_>>();
    let n = a.len();
    // debug!(a);

    let mut comb = dvec![0i64; n+1, n+1];
    for i in 0..=n {
        comb[i][0] = 1;
        comb[i][i] = 1;
        for j in 1..i {
            comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
        }
    }

    let mut total = 0;
    for i in 0..n {
        for ptn in 0..=MAX {
            if ptn & mask != ptn {
                continue;
            }
            let mut ok_cnt = 0;
            for j in i+1..n {
                if (a[i] ^ a[j]) & ptn == 0 {
                    ok_cnt += 1;
                }
            }
            let mut add = 0;
            for w in 0..=K-1 {
                add += comb[ok_cnt][w];
            }
            total += ifv!(ptn.count_ones() % 2 == 0, add, -add);
        }
    }
    println!("{}", total);
}

