fn main() {
    #[allow(unused_imports)]
    use std::io::Write as _;
    let __out = std::io::stdout();
    #[allow(unused_mut, unused_variables)]
    let mut __out = std::io::BufWriter::new(__out.lock());
    #[allow(unused_macros)]
    macro_rules !print {($($arg :tt ) *) =>(::std ::write !(__out ,$($arg ) *) .unwrap () ) }
    #[allow(unused_macros)]
    macro_rules !println {($($arg :tt ) *) =>(::std ::writeln !(__out ,$($arg ) *) .unwrap () ) }
    #[allow(unused_macros)]
    macro_rules! echo {
        ($iter :expr ) => {
            echo!($iter, "\n")
        };
        ($iter :expr ,$sep :expr ) => {
            let mut iter = $iter;
            if let Some(item) = iter.next() {
                print!("{}", item);
            }
            for item in iter {
                print!("{}{}", $sep, item);
            }
            println!();
        };
    }
    input!(n, k, s: usize, t: usize, a: [usize; n]);
    const B: usize = 18;
    let a: Vec<_> = a
        .into_iter()
        .filter(|&x| s & x == s && t | x == t)
        .collect();
    let mut ans = 0i64;
    let mut comb = vec![vec![0; n + 2]; n + 2];
    comb[0][0] = 1i64;
    for i in 0..=n {
        for j in 0..=i {
            comb[i + 1][j] += comb[i][j];
            comb[i + 1][j + 1] += comb[i][j];
        }
    }
    for i in 0..=n {
        for j in 1..=n {
            comb[i][j + 1] += comb[i][j];
        }
    }
    for i in 0usize..1 << B {
        if s & i == s && t | i == t {
            let c = (-1i64).pow((i ^ s).count_ones());
            let mut mp = std::collections::HashMap::new();
            for &x in a.iter() {
                *mp.entry(x & i).or_insert(0) += 1;
            }
            for &v in mp.values() {
                ans += c * comb[v][k];
            }
        }
    }
    println!("{}", ans);
}

#[allow(unused_imports)]
use std::cmp::{max, min};
use std::io::{stdin, Read};

#[allow(unused_macros)]
macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: ty),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, u1) => {
        $it.next().unwrap().parse::<usize>().unwrap() -1
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, k: u32, s: usize, t: usize, a: [usize; n]);
    if t & s != s {
        println!("{}", 0);
        return;
    }
    let a: Vec<_> = a
        .into_iter()
        .filter(|ai| ai & s == s && ai | t == t)
        .collect();
    let n = a.len();
    let mut ret = 0;
    let dt: Vec<_> = (0..18usize)
        .filter(|i| (s >> i) & 1 == 0 && (t >> i) & 1 == 1)
        .collect();
    let m = dt.len();
    let mut targets = vec![];
    let mut csets = vec![];
    for i in 0..n {
        targets.clear();
        for &j in dt.iter() {
            targets.push((a[i] >> j) & 1)
        }

        csets.clear();
        for j in 0..m {
            let ti = dt[j];
            csets.push(0);
            for k in (i + 1)..n {
                if (a[k] >> ti) & 1 == targets[j] {
                    csets[j] |= 1 << k;
                }
            }
        }

        let mut cnum = 0i64;
        for sub in 0usize..(1 << m) {
            let mut iset = !0usize;
            for j in (0..m).filter(|j| (sub >> j) & 1 == 1) {
                iset &= csets[j];
            }
            if iset == !0usize {
                continue;
            }
            let c = sumcomb(iset.count_ones() as usize, k as usize - 1) as i64;
            if sub.count_ones() % 2 == 1 {
                cnum += c;
            } else {
                cnum -= c;
            }
        }
        cnum = max(cnum, 1);
        let a = sumcomb(n - 1 - i, (k - 1) as usize);
        ret += a - cnum as usize;
    }
    println!("{}", ret);
}
fn sumcomb(m: usize, n: usize) -> usize {
    (0..=n).map(|i| comb(m, i)).sum()
}
fn comb(m: usize, n: usize) -> usize {
    if m < n {
        return 0;
    }
    let mut ret = 1;
    for i in (m - n)..m {
        ret *= i + 1;
    }
    for i in 0..n {
        ret /= i + 1
    }
    ret
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

