use proconio::*;

fn run() {
    input! {
        n: usize,
        k: usize,
        s: usize,
        t: usize,
        a: [usize; n],
    }
    let a: Vec<usize> = a.into_iter().filter(|a| a & s == s && a | t == t).collect();
    if a.is_empty() || s & t != s {
        println!("0");
        return;
    }
    let mut comb = vec![vec![0i64; n + 1]; n + 1];
    comb[0][0] = 1;
    for i in 1..=n {
        comb[i][0] = 1;
        for j in 1..=i {
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
        }
    }
    let mut bit = vec![];
    for i in 0..18 {
        if (s >> i) & 1 != (t >> i) & 1 {
            bit.push(i);
        }
    }
    let n = std::cmp::min(n, a.len());
    let k = std::cmp::min(k, n);
    let mut cnt = vec![0; 1 << 18];
    let mut ans = 0i64;
    for b in 0..(1usize << bit.len()) {
        let sign = if b.count_ones() % 2 == 0 {1} else {-1};
        let mut mask = 0;
        for (i, &x) in bit.iter().enumerate() {
            if (b >> i) & 1 == 1 {
                mask |= 1 << x;
            }
        }
        for a in a.iter() {
            cnt[*a & mask] += 1;
        }
        for a in a.iter() {
            let x = *a & mask;
            if cnt[x] == 0 {
                continue;
            }
            let v = cnt[x];
            cnt[x] = 0;
            for c in comb[v].iter().skip(1).take(std::cmp::min(v, k)) {
                ans += sign * *c;
            }
        }
    }
    println!("{}", ans);
}

fn main() {
    run();
}

