use std::io::*;
use std::str::FromStr;
// ABC086C - Traveling
// https://atcoder.jp/contests/abs/fasks/arc089_a

fn switch<T>(flag: bool, t: T, f: T) -> T {
    if flag {
        t
    } else {
        f
    }
}

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}
#[allow(dead_code)]
fn read_string() -> Vec<char> {
    read::<String>().chars().collect()
}
#[allow(dead_code)]
fn read_vector<T: FromStr>(number: usize) -> Vec<T> {
    (0..number).map(|_| read()).collect()
}

fn main() {
    let (n, k, s, t): (usize, usize, u32, u32) = (read(), read(), read(), read());
    let list: Vec<u32> = read_vector(n);

    //候補の作成 O(n)
    let mut candidate = list.clone();
    for i in 0..18 {
        let mask = 1 << i;
        //and
        if (s & mask) != 0 {
            candidate.retain(|x: &u32| x & mask != 0);
        }
        //or
        if (t & mask) == 0 {
            candidate.retain(|x: &u32| x & mask == 0);
        }
    }
    //条件を満たし続ける間探索

    let mut stack = VecDeque::new();
    let mut log = HashSet::new();
    let mut sum = 0;

    let btree: BTreeSet<_> = candidate.iter().collect();
    stack.push_back(btree);

    while let Some(list) = stack.pop_back() {
        //条件を満たしているか?
        let mut ss = !0;
        let mut tt = 0;
        for item in list.iter() {
            ss &= *item;
            tt |= *item;
        }
        if ss == s && tt == t {
            if list.len() <= k {
                sum += 1;
            }
            println!("{:?}", list);
            for item in list.iter() {
                let mut tmp: BTreeSet<_> = list.clone();
                tmp.remove(*item);
                if !log.contains(&tmp) {
                    stack.push_back(tmp.clone());
                    log.insert(tmp);
                }
            }
        }
    }
    println!("{}", sum);
}

use proconio::input;
use std::collections::HashMap;

fn main() {
    input! {
        n: usize, k: usize, s: usize, t: usize,
        a: [usize; n]
    }
    let mut dp = vec![HashMap::new(); k + 1];
    dp[0].insert(((1 << 18) - 1, 0), 1);
    for &a in &a {
        for i in (0..k).rev() {
            let mut ins = Vec::new();
            for (&(x, y), &p) in &dp[i] {
                let x = x & a;
                let y = y | a;
                if x & s != s || y | t != t {
                    continue;
                }
                ins.push(((x, y), p));
            }
            for (xy, p) in ins {
                *dp[i + 1].entry(xy).or_insert(0) += p;
            }
        }
    }
    let ans: u64 = (1..=k).filter_map(|i| dp[i].get(&(s, t))).sum();
    println!("{}", ans)
}

use proconio::input;

fn main() {
    input! {
        n: usize,
        k: usize,
        s: usize,
        t: usize,
        a: [usize; n]
    };
    let b = a.iter().filter(|&v| v&s == s && v|t == t ).map(|&v| v^s).collect::<Vec<usize>>();
    let mut comb = [[0 as i64; 51]; 51];
    let mut valid = [0; 51];
    for i in 1..=50 {
        comb[i][0] = 1;
        for j in 1..i {
            comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
        }
        comb[i][i] = 1;
        for j in 1..=std::cmp::min(i, k) {
            valid[i] += comb[i][j];
        }
    }
    let mut res = valid[b.len()];
    let mut cnt = [0; 1<<18];
    let mask = t^s;
    for i in 1..1<<18 {
        if i|mask != mask { continue }
        let sgn = if i.count_ones()%2 == 1 { -1 } else { 1 };
        for &v in &b { cnt[v&i] += 1; }
        for &v in &b {
            if cnt[v&i] == 0 { continue }
            res += sgn * valid[cnt[v&i]];
            cnt[v&i] = 0;
        }
    }
    println!("{}", res);
}

use proconio::*;

fn run() {
    input! {
        n: usize,
        k: usize,
        s: usize,
        t: usize,
        a: [usize; n],
    }
    let a: Vec<usize> = a.into_iter().filter(|a| a & s == s && a | t == t).collect();
    if a.is_empty() || s & t != s {
        println!("0");
        return;
    }
    let mut dp = vec![std::collections::BTreeMap::new(); k + 1];
    dp[0].insert((!0usize, 0usize), 1u64);
    let mut memo = vec![];
    for a in a {
        for i in (0..k).rev() {
            memo.clear();
            for (&(and, or), &cnt) in dp[i].iter() {
                let and = a & and;
                let or = a | or;
                memo.push((and, or, cnt));
            }
            let dp = &mut dp[i + 1];
            for &(and, or, cnt) in memo.iter() {
                *dp.entry((and, or)).or_insert(0) += cnt;
            }
        }
    }
    let mut ans = 0;
    for dp in dp {
        ans += dp.get(&(s, t)).cloned().unwrap_or(0);
    }
    println!("{}", ans);
}

fn main() {
    run();
}
